INSERT INTO `bimbingan` VALUES (3, 8, 5, '2016-02-16', 'Hari ini dilaksanakan perguliran ke Kelompok Bunga dahlia dengan Jumlah 40.000.000,- Perguliran dilaksanakan oleh UPK yang dihadiri oleh Tim Verifikasi dan Anggota Kelompok Pemanfaat. dilaksanakan di rumah ketua Kelompok', 1);
INSERT INTO `bimbingan` VALUES (4, 4, 4836, '2016-02-18', 'Proses identifikasi kelompok sedang berjalan, dimungkinkan terdapat kelompok ganda yang masih memiliki pinjaman', 79);
INSERT INTO `bimbingan` VALUES (5, 1, 48, '2016-02-19', 'Kelompok bagus', 241);
INSERT INTO `bimbingan` VALUES (6, 4, 4758, '2016-02-22', 'Kelompok lama, supaya dilakukan pendataan ulang atas data tunggakan yang ada. kalau ada peminjam yang terdaftar meninggal bisa dilakukan pemberian dana sosial', 130);
INSERT INTO `bimbingan` VALUES (7, 4, 237, '2016-02-23', 'Pencairan Rp. 31.000.000', 54);
INSERT INTO `bimbingan` VALUES (8, 8, 42, '2016-02-24', 'Klp. Sipaurangi Banyorang telah masuk kolektibilitas V (lima). Tunggakan tersebut sebesar Pokok Rp. 25.019.100,- dan Bunga Rp. 0,-. tunggakan tersebut murni mejadi tunggakan ketua kelompok an. SAHARI. tunggakan tersebut dipergunakan oleh yang bersangkutan secara pribadi.', 1);
INSERT INTO `bimbingan` VALUES (9, 4, 4765, '2016-02-24', 'Kelompok sejahtera abadi sudah mulai merintis berdirinya koperasi, dan tahun 2015 sudah berbadan hukum. kegiatan usahanya perlu dicontoh oleh kelompok lainnya.', 130);
INSERT INTO `bimbingan` VALUES (10, 8, 81, '2016-02-25', 'Adanya tunggakan yang tinggal di ketua kelompok.Dan akan di lunasi akhir bulan pebruari', 3);
INSERT INTO `bimbingan` VALUES (11, 4, 4693, '2016-03-02', 'Data identitas klp tdk bisa dirubah', 130);
INSERT INTO `bimbingan` VALUES (12, 4, 4508, '2016-03-23', 'Angsuran sering tidak target, diupayakan saat jatuh tempo bulan april bisa lunas tanpa tunggakan', 130);
INSERT INTO `bimbingan` VALUES (13, 4, 4508, '2016-03-23', 'Angsuran sering tidak target, diupayakan saat jatuh tempo bulan april bisa lunas tanpa tunggakan', 130);
INSERT INTO `bimbingan` VALUES (14, 4, 4506, '2016-03-23', 'Pengajuan kembali berguliran 50 juta, dilihat kembali data peminjamnya. apakah ada peminjam yang blm lunas. verifikasi kembali lebih teliti supaya kedepan kelompok ini angsurannya lancar.', 130);
INSERT INTO `bimbingan` VALUES (15, 4, 4953, '2016-03-23', 'Pencairan perguliran sdh dilaksanakan. ada peminjam yang bekerja di cirebon bersama keluarga. dia sanggup membayar rutin setiap bulan dengan cara kirim uang ke ibunya. sedangkan ibunya sendiri juga pinjam di kelompok yang sama, perlu dipantau perkembangan kedepan', 130);
INSERT INTO `bimbingan` VALUES (16, 4, 4981, '2016-03-23', 'kelompok baru usaha maju, semoga maju dan berjaya di ngawen', 130);
INSERT INTO `bimbingan` VALUES (17, 1, 7, '2016-04-03', 'kelompok ini sudah siap untuk mengembangkan usahanya. sang', 242);
INSERT INTO `bimbingan` VALUES (18, 1, 3, '2016-04-03', 'KELOMPOK PG. GATUTKACA TANI TIDAK MEMILIKI SISTEM ORGANISASI TETAP SEHINGGA BEBAN TANGGUNGJAWAB TIDAK SEIMBANG.', 241);
