INSERT INTO `bimbingan` VALUES (28, 4, 4506, '2016-04-14', 'Setelah saya evaluasi, terdapat dua bulab tunggakan. dan peminjam pada waktu jatuh tempo sudah melunasi. tinggal satu orang soestri kurang 2 bulan ( 212.000) karena ybs anaknya dirawat di RS Umum Demak ', 130);
INSERT INTO `bimbingan` VALUES (29, 4, 4977, '2016-04-27', 'Kelp Nariyah 2, ada kesalahan pencatatan sistem angsuran. yang benar adalah : Pinjaman 4 bulan dibayar sekali waktu jatuh tempo. disistem dibayar setiap bulan. perlu direvisi', 130);
