INSERT INTO `bimbingan` VALUES (32, 6, 277, '2016-05-16', 'Angsuran anggota kurang teratur, buku kas belum dikerjakan keluar masuk kas kelompok belum jelas', 292);
INSERT INTO `bimbingan` VALUES (33, 7, 302, '2016-06-21', 'Penganggsuran selalu terlambat, diidentyifikasi bahwa dana yang terkumpul di pakai terlebih dahulu oleh pengurus kelompok', 366);
INSERT INTO `bimbingan` VALUES (34, 12, 1360, '2016-06-22', 'setiap bulan tanggal 22 Kelompok Usaha jaya sudah setor uang angsuran ke UPK dan tingkatkan aktifitas kehadiran kelompok', 939);
INSERT INTO `bimbingan` VALUES (35, 12, 1360, '2016-06-22', 'setiap bulan tanggal 22 Kelompok Usaha jaya sudah setor uang angsuran ke UPK dan tingkatkan aktifitas kehadiran kelompok', 939);
INSERT INTO `bimbingan` VALUES (36, 7, 420, '2016-06-30', 'Anggsuran tidak tepat jatuh tempo, namun pengangsuran berjalan rutin setiap bulannya.\nKelompok tidak memperoleh IPTW dan ada salah satu anggotanya yang melakukan pembayaran tdk tetap waktu sehingga dana yang sudah terkumpul terpending penyetotrannya.', 366);
INSERT INTO `bimbingan` VALUES (37, 7, 358, '2016-06-30', 'kelompok beranggotakan 5 orang dan pengangsuran tidak berjalan baik sesui kesepakatan bersama dalam kelompok.\nAnggota atas nama Sri Rahmawati diindikasi sering memakai uang angsuran kelompok sehingga pembayaran yang harusnya disetorkan pada tanggal yang disepakati tercansel dan membuat kelompok menunggak 1 bulan', 366);
INSERT INTO `bimbingan` VALUES (38, 12, 1123, '2016-07-26', 'Pembayaran angsuran kurang bagus, IPTW/ hilang dikarenakan oleh anggota kelompok yang kurang bagus pembayarannya,sesuai kemampuan', 939);
INSERT INTO `bimbingan` VALUES (39, 0, 0, '2016-07-27', '1. Pembayaran secara terpisah oleh salah satu anggota yaitu atas nama MUFIDAH, yang bersangkutan merasa nyaman melakukan pengangsuran ke kantor tanpa melalui pengurus kelompok.\n2. Pengurus kelompok tdk ada keselarasan dalam membina kelompok sehingga ada kealahpahaman dalam berkomunikasi.\n3. Masih salah dalam menafsirkan waktu tambahan bila sudah jatuh tempo\n', 0);
INSERT INTO `bimbingan` VALUES (40, 0, 0, '2016-07-27', '1. Pembayaran secara terpisah oleh salah satu anggota yaitu atas nama MUFIDAH, yang bersangkutan merasa nyaman melakukan pengangsuran ke kantor tanpa melalui pengurus kelompok.\n2. Pengurus kelompok tdk ada keselarasan dalam membina kelompok sehingga ada kealahpahaman dalam berkomunikasi.\n3. Masih salah dalam menafsirkan waktu tambahan bila sudah jatuh tempo\n', 0);
INSERT INTO `bimbingan` VALUES (41, 7, 421, '2016-07-27', '1. Pembayaran secara terpisah oleh salah satu anggota yaitu atas nama MUFIDAH, yang bersangkutan merasa nyaman melakukan pengangsuran ke kantor tanpa melalui pengurus kelompok.\n2. Pengurus kelompok tdk ada keselarasan dalam membina kelompok sehingga ada kealahpahaman dalam berkomunikasi.\n3. Masih salah dalam menafsirkan waktu tambahan bila sudah jatuh tempo', 366);
INSERT INTO `bimbingan` VALUES (42, 7, 390, '2016-07-27', '1. Anggota sudah saling mengenal dana mayoritas semua bekerja pada lokasi yang sama yaitu pabrik bihun\n2. Kekuatan kelompok masih terbeban pada ketua kelompok, baik dalam penagihan dan pembayaran sudah terkoordinir dengan baik namun administrasinya masih belum teratur\n3. Keterbatasan SDM namun karakter peminjam dan kesungguhan dalam melakukan pengangsuran dapat dikategorikan kelas baik', 366);
INSERT INTO `bimbingan` VALUES (43, 7, 389, '2016-07-27', '1. Anggota sudah saling mengenal dana mayoritas semua bekerja pada lokasi yang sama yaitu pabrik bihun\n2. Kekuatan kelompok masih terbeban pada ketua kelompok, baik dalam penagihan dan pembayaran sudah terkoordinir dengan baik namun administrasinya masih belum teratur\n3. Keterbatasan SDM namun karakter peminjam dan kesungguhan dalam melakukan pengangsuran dapat dikategorikan kelas baik', 366);
INSERT INTO `bimbingan` VALUES (44, 4, 5393, '2016-08-18', 'Kelompok pemula dan baik', 120);
INSERT INTO `bimbingan` VALUES (45, 13, 119, '2016-09-07', 'buku Kas sudah dikerjakan tetapi untuk bukti belum terpasang dengan baik', 964);
INSERT INTO `bimbingan` VALUES (46, 11, 124, '2016-09-09', 'Identifikasi kemacetan Kelompok Aktif, ditemukan 3 orang yang menunggak yaitu :\n1). Nurhayati Besar pinjaman Rp. 5.100.000 menunggak selama 2 bulan sebesar 1.037.000 dengan alasan suami sedang sakit\n2). Mulyani Besar Pinjaman Rp. 5.100.000 menunggak selama 3 1/2 bulan sebesar 1.824.000 dengan alasan usaha sedang sepi\n3). Tita Rosita besar Pinjaman 5.100.000 menunggak selama 1 bulan sebesar 518.500 dengan alasan dagang sepi..', 808);
INSERT INTO `bimbingan` VALUES (47, 4, 4628, '2016-09-22', 'kelompok wangkong jaya, pada saat jatuh tempo ada pelunasan.\ndilakukan penagihan lebih dari 2 kali krn menunggak di bulan menghadapi lebaran.  bulan 5 dan bulan 6.\npengurus klp turmudi pinjamn 9 jt dan sururi 10 jt', 130);
INSERT INTO `bimbingan` VALUES (48, 4, 4628, '2016-09-22', 'buku kredit angsuran lancar mulai  awal angsuran sampai angsuran ke 8, ', 130);
INSERT INTO `bimbingan` VALUES (49, 4, 4628, '2016-09-22', 'buku kredit angsuran lancar mulai  awal angsuran sampai angsuran ke 8, ', 130);
INSERT INTO `bimbingan` VALUES (50, 11, 146, '2016-09-09', 'Teridentifikasi dikelompok kedelai ini, Ibu Novi meminjam SPP tapi uang tersebut dipinjamkan lagi/digunakan oleh Ibu Siti.', 808);
INSERT INTO `bimbingan` VALUES (51, 11, 144, '2016-09-13', 'Ibu Nina Marlina menungak 3 Bulan, karena suaminya sampai sekarang belum memiliki pekerjaan.', 808);
INSERT INTO `bimbingan` VALUES (52, 11, 235, '2016-09-13', 'Teridentifikasi Ibu Lilis menunggak 4 bulan, akan bayar melalui kelompok/transfer jarak waktu 2 minggu', 808);
INSERT INTO `bimbingan` VALUES (53, 11, 20, '2016-09-14', 'Hasil identifikasi dikelompok Merpati yang akan melaksanakan Verifikasi Usulan, ternyata Ibu Dewi sering terlambat setor. sehingga masukan dari anggota kelompok, Ibu Dewi jangan diberi pinjaman lebih dari Rp. 2.100.000,- supaya lancar.', 808);
INSERT INTO `bimbingan` VALUES (54, 11, 63, '2016-09-21', 'Dari seluruh Pinjaman sebesar Rp. 3.000.000,- Dikelompok anggur, Ibu Basiroh baru bayar Rp. 1.000.000,- dan sampai sekarang masih memiliki tunggakan kurang lebih 2.000.000.\nsedangkan seluruh tunggakannya sebesar Rp. 4.652.000,-', 808);
INSERT INTO `bimbingan` VALUES (55, 11, 55, '2016-09-21', 'Teridentifikasi kelompok semangka atas nama Ibu Lilis memiiki tunggakan sebesar Rp. 2.073.500,-\nkesanggupan mulai bulan depan akan membayar secara mencicil.', 808);
INSERT INTO `bimbingan` VALUES (56, 11, 57, '2016-09-21', 'teridentifikasi dikelompok Delima ada tunggakan sebesar Rp. 5.058.000,-, ketika dikonfirmasi ke ketua kelompok (Ibu Yanti), ternyata delima untuk pembayaran setorannya dilakukan oleh ibu Ii dan Ibu Yanti merasa sudah lunas.\nsetelah ditelusuri ternyata tunggakan tersebut ada di Ibu Wida Rp. 667.500.\ndan menurut Ibu Ii ada di Ibu Entin Rp. 1.435.000,- dan di Ibu Ii Rp. 3.300.000,-\nada kesanggupan dari Ibu Ii dan Ibu Entin untuk melakukan pembayaran kembali secara mencicil, sedangkan untuk Ibu Wida, tidak dapat dikonfirmasi.', 808);
INSERT INTO `bimbingan` VALUES (57, 11, 59, '2016-09-28', 'teridentifikasi dikelompok Belimbing atas nama Ibu Ihat memiliki tunggakan sebesar Rp. 4.392.000,-, dari awal pinjaman belum pernah melakukan cicilan secara langsung, akan tetapi Ibu Ihat pernah menitipkan uang sebesar Rp. 50.000,- sebanyak 3 kali  akan tetapi yang diterima oleh UPK melalui Ibu Euis (TPP Desa) sebesar Rp. 50.000,- (1 Kali).\n', 808);
INSERT INTO `bimbingan` VALUES (58, 11, 8, '2016-09-23', 'Teridentifikasi dikelompok Nuri menunggak sebesar Rp. 7.979.500,- dan setelah ditelusuri ternyata dari anggotanya telah selesai, tapi dari ketua kelompok tidak disetorkan.\nada kesanggupan di Bulan Oktober akan melakukan pembayaran lagi secara mencicil.', 808);
INSERT INTO `bimbingan` VALUES (59, 11, 19, '2016-09-23', 'Ada tunggakan yang cukup besar di kelompok Cucak Rawa ini, tapi setiap di datangi ketua kelompoknya (Ibu Een) selalu tidak ada di tempat.', 808);
INSERT INTO `bimbingan` VALUES (60, 11, 17, '2016-09-23', 'Untuk kesekian kalinya, kelompok Nuri (Ibu Yuni) diidentifikasi dan ternyata sampai saat ini belum melakukan pembayaran/Cicilan lagi sesuai dengan janji yang selalu disampaikan ketika diidentifikasi.', 808);
INSERT INTO `bimbingan` VALUES (61, 8, 3, '2016-10-18', 'Pada tanggal, 17 Oktober 2016 pada kelompok Bersatu, telah dilakukan proses Resceduling atas pinjaman kelompok tersebut yang telah bermasalah. namun dengan melalui upaya penyehatan pinjaman yang dilakukan oleh UPK, maka kelompok tersebut telah dilakukan Resceduling sesuai aturan yang ada.', 1);
INSERT INTO `bimbingan` VALUES (62, 8, 2, '2016-10-18', 'Pada tanggal, 17 Oktober 2016 pada kelompok SUKA MAJU, telah dilakukan proses Resceduling atas pinjaman kelompok tersebut yang telah bermasalah. namun dengan melalui upaya penyehatan pinjaman yang dilakukan oleh UPK, maka kelompok tersebut telah dilakukan Resceduling sesuai aturan yang ada. Pinjaman tersebut mulai tercatat di UPK sejak tanggal 01 Agustus 2013', 1);
INSERT INTO `bimbingan` VALUES (63, 8, 1, '2016-10-18', 'Pada tanggal, 18 Oktober 2016 pada kelompok MAWAR 1 Bonto-bontoa, telah dilakukan proses Resceduling atas pinjaman kelompok tersebut yang telah bermasalah. namun dengan melalui upaya penyehatan pinjaman yang dilakukan oleh UPK, maka kelompok tersebut telah dilakukan Resceduling sesuai aturan yang ada.', 1);
INSERT INTO `bimbingan` VALUES (64, 8, 1, '2016-10-18', 'Berdasarkan catatan bimbingan dan penanganan pinjaman bermasalah, maka kelompok Mawar 1 Bonto-bontoa memiliki masalah yg sangat rumit. pinjaman yg masih tersisa sampai sekarang sebesar Rp. 1,534,800,- tidak dapat lagi ditagih karena sudah tidak jelas siapa lagi si penunggak dalam kelompok tersebut.', 1);
INSERT INTO `bimbingan` VALUES (65, 15, 359, '2016-11-02', 'Pada hari ini telah di adakan pembinaan kelompok dikarenakan ada tunggakan yang cukup besar. Dihadiri oleh 4 anggota kelompok. Pembinaan dilaksanakan oleh Ketua UPK, Sekretaris UPK dan Ketua BKAD. Tunggakan per Oktober sebesar 4.810.000 dibayar 1.900.000 dengan rincian sbb:\n1. Sriani bayar 500.000 lunas\n2. Musriani bayar 300.000 kurang 400.000\n3. Samirah Joyo bayar 300.000 kurang 700.000\n4. Wiji bayar 250.000 kurang 550.000\n5. Katini bayar 250.000 kurang 1.000.000\n6. Samirah Kusni bayar 300.000 kurang 400.000\nAnggota kelompok sepakat akan membayar tanggal 15 Nopember 2016 sekaligus angsuran bulan Nopember 2016.', 1016);
INSERT INTO `bimbingan` VALUES (66, 15, 360, '2016-11-01', 'Pada hari ini telah di adakan pembinaan kelompok dikarenakan ada tunggakan yang cukup besar. Pembinaan dilaksanakan oleh Ketua BKAD, Ketua UPK dan Sekretaris UPK. Dihadiri oleh 5 anggota kelompok. Tunggakan per Oktober 2016 sebesar 5.290.000 dengan rincian sbb :\n1. Susilowati 1.000.000\n2. Kasmiati 300.000\n3. Puji Astutik 1.000.000\n4. Sipu 600.000\n5. Yeni 800.000\n6. Ida 1.500.000\n7. Supi 100.000\nAnggota sepakat akan membayar angsuran tanggal 7 Nopember dan 15 Nopember 2016.', 1016);
INSERT INTO `bimbingan` VALUES (67, 15, 326, '2016-11-15', 'Pada hari initelah diadakan pembinaan kelompok dikarenakan adanta tunggakan yang cukup besar per 31 oktober 2016 yaitu Rp 7.853.300,-. Tunggakan ini dikarenakan angsuran anggota kelompok dipakai oleh Ketua Kelompok yaitu an. Titin Sihtiar. Tunggakan tersebut akan dibayar tanggal 23 Desember 2016. Untuk angsuran bulan Nopember akan dibayar paling lambat akhir  bulan ini dan dialihkan pembayrannya ke Bendahara Kelompok agar tidak disalahgunakan lagi.', 1017);
INSERT INTO `bimbingan` VALUES (68, 15, 779, '2016-11-03', 'Kelompok Mawar 1 Desa Joketro merupakan kelompok yang menunggak dan telah jatuh tempo pada 7 September 2016. Setelah diadakan identifikasi dan penagihan, anggota kelompok sanggup untuk membayar tunggakannya dengan cara mengangsur.', 1041);
INSERT INTO `bimbingan` VALUES (69, 15, 779, '2016-11-03', 'Kelompok Mawar 1 Desa Joketro merupakan kelompok yang menunggak dan telah jatuh tempo pada 7 September 2016. Setelah diadakan identifikasi dan penagihan, anggota kelompok sanggup untuk membayar tunggakannya dengan cara mengangsur.', 1041);
INSERT INTO `bimbingan` VALUES (70, 15, 738, '2016-11-07', 'Kelompok Tulip Desa Tamanarum merupakan kelompok yang tergolong baru. Kelompok ini sudah 2x melunasi pinjamannya sebelum jatuh tempo (pada angsuran ke 6). Setelah diidentifikasi ada anggota yang keberatan bila diajak ngedrop angsuran.', 1041);
INSERT INTO `bimbingan` VALUES (71, 15, 755, '2016-11-11', 'Ada 1 anggota kelompok yang sulit dalam penagihan yaitu bu Jomi', 1041);
INSERT INTO `bimbingan` VALUES (72, 15, 346, '2016-11-17', '1. Tunggakan ada di ketua atas nama Dewi Anita Rp. 10.126.800 akan di bayar awal bulan Desember \n2. Angsuran untuk anggota a/n Ririn, Siti Indiani, Somiatun, Menik untuk bulan Nopember akan dibayar tgl 17 Siang\n3. Angsuran selanjutnya dialihkan ke bendahara a/n Siti Indiani', 1015);
INSERT INTO `bimbingan` VALUES (73, 4, 4765, '2016-11-23', 'sebagai kelompok yang angsurannya tepat waktu, tapi belum ditunjang dengan pencatatan pembukuan yang lengkap. ', 130);
INSERT INTO `bimbingan` VALUES (74, 4, 4763, '2016-11-23', 'Tunggakan terjadi karena terjadi gagal panen garam. tambak garam terkena dampak banjir tanggul kali jebol. sehingga para petani garam tdk dpt membayar lunas', 130);
INSERT INTO `bimbingan` VALUES (75, 1, 221, '2016-12-10', 'dasdasdasasdasasdasd', 242);
INSERT INTO `bimbingan` VALUES (76, 1, 221, '2016-12-14', 'sasda', 241);
INSERT INTO `bimbingan` VALUES (77, 4, 4736, '2016-12-19', 'kelompok tata busana 1, waktu pelunasan memakai uang pinjaman pihak ketiga, \nmhn bantuan tim verifikasi ,lebih hati hati apabila ada proposal pengajuan ulang di klp tata busana', 130);
INSERT INTO `bimbingan` VALUES (78, 8, 15, '2016-12-27', 'Dilakukan Resceduling dengan data Tunggakan per 30 September 2016\nPokok : 8,333,500\nBunga : 1,319,800\nJumlah : 9,653,300\n', 1);
INSERT INTO `bimbingan` VALUES (79, 8, 18, '2016-12-27', 'Dilakukan Resceduling dengan data per 30 September 2016\nAlokasi Pinjaman 23.000.000 dan Tunggakan Pokok : 12,916,600 Bunga : 4,558,100\nJumlah : 17,474,700\nResceduling Tanggal 27 Desember 2016', 1);
INSERT INTO `bimbingan` VALUES (80, 14, 136, '2016-12-30', 'Masuk Kelompok Pisah Buku Dengan catatan terakhir :\nTunggakan 8.500.000, dan Bunga 2.550.000,-', 976);
INSERT INTO `bimbingan` VALUES (81, 14, 173, '2016-12-30', 'Masuk Kelompok Pisah Buku, dengan catatan tunggakan terakhir :\nTunggakan Pokok : 2.636.400 dan Bunga 0,00', 976);
INSERT INTO `bimbingan` VALUES (82, 14, 173, '2016-12-30', 'Masuk Kelompok Pisah Buku, dengan catatan tunggakan terakhir :\nTunggakan Pokok : 2.636.400 dan Bunga 0,00', 976);
INSERT INTO `bimbingan` VALUES (83, 7, 892, '2017-01-07', 'Kepengurusan dalam kelompok gayatri 1, terdapat permasalahan yang mana diindintifikasi bahwa pengurus memakai dana angsuran yang disetorkan oleh salah satu anggotanya.\nKemudian saat diadakan verifikasi a/n Nur Cholis dan Villa Andriana tidak hadir dalam kegiatan tersebut.\nMenurut Atik Mutmainnah; Nur Cholis memiliki sejumlah tanggungan kepada Atik Mutmainnah.', 366);
INSERT INTO `bimbingan` VALUES (84, 19, 99, '2017-01-19', 'Tidak aktif karena angsurannya tidak lancar dan kelompoknya tidk solid', 1235);
INSERT INTO `bimbingan` VALUES (85, 11, 250, '2017-01-30', 'Berdasarkan hasil identifikasi lapangan tunggakan dikelompok belibis disebabkan :\n1. uangnya hilang \n2. Terpakai oleh ibu eutik sebagian dan sebagian lagi oleh ibu yati \n3. Setoran ibu lina  terpakai oleh ibu yati yang pergi ke lampung\n4. Ketua kelompok (ibu Eutik) sudah menyanggupi untuk mencicil uang setoran yang telah   terpakai sampai beres\n5.Mulai bulan depan Ketua kelompok menyerahkan setoran anggota ke TPP karena takut terpakai lagi', 810);
INSERT INTO `bimbingan` VALUES (86, 11, 73, '2017-01-31', 'Berdasarkan hasil identifikasi lapangan kelompok jambu tunggakan kel tsb berada di beberapa anggota yang sudah berbulan bulan tidak setor. ', 810);
INSERT INTO `bimbingan` VALUES (87, 1, 34, '2017-02-25', 'Anggotanya cantik cantik', 241);
INSERT INTO `bimbingan` VALUES (88, 7, 3308, '2017-02-27', 'Kelompok sebelumnya bernama UEP Rumah Sehati , jadi intinya ini bukan kelompok baru , berganti nama dikarenakan berganti pengurus ,. kelompok UEP Rumah sehati tidak diajukan lagi ', 724);
INSERT INTO `bimbingan` VALUES (89, 1, 1, '2017-03-08', 'Administrasi kelompok perlu mendapat bimbingan', 241);
INSERT INTO `bimbingan` VALUES (90, 4, 5698, '2017-03-08', 'kelompok Ar Rahmah Tahun 2017 semoga bisa bangkit kembali dan pinjam ke UPK lagi dengan catatan mengikuti aturan yang ada', 1248);
INSERT INTO `bimbingan` VALUES (91, 4, 5991, '2017-03-08', 'Identifikasi tunggakan sudah masuk per anggota, karena kelompok terdiri dari anggota yang bertempat tinggal acak seluruh desa. maka identifikasi harus perdaerah agar penagihan lebih mudah dan tunggakan bisa segera nol persen.', 1249);
INSERT INTO `bimbingan` VALUES (92, 4, 5985, '2017-03-08', 'Mohon Angsuran diberikan secara tepat waktu sehingga pengajuan pencairan tidak terkendala dengan angsuran yang tertunggak. karena kelompok Bakau akan lunas bulan April.', 1248);
INSERT INTO `bimbingan` VALUES (93, 4, 5986, '2017-03-08', 'identifikasi kelompok sudah dipetakan per dukuh. untuk memudahkan penagihan harus rutin dan berkelanjutan untuk membentuk mental nasabah agar sadar untuk menunaikan kewajibanya.', 1249);
INSERT INTO `bimbingan` VALUES (94, 4, 5988, '2017-03-08', 'Identifikasi sudah per nama anggota dan perdukuh, peran ketua kelompok kurang berfungsi jadi UPK harus memantau dan membantu dalam penagihan langsung .\n', 1249);
INSERT INTO `bimbingan` VALUES (95, 4, 5989, '2017-03-08', 'Ada beberapa nama sudah lunas dan angsuran digunakan ketua/koordinator kelompok untuk menutup agsuran kelompok lain yang dalam LPP UPK sudah lunas.\nKetua Kelompok tidak berfungs dengan baik mengharuskan UPK untuk terjun langsung menyisir angsuran per anggota,per rumah secara kontinue agar mental nasabah terbentuk untuk bisa menunaikan kewajiban membayar angsuran. ', 1249);
INSERT INTO `bimbingan` VALUES (96, 4, 5990, '2017-03-08', 'Identifikasi pernama perdusun sudah dilaksanakan proses selanjutnya menekuni penagihan secara rutin, untuk memberikan pembelajaran kepada semua anggota untuk tetap bertanggungjawab menunaikan kewajiban mengangsur. ', 1249);
INSERT INTO `bimbingan` VALUES (97, 4, 5983, '2017-03-08', 'identifikasi tunggakan peranggota dan perrumah. setiap rumah yang menunggak ada stiker RUMAH BINAAN UPK untuk memudahkan pencarian rumah dalam penagihan angsuran oleh UPK karena ketua / koordinator sudah tidak berfungsi peranya.', 1249);
INSERT INTO `bimbingan` VALUES (98, 4, 5984, '2017-03-08', 'Semua kelompok diTimbulsloko sudah teridentifikasi peranggota dan dukuh. butuh penagihan secara rutin agar membiasakan nasabah menunaikan kewajibanya membayar angsuran', 1249);
