INSERT INTO `bimbingan` VALUES (144, 18, 24, '2017-05-09', 'Koonfirmasi kelompok dan hampir jatuh tempo pinjaman sert masih banyaknya saldo pinjaman kepada ketua kelompok.Ketua kelompok untuk dapat memberikan data data administrasi keterlambatan angsuran anggota.Ketua kelompok sendiri tidak mengangsur sejak pinjmana ke 2 sehingga untuk angsuran diserahkan kepada pengurus yang lain.Maksimal hari senin Tanggal 15 Mei 2017 untuk bisa bertemu dikantor UPK kecamatan kebumen dengan kepengurusan yang lain dengan membawa data administrasi', 1194);
INSERT INTO `bimbingan` VALUES (145, 18, 130, '2017-05-09', 'Kunjungan penagihan Keketua kelompok \nYang bersangkutan tidak dirumah sehingga diberikan catatan panggilan untuk dapat kekantor UPK hari Jumat tanggal 12 Mei 2017', 1194);
INSERT INTO `bimbingan` VALUES (146, 18, 87, '2017-05-09', 'Kunjungan Keanggota kelompok An sucipto .\nYang bersangkutan belum bisa membayar karena dana panen padi digunakan untuk modal anaknya ternak lele sehingga saat pada panen akan digunakan untuk membayar pinjaman di UPK.prediksi panen 1 bulan lagi.disepakati tanggal 09 petugas UPK akan kesana kembali.\n', 1194);
INSERT INTO `bimbingan` VALUES (147, 18, 135, '2017-05-12', 'Penagihan dan konfirmasi panggilan .\nbelum dapat membayar .data administrasi belum dapat dilihat karena ketemu di kios usahanya dipasar tumenggungan.Hari senin tanggal 15 untuk kekantor UPK dg mmembawa administrasi dan angsuran.', 1194);
INSERT INTO `bimbingan` VALUES (148, 18, 135, '2017-05-09', 'Kunjungan penagihan Keketua kelompok Yang bersangkutan tidak dirumah sehingga diberikan catatan panggilan untuk dapat kekantor UPK hari Jumat tanggal 12 Mei 2017', 1194);
INSERT INTO `bimbingan` VALUES (149, 18, 130, '2017-05-09', 'Salah posting  memasukan Ke kelompok Seharusnya mandiri makmur ', 1194);
INSERT INTO `bimbingan` VALUES (150, 18, 59, '2017-05-12', 'KUn jungan Penagihan .konfirmasi Perjanjian pembayaran yang belum terealisasi.\nInformasi dari tetangga sudah jarang pulang kerumah .tidur ditempat kerja dengan anak yang kecil namun tetangga belum tahu bekerja dimana serta suami dan anak yang sudah tamat slta  kerja dijakarta ', 1194);
INSERT INTO `bimbingan` VALUES (151, 18, 168, '2017-05-12', 'Konfirmasi Saldo pin jmana dan pegecekan admisitrasi \nAngsuran 4 orang msih bisa ditanagani ketua kelompok 2 orang untuk ditanagani oleh pengurus UPK \nterdiri dari :Suparno dan Mut mainah .hari senin tanggal 15 Mei 2017 untuk dikroscek data angsuran dan administrasi Kelompok di UPK\n', 1194);
INSERT INTO `bimbingan` VALUES (152, 18, 167, '2017-05-12', 'Kunjungan keketua Kelompok hari senin tanggal 15 mei 2017 untuk bisa hadir di UPK Kec kebumen dengan membawa Dokumen Administrasi guna identifikasi saldo pinjaman ', 1194);
INSERT INTO `bimbingan` VALUES (153, 18, 167, '2017-05-12', 'Kunjungan Ke ketua kelompok \nbeberapa anggotakelompok menunggak dan mengatakan minta ditalangi dulu oleh ketua kelompok.namun ketua kelompok tidak bisa bahkan ketua kelompok sendiri agak sedang kesulitan keuangan karna usaha tempe sedang kurang baik  dan jg kebutuhan keluarga ( biaya ) anak sedang banyak,.hasri senin tanggall 15 Mei 2017 untuk cek singkronisasi saldo pinjman dikantor UPK dengan membawa Dokumen administrasi.\n', 1194);
INSERT INTO `bimbingan` VALUES (154, 18, 135, '2017-05-15', 'konfirmasi tunggakan.\nKetua Hadir Di UPK kec kebumen terinformasikan Angsuran menjadi tanggung jawab ketua kelompok .akan diselesaikan s/d jatuh tempo juli 2017 dg sitem mengangsur perbulan .angsuran hari ini Rp 200.000. saran UPK; Selesaikan data angsuran anggota ...bila sudah dipake oleh ketua itu bentuk penyelewengan untuk segera diselesaikan jika tidak mau menjadi masalah Hukum.berjanji akan diselesaikan sd/juli 2017 .\n', 1194);
INSERT INTO `bimbingan` VALUES (155, 18, 2986, '2017-05-18', 'Kerumah Bp basuki bersama bu Anna untuk menanyakan kesanggupan melunasi angsuran, dg memberikan jaminan motor Vega.', 1423);
INSERT INTO `bimbingan` VALUES (156, 18, 2963, '2017-05-18', 'tgl 17 Mei 2017, Pencairan perdana Kel Gondang Baru,sejumlah 7.500.000, bersama Bu Anna, dan dihadiri semua anggota kel yg berjumlah 5 orang.', 1423);
INSERT INTO `bimbingan` VALUES (157, 18, 649, '2017-05-18', 'tgl 17 Mei 2017, menyerahkan proposal pengajuan SPP, dan Kelompok akan melunasi kekurangan angsuran pd tgl 25 Mei 2017', 1423);
INSERT INTO `bimbingan` VALUES (158, 18, 59, '2017-05-20', 'informasi dari ketua kelompok lain ketuakelompok sedang dirumah.kunjungan ke ybs.mengakui masih memiliki kekurangan angsuran di upk dan dana masih berada dianggota kelompok .2 orang anggota kelompok dipanggil dg hasil mengakui pinjman dan meminta untuk di angsur kembali setiap tanggal 20 perbulan s/d selesai mulai bulan juni 2017 dg sistem petugas upk kerumah  dan angsuran akan diserahkan kepada ibunya yg disebelah rumah.\n', 1194);
INSERT INTO `bimbingan` VALUES (159, 18, 59, '2017-05-20', 'informasi dari ketua kelompok lain ketuakelompok sedang dirumah.kunjungan ke ybs.mengakui masih memiliki kekurangan angsuran di upk dan dana masih berada dianggota kelompok .2 orang anggota kelompok dipanggil dg hasil mengakui pinjman dan meminta untuk di angsur kembali setiap tanggal 20 perbulan s/d selesai mulai bulan juni 2017 dg sistem petugas upk kerumah  dan angsuran akan diserahkan kepada ibunya yg disebelah rumah.\n', 1194);
