INSERT INTO `bimbingan` VALUES (163, 0, 0, '2017-07-03', 'Dari hasil kunjungan yang dilakukan oleh Ketua UPK bersama sekretaris UPK, menunjukkan bahwa terdapat tunggakan pada periode pembayaran bulan Juni 2017 yang disebabkan oleh anggota atas nama Buniyati Rp. 300.000,- dan Parti Rp. 300.000,- sedangkan uang angsuran Biniayati sudah disetorkan ke ketua kelompok dan yang bersangkutan tidak ada di rumah, sedangkan parti kami mencoba menemui anamun pihak keluarga menyatakan bahwa sdri. parti tidak ada di rumah.', 0);
