INSERT INTO `bimbingan` VALUES (166, 10, 3172, '2017-07-13', 'kelompok ini mengalami keterambatan dalam pembayaran angsuran setelah dilakukan kunjungan oleh tim UPK diindikasikan adanya penyalagunaan dana oleh salah sau oknum emanfaat dan pengurus kelompok oleh karenanya kami upk memberi catatan khusu kepada kelompok ini agar dilakukan penkajian serta penanganan secara khusus oleh kelembagaan yang terkait.', 594);
