INSERT INTO `bimbingan` VALUES (180, 18, 1386, '2017-07-18', 'Atas nama Supriyanti masih tertulis sehingga untuk kelompok Arisan dusun perlu direvisi lg  karena supriyanti sebagai ketua kelompok Arisan Dusun dan juga sebagai pemanfaat', 1358);
INSERT INTO `bimbingan` VALUES (181, 7, 3365, '2017-07-20', 'Kelompok masih pemula dan atas nama IFA ROSITA DEWI mengundurkan diri dikarenakan yang bersangkutan bekerja diluar daerah.', 366);
INSERT INTO `bimbingan` VALUES (182, 10, 2055, '2017-02-02', 'Kunujungan terhadap kelompok ini karena ada salah satu anggota yang mengalami tersendat dalam pembayan maka perlu dilkukan pemdampingan dalam hal ini dilakukan oleh ketua dan staf UPK ', 594);
INSERT INTO `bimbingan` VALUES (183, 10, 2181, '2017-02-07', 'Pendampingan kelompok yang dilakukan oleh ketua bersama tim UPK untuk mempersiapkan kelomok dalam rencana pengajuan dana', 594);
INSERT INTO `bimbingan` VALUES (184, 10, 1913, '2017-02-08', 'Melakukan pembinaan terhadap kelompok ini dan melakukan upaya penyelesaian pinjaman yang disebabkan oleh salah seorang angota yang bernama Surani', 594);
INSERT INTO `bimbingan` VALUES (185, 10, 1912, '2017-02-08', 'Melakukan upaya peneyelesaian pinjaman bermasalah dengan mediasi via DATUN Kejari Lumajang dengan melakukan penagihan dengan terhadap anggota anggota yang bermasalah', 594);
INSERT INTO `bimbingan` VALUES (186, 10, 3157, '2017-02-10', 'Melakukan kunjungan terhadap kelompok ini dalam rangka pembinaan persiapan penyaluran dana yang telah diajukan oleh kelompok tersebut', 594);
INSERT INTO `bimbingan` VALUES (187, 10, 2183, '2017-02-14', 'Melakukan kunjungan karena kelmpok ini mengajukan pinjaman yang ke 2 kalinya oleh  kerenanya dikaukan pembinaan terhadap kelompok ini', 594);
INSERT INTO `bimbingan` VALUES (188, 10, 2021, '2017-02-16', 'Melakukan penanganan pinjaman bermasalah karena tunggakan yang ada di kelompok ini disebabkan adanya indikasi penyalagunaan oleh ketua (penguru) kelompok dasa wisma (Eka Otaviana)', 594);
INSERT INTO `bimbingan` VALUES (189, 10, 2029, '2017-02-16', 'Melakukan kunjungan terhadap kelompok ini karena tunggakan disebabkan adanya indikasi penyalagunaan dana oleh oknum pemanfaat yang diluar SPK yang sudah disepakati serta ada juga anggota pemanfaat yang memang belum lunas', 594);
