INSERT INTO `bimbingan` VALUES (198, 18, 601, '2017-07-27', 'Pembinaan dan kroscek data pinjaman di Kell Kenanga 3 dan 4,tempat dirumah Ibu Agus Triyani/Ketua Kel, Jam 14.30 s/d jam 16.30 wib, undangan untuk semua anggota kel Kenanga 3 dan 4, namun yang hadir hanya 6 orang dari 9 orang.\n1. Bu Unayah\n2 Bu Darisem\n3, Bu Samijem\n4. Bu.Siti Khotimah\n5. Bu Samini\n6. Bu Siwan\nHasil cross cek data pinjaman sbb:\n1. bu Unayah SPK 10 jt(7 real 3 Tebengan) Juni Juli belum ngangsur\n2. Bu Darisem SPK 10 jt (1,5 jt riil, 8,5 jt Tebengan.Juni belum ngangsur\n3. Bu samijem, (SPK 8 Jt, riil 8 jt( Juni blm ngangsur Juli krg 100 rb\n4. Siti Khotimah SPK 8 Jt riil 4 jt tebengan 4 jt ( Juni blm angsur Juli krg 400 rb)\n5. Bu Samini SPK 5 jt riil 3 jt tebengan 2 jt( Juni blm ngangsur Juli kurang 100 rb)\n6 Bu Siwan SPK 8 Juta dipakai sendiri ( Angsuran JUNI dan Juli Belum.\n7. Bu Rusmiyati SPK 10 Jt, riil 14 Jt(angsuran Juni dan Juli belum.)\n8. Bu Khotijah SPK 15 jt riil 23 jt(angsauran sll lewat bulan\n9.Bu Sawit SPK 1 jt dipakai sendiri(angsuran lancar\n10. Bu Sutijah SPK 5 jt, riil 3 jt Tebengan 2 Jt(Juni dan Juli blm ngangsur)\nSetelah pertemuan ada angsuran masuk sebesar 2 jt. \nselain itu dari UPK mensosialisasikan hasil rakor Ketua UPK dan Ketua kelompok berkaitan dengan penyampaian SOP perguliran th 2017 dan penyampaian Dansos 2017', 1423);
