INSERT INTO `bimbingan` VALUES (216, 0, 0, '2017-08-18', 'Kelompok mengalami kemacetan angsuran, dari target bulan Juli 2017 LUNAS namun sampai bulan Agustus belum menyelesaikan tunggakannya.\nAda 11 anggota dan rata-rata belum menggangsur untuk angsurannya. Tanggungan atas nama Yuyun 2x angsuran, Siti Rahayu 1x angsuran, Khotimah 1x angsuran, Suhartiningsih 1x angsuran; dipakai oleh ketua kelompok a/n Siti Rahmawati dengan total tanggungan 2.891.000', 0);
