INSERT INTO `bimbingan` VALUES (223, 7, 407, '2017-07-20', 'Kelompok mengalami kemacetan angsuran, dari target bulan Juli 2017 LUNAS namun sampai bulan Agustus belum menyelesaikan tunggakannya.\nAda 11 anggota dan rata-rata belum menggangsur untuk angsurannya. Tanggungan atas nama Yuyun 2x angsuran, Siti Rahayu 1x angsuran, Khotimah 1x angsuran, Suhartiningsih 1x angsuran; dipakai oleh ketua kelompok a/n Siti Rahmawati dengan total tanggungan 2.891.000', 366);
INSERT INTO `bimbingan` VALUES (224, 7, 413, '2017-07-25', 'Rencana kelompok akan bubar dan anggota banyak yang akan bergabung dengan kelompok lain.\nterdapat beberapa orang yang bermasalah dalam kelompok, kegiatan tanggung renteng tidak berjalan dengan baik sehingga pengurus kelompok sering nalangi dalam pengasuran. Karena tertlalu sering pengurus nalangi anggsuran maka rencananya kelompok akan membubarkan diri.', 366);
INSERT INTO `bimbingan` VALUES (225, 7, 415, '2017-07-24', 'Kelompok pada awalnya berjalan baik, namun pada saat penggasuran berjalan kurang baik karena ada beberapa anggota yang melakukan pengagsuran kurang baik, bahkan ada yang memending settoran ke UPK sehingga kelompok sempat menunggak anggsuran.\nkelompok berjanji akan melunasi angsuran 29 Juli 2017 dan berharap dapat mengikuti proses perguliran kembali', 366);
INSERT INTO `bimbingan` VALUES (226, 7, 450, '2017-06-28', 'Kelompok tergolong masih pemula, namun karakter dari pengurus kelompok yang kurang baik membuat berjalannya anggsuran menjadi tersendat.\nsejumlah dana yang harusnya tersetorkan ke UPK dipakai oleh pengurus untuk keperluan lain dan menjadi tunggakan yang harus diselesaikan', 366);
INSERT INTO `bimbingan` VALUES (227, 7, 450, '2017-07-26', 'kunjungan berikutnya untuk memastikan bahwa yang bersangkutan akan melakasanakan pengangsuran.\nPertemuan dilakukan dirumah kader pengurus kelompok SPP yaitu di rumah MULYONO dan ditarik kesepakatan bahwa yang bersangkutan akan melunasi tanggungan dengan meminta waktu sampai bulan akhir agustus 2017', 366);
INSERT INTO `bimbingan` VALUES (228, 7, 3086, '2017-07-18', 'Pada awalnya kelompok berjalan baik dan selalu tepat waktu dalam melakukan pengangsuran, namun pada putaran berikutnya kelompok mengalami kendala dalam melakukan pengagsuran ke UPK.\nPengurus kelomok telah melakukan pemendingan dana dan memakainya untuk keperluan lain sehingga anggsuran tidak berjalan baik dan setelah dikunjungi, pengurus yang besangkutan janji bayar dobel anggsuran pada tanggal 25/07/2017', 366);
INSERT INTO `bimbingan` VALUES (229, 7, 3032, '2017-08-18', 'kelompok masih pemula dan anggsuran yang awalnya baik, namun untuk anggsuran yang selanjutnya mengalami kendala. Angsuran ke 7 dan 8 mengalami kemacetan pada pengurus, karena memending dana yang seharusnya tersetorkan namun digunakan untuk keperluan lainnya.', 366);
INSERT INTO `bimbingan` VALUES (230, 18, 2876, '2017-08-22', 'Kel. Curug mengangsur , Rp. 4.600.000\ndirumah Bp. Suwardo', 1423);
INSERT INTO `bimbingan` VALUES (231, 18, 491, '2017-08-22', 'Bertemu Bp. sami untuk menanyakan kembali tanggungan tunggakanb pinjaman di UPK 6.625.000 dan telah menyerahkan sepeda motor, pada bulan Mei 2017, tetapi sampai saat ini BPKB masih di gadaikan', 1423);
