INSERT INTO `bimbingan` VALUES (233, 18, 492, '2017-08-22', 'Ke Bp. Sawaun, untuk mngumpulkan anggota yg belum melunasi tunggakan yg sudah bertahun tahun.\nbp. Sawaun mengangsur tunggakan 200.000', 1423);
INSERT INTO `bimbingan` VALUES (234, 14, 307, '2017-08-23', 'PL datang ke kelompok Manunggal Doplang ketemu dengan Bp.Suyudi dan Bu Tarfiah menjalankan tugas penagihan tunggakan sebesar Rp. 22,176,600. Dan di buat kesepakatan dalam tahap 3X angsuran selama 3 bulan lunas. ', 989);
INSERT INTO `bimbingan` VALUES (235, 14, 307, '2017-08-22', 'PL datang ke kelompok Manunggal Doplang dan ketemu dengan Bp. Suyudi dan Ibu Tarfiah dan PL mengingatkan kembali bahwa jatuh tempo kelompok Manunggal Doplang adalah Tgl 23 juli 2014 dengan jumlah angsuran Pokok Rp. 1.389.300. Bunga Rp. 416.700 selama 18X angsuran, dengan total pinjaman Rp. 25.000.000. \nPL juga mengingatkan bahwa kewajiban kelompok mengangsur sebesar Rp. 1.806.000/bulan. sampai saat ini Total tunggakan masih Rp. 22.1756.000. dan PL bersama Bp. Suyudi dan Ibu Tarfiah membuat kesepakatan tahapan penyelesaian tunggakan dengan skema 3X LUNAS selam 3 bulan. PL Hermanto dan Pranan Prastiwi', 989);
INSERT INTO `bimbingan` VALUES (236, 14, 307, '2017-08-22', 'PL datang ke kelompok Manunggal Doplang dan ketemu dengan Bp. Suyudi dan Ibu Tarfiah dan PL mengingatkan kembali bahwa jatuh tempo kelompok Manunggal Doplang adalah Tgl 23 juli 2014 dengan jumlah angsuran Pokok Rp. 1.389.300. Bunga Rp. 416.700 selama 18X angsuran, dengan total pinjaman Rp. 25.000.000. \nPL juga mengingatkan bahwa kewajiban kelompok mengangsur sebesar Rp. 1.806.000/bulan. sampai saat ini Total tunggakan masih Rp. 22.1756.000. dan PL bersama Bp. Suyudi dan Ibu Tarfiah membuat kesepakatan tahapan penyelesaian tunggakan dengan skema 3X LUNAS selam 3 bulan. PL Hermanto dan Pranan Prastiwi', 989);
INSERT INTO `bimbingan` VALUES (237, 14, 307, '2017-08-22', 'PL datang ke kelompok Manunggal Doplang dan ketemu dengan Bp. Suyudi dan Ibu Tarfiah dan PL mengingatkan kembali bahwa jatuh tempo kelompok Manunggal Doplang adalah Tgl 23 juli 2014 dengan jumlah angsuran Pokok Rp. 1.389.300. Bunga Rp. 416.700 selama 18X angsuran, dengan total pinjaman Rp. 25.000.000. \nPL juga mengingatkan bahwa kewajiban kelompok mengangsur sebesar Rp. 1.806.000/bulan. sampai saat ini Total tunggakan masih Rp. 22.1756.000. dan PL bersama Bp. Suyudi dan Ibu Tarfiah membuat kesepakatan tahapan penyelesaian tunggakan dengan skema 3X LUNAS selam 3 bulan. PL Hermanto dan Pranan Prastiwi', 989);
INSERT INTO `bimbingan` VALUES (238, 14, 288, '2017-08-22', 'PL datang ke kelompok Ngudi Rejeki Pundung  ketemu dengan ibu yanti dan Bp. Suharyanto, PL mengingatkan kembali  bahwa jatuh tempo kelompok Ngudi Rejeki Pundung adalah 22 april 2010 dengan jumlah angsuran Pokok Rp. 833.300 Bunga Rp. 166.700 selma 12X angsuran. Total Pinjaman Rp. 10.000.000.\nDan PL mengingatkan kembali bahwa kewajiban kelompok ini mengangsur sebesar Rp. 1.000.000./ bulan.\nSampai saat ini Total tunggakan Rp. 3.750.000. PL dan Ibu Yanti dan Bp. Suharyanto membuat tahapan penyelesaian tunggakan dalam tahap 3X angsuran Lunas dalam 3 bulan. PL Hermanto, Pranan Prastiwi', 989);
INSERT INTO `bimbingan` VALUES (239, 14, 298, '2017-08-22', 'PL datang ke kelompok Karya Mandiri Wiloso ketemu dengan Bp. Suhardi dan Ibu Sutiyem, PL mengingatkan kembali bahwa jatuh tempo kelompok Karya Mandir Wiloso adalah Tgl 8 Desember 2011, dengan jumlah angsuran Pokok Rp. 1.250.000. Bunga Rp.  250.000. Selama 12X angsuran dengan Total pinjaman Rp. 15.000.000.\nPL juga mengingatkan kembali bahwa kewajiban kelompok mengangsur sebesar Rp. 1.500.000/ bulan.\nSampai saat ini total tunggakan Rp. 7.435.000, PL dengan pengurus kelompok membuat kesepakatan kesanggupan pelunasan dalam tahap 3X Lunas selama 3 bulan.PL Hermanto, Pranan Prastiwi', 989);
INSERT INTO `bimbingan` VALUES (240, 14, 307, '2017-08-23', 'Revisi : Jumlah Tunggakan Total : Rp. 22.176.000,-', 976);
INSERT INTO `bimbingan` VALUES (241, 14, 307, '2017-08-23', 'Koodinator PL datang ke kelompok manunggal doplang dan menyarankan agar Bp. Suyudi dan Bu tarfiah jangan patah semangat dan berusaha menjalankan skema 3 bulan pelunasan walau dengan keadaan sakit dan memberikan masukan mengumpulkan atau memasukan uang di kotak setiap malam habis jualan dan akan di buka seminggu sekali demikian hasil kunjungan Koordinator PL', 989);
