INSERT INTO `bimbingan` VALUES (247, 18, 537, '2017-06-06', 'Selasa 6 Juni 2017\nPada saat pencairan ada potoingan lagi di Kel. Per org 45.000(buat transport yg ngurusi). masing2 pinjaman yg diterima anggota sesuai SPK\nSampai dg bulan Mei anggota setor penuh ke ketua Kel.\nDwi sriyani belum ngangsur 3 bulan sampai dg bulan Mei 2017. Disepakati koordinator berikutnya Ibu siti fatimah.\nTunggakan sampai bulan mei 2.100 rb. indikasi dipakai oleh ketua kel.', 1423);
INSERT INTO `bimbingan` VALUES (248, 18, 537, '2017-06-06', '6 Juni 2017\nTunggakan 1.746.000, indikasi dipakai ketua kelompok.\nAnggota tidak ada yg hadir saat dikumpulkan', 1423);
INSERT INTO `bimbingan` VALUES (249, 18, 544, '2017-06-07', 'Rebo 7 Juni 2017\nData tunggakan\n1. Tika dan Sunar, tunggakan mulai Januari 2017.\nSari krg 3 bulan.\nNing rahayu di spk 2 jt, namun pinjam riil 3 juta dan sdh lunas.\nTumirah krg 5 bulan. Kesepakatan tiap bulan ngangsur 1 Juta,\n', 1423);
