INSERT INTO `bimbingan` VALUES (256, 14, 85, '2017-09-08', 'PL datang ke kelompok Jamur Tiram Sanglor II, ketemu dengan pengurus kelompok Ibu Sulasmi, PL memerikan surat kesanggupan lunas dalam tahap 3bulan lunas,Bu Sulasmi menandatangani surat penagiahan lunas dalam tahap 3x angsuran Lunas Bu sulasmi memberikan keterangan : mudah-mudahan sebelum bulan desember 2017 bisa melunasi sisa tunggakan di kelompok Jamur Tiram, dan akan mengajukan proposal permohonan pinjaman lagi ke UPK. sisa tunggakan Rp. 39.399.600 - 1.000.000 = 38.399.600 \n* Rp. 1.000.000 di angsur di tgl 08/09/2017. PL Hermanto dan Pranan Prastiwi', 989);
INSERT INTO `bimbingan` VALUES (257, 18, 416, '2017-09-12', 'Data Tunggakan per 31 Agustus 2017 di UPK Rp. 5.244.000 posisi pada\n1. Kartono Alamat Rt. 01 Rw. 03 Sisa Pinjaman Rp. 4.600.000,- kesanggupan \n    akan di angsur setiap tgl 5 per bulan mulai bulan september tgl 13 atau     \n   14. \n2. Endah Alamat Rt. 02 Rw.  05 Sisa pinjaman Rp.  700.000,- diangsur tgl 12 \n    Sept 2017 Rp 400.000 sisa Pinjaman Rp. 300.000,- \n\n0', 1220);
INSERT INTO `bimbingan` VALUES (258, 14, 87, '2017-08-21', 'PL datang kerumah Bp. Sudarmo, Total tunggakan kelompok saat ini Rp 350.000 ada di Bp Sudarmo, Dan di tgl 21 ini Bp Sudarmo nitip angsuran Rp. 50.000. sisa tunggakan Rp. 300.000. PL memberikan solusi penyelesaian tahap 3bulan lunas,dengan perincian setiap bulan Rp. 100.000. per tanggal 21/bulan. Demikian kesepakatan yang di tandatangani Bp Sudarmo bersama PL. Hermanto Dan Pranan Prastiwi', 989);
INSERT INTO `bimbingan` VALUES (259, 14, 90, '2017-08-28', 'PL datang ke kelompok Enam-Enam Pudak ketemu dengan Bp Rejo sebagai ketua kelompok, Tunggakan kelompok saat ini Rp. 3.350.000. pengurus pada saat itu nitip angsuran Rp. 100.000. sisa tunggakan Rp. 3.250.000, Tunggakan dikelompok ini tertumpu disatu orang di pengurus kelompok, Bp Rejo setiap bulannya mengangsur Rp. 150.000. dengan tunggakan sebesar itu jika angsuran setiap bulan Rp. 150.000 mau selesai kapan? PL memberikan solusi dengan skema pelunasan 3 bulan untuk kelompok Bp Rejo. jadi Bp Rejo mengangsur sebesar Rp. 1.150.000. Demikian kesepakatan yang di buat PL dan Bp Rejo.', 989);
INSERT INTO `bimbingan` VALUES (260, 14, 109, '2017-08-28', 'PL datang ke kelompok ini dan ketemu dengan Ibu Sumaryani dan tunggakan kelompok ini Rp. 22.554.500. Tunggakan ini ada di ibu Sumaryani dan saat datang menagih Ibu Sumaryani tidak mengangsur di karenakan usaha suaminya mengalami kemacetan.dan PL memberi solusi dengan skema 3X angsuran  Lunas. Jadi kelompok ini mengangsur setiap bulanya Rp. 7.518.000. dan Ibu Sumaryani menandatangani kesepakatan ini.', 989);
INSERT INTO `bimbingan` VALUES (261, 14, 109, '2017-08-28', 'PL datang ke kelompok ini dan ketemu dengan Ibu Sumaryani dan tunggakan kelompok ini Rp. 22.554.500. Tunggakan ini ada di ibu Sumaryani dan saat datang menagih Ibu Sumaryani tidak mengangsur di karenakan usaha suaminya mengalami kemacetan.dan PL memberi solusi dengan skema 3X angsuran  Lunas. Jadi kelompok ini mengangsur setiap bulanya Rp. 7.518.000. dan Ibu Sumaryani menandatangani kesepakatan ini.', 989);
INSERT INTO `bimbingan` VALUES (262, 14, 25, '2017-08-24', 'PL datang ke kelompok Dawis Apel Pgg III, Ketemu dengan Ibu Sutilah sebagai ketua kelompok,Tunggakan ada di Ibu Sutilah, Besar Tunggakan Rp. 3.950.000. Saat PL datang menagih belum bisa mengasih angsuran karena suaminya belum gajian. PL memberikan solusi untuk angsuran dalam tahap 3 bulan Lunas,jadi kelompok ini mengangsur setiap bulannya Rp. 1.317.000. PL bersama ibu Sutilah Menandatangani kesepakatan ini.Hermanto dan Pranan Prastiwi', 989);
