INSERT INTO `bimbingan` VALUES (265, 13, 253, '2017-09-19', 'kelompok dengan mayoritas usaha kerupuk ikan. ada penambahan jumlah anggota untuk pengajuan proposal kelompok tahun 2017 sebanyak  3 orang.\nnamun pada saat verifikasi ada sejumlah anggota yang tidak bisa hadir dengan alasan ttt.\ndan anggota A/N KHAIRATUN NISAK berhalangan hadir dan di wakili oleh ibu zainab, kemudian MUSLIHATI dan HAMISAH tidak hadir saat verifikas kelompok di rumah ketua kelompok (jumaati).\n', 1098);
