INSERT INTO `bimbingan` VALUES (271, 14, 317, '2017-09-25', 'Koordinator PL dan PL datang ke kelompok shinta pundung untuk melakukan pembinaan kelompok,Koordinator menanyakan ke kelompok sebab angsuran yang telat tanggal.\nketerangan dari kelompok dari anggota sudah mengangsur ke ketua kelompok sebelum tanggal pencairan,tapi ketua belum menyetorkan ke UPK, ada salah satu anggota yg meminjamkan yang bukan dari anggota pemanfaat kelompok shinta pundung.bulan depan kelompok shinta pundung akan memperbaiki angsuran sesuai dengan jadwal pencairan dari UPK.', 989);
INSERT INTO `bimbingan` VALUES (272, 14, 252, '2017-09-29', 'Koordinator dan PL datang datang ke kelompok Mekarsari waru melakukan pembinaan di kelompok ini menanyakan awal dari kemacetan angsuran,keterangan dari pengurus dan anggota,kemacetan tidak di sebabkan dari salah satu anggota di kelompok ini,tidak di slewengkan,kelompok Mekarsari waru bulan depan akan kembali ke trek angsuran sesuai jadwal pencairan dari UPK.', 989);
INSERT INTO `bimbingan` VALUES (273, 14, 103, '2017-09-28', 'PL datang ke kelompok Ngudi Makmur Klepu ketemu dengan ketua atas nama Ibu Sudaryati dan kemacetan ada di ketua dan anggota sudah lunas dengan total tunggakan Rp. 2.000.000. PL bersama Ibu Sudaryati membuat kesepakatan pelunasan tahap 3 bulan Lunas, PL memberikan masukan agar angsuran tidak hanya  Rp. 200.000. agar tunggakn  cepat lunas.', 989);
INSERT INTO `bimbingan` VALUES (274, 7, 328, '2017-09-28', 'Anggota kelompok sudah melakukan kwajibannya dalam melakukan anggsuran namun ada pemendingan dana oleh pengurus kelompok dan dana tersebut dipakai untuk keperluan pribadi sehingga terjadi kemacetan.\n\nsudah dikunjungi berkali kali dan yang bersangkutan belum menunjukan  itikad baik dalam  menyelesaikan tanggungannya. Setelah berdiskusi panjang maka disepakati yang bersangkutan akan melakukan penggangsuran setiap tanggal 20 per bulannya.', 366);
INSERT INTO `bimbingan` VALUES (275, 7, 413, '2017-10-03', 'Kemacetan terjadi di karenakan ada salah satu anggota yang tidak dapat melakukan kwajibannya dalam mrlakukan aggsuran sehingga tanggungannya makin bertambah dan besar kemungkinan tidahk dalat melakukan pelunasan tepat pada waktunya. Pemanfaat a/n Neti Setya Ningsih kiranya dapat dilakukan pemblacklisan sebab memiliki tanggungan di banyak tempat.', 366);
