INSERT INTO `bimbingan` VALUES (281, 7, 2970, '2017-10-30', 'Perlu pemantauan untuk kelompok ini dikarenakan ada beberapa anggota yang sulit untuk datang dalam pertemuan yang diselenggarakan secara berkala. Kendala pekerjaan yang tidak memungkinkan untuk pulang setiap kali.', 366);
INSERT INTO `bimbingan` VALUES (282, 7, 303, '2017-10-31', 'kelompok rencananya membubarkan diri dan berhenti, sekaligus menggkonfirmasi bahwa dana tabungan tanggung renteng digunakan untuk menutup anggsuran yang terakhir.', 366);
INSERT INTO `bimbingan` VALUES (283, 7, 328, '2017-10-21', 'perjanjian secara lisan tidak memenuhi target dan yang bersangkutan selalu janji janji tidak ditepati. Yang bersangkutan juga mengikuti program pinjaman di tempat lain.', 366);
INSERT INTO `bimbingan` VALUES (284, 14, 269, '2017-10-26', 'PL datang ke pengurus kelompok ketemu dengan Bpk Heru Suryanto dan Ibu Sikem,menanyakan tagihan tunggakan di kelompok PK Raharjo padem sebesar Rp. 3.200.000..PL memberikan solusi penyelesaian tunggakan dalam tahap 3bulan lunas di  mulai bulan november 2017.', 989);
INSERT INTO `bimbingan` VALUES (285, 14, 18, '2017-11-01', 'PL datang ke kelompok Banowati Panggang I ketemu dengan pengurus kelompok Ibu Marsiyem, menanyakan tunggakan kelompok sebesar Rp. 4.770.000, PL memberikan opsi penyelesaian tunggakan di kelompok ini dengan skema 3bulan lunas.Ibu Marsiyem menandatangani Surat Penyelesaian Tunggakan dalam tahap 3bulan lunas.', 989);
INSERT INTO `bimbingan` VALUES (286, 14, 20, '2017-10-07', 'PL datang ke kelompok ketemu dengan pengurus Ibu Marsiyem,Tunggakan di kelompok ini sebear Rp. 2.150.000, PL memberikan opsi penyelesaian tunggakan dalam tahap 3bulan lunas, Pengurus kelompok Srikandi B Panggang I Ibu marsiyem menandatangi surat penyelesaian tunggakan dari PL. Angsuran di mulai dari bulan november 2017 per tgl 15.', 989);
INSERT INTO `bimbingan` VALUES (287, 17, 576, '2017-10-25', 'Merupakan kelompok baru, pd bulan oktober adl angsuran ke-3 tetapi sudah mengalami tunggakan angsuran, anggota yang menunggak pd bulan ini adalah Ibu Rini Yulianti kasus meninggalkan rumah ', 1132);
INSERT INTO `bimbingan` VALUES (288, 17, 4, '2017-08-29', 'Penanganan masalah di Rumah Bpk Rukiman (suami Ibu Ngatinem)\n1). Dari 10 anggota terdapat 5 anggota bermasalah yaitu Suprih, Enik, Ngatiyem , Yainah dan Fita menunggak dari Bulan Juni 2017,\n2). Pinjaman atasnama Ibu Ngatiyem digunakan ibu Enik, Pinjaman Ibu Fita digunakan Ibu Yainah.\n3). 5 anggota yang lain masih sanggup untuk melanjutkan mengangsur, yaitu Sutinem, Sulis, Surip, Ngatinem dan Susilo mulai bulan September 2017\n', 1132);
INSERT INTO `bimbingan` VALUES (289, 17, 180, '2017-09-27', 'Tidak jalannya tanggung renteng, penanganan masalah dihadiri 7 orang anggota, permasalahan ada 1 orang anggota yaitu IBU ISNAWATI yang menunggak pada angsuran ke 5, dikesepaki sbb : \n1). kelompok sepakat kas digunakan unt angsuran Isnawati (SALDO ANGS   IPTW); \n2). Pemegang uang kas sanggup memenuhi angsuran ke UPK; \n3). Pinjaman ke 11, ditambah iuran per orang Rp. 10.000 untuk 4 bulan (Oktober 2017 - Januari 2018) jumlah 40.000/orang;\n4). Angsuran ke 12 harus ada yang bertanggungjawab menggenapi angsuran', 1132);
INSERT INTO `bimbingan` VALUES (290, 17, 180, '2017-07-31', 'Ibu Suharsi dan Bp. Sugeng menemui BAPAK SIHONO (suami IBU ISNAWATI), menyatakan :\n1). Bpk Sihono menyatakan bahwa hanya menunggak 1 bulan (Juli) saja;\n2). Bersedia membayar angsuran apabila ibu ketua (Septi Sujarwati) mau meminta maaf kepada Ibu Isnawati di tempat kerja, karena sebelumnya ibu Septi pernah menagih Ibu Isna dnegan ucapan yang tidak berkenan;\n3). Merasa statement no.2 tidak ditanggapi oleh Ibu Septi, Bp. Sihono menyerahkan beban angsuran ke Ibu Septi, Bpk Sihono tidak bersedia membayar kekurangan angsuran, karena diawal tahunya ibu Isna hanya pinjam 1 juta', 1132);
INSERT INTO `bimbingan` VALUES (291, 21, 636, '2017-11-17', 'Kelompok tersebut telah dilakukan perpanjangan angsuran selama 4 bulan terhitung mulai desember 2017 sd maret 2018. selanjutnya tidak bisa dilakukan perpanjangan waktu.', 1906);
