INSERT INTO `bimbingan` VALUES (296, 14, 330, '2017-11-13', 'PL datang ke kelompok SAMAN PANGGANG III, ketemu dengan pengurus kelompok Bpk Amar Hidayat,Pl menanyakan Tunggakan di kelompok tersebut agar segera di lunasi,Pl memberikan opsi pengangsuran dengan skema 3 (tiga) hari sekali angsur Rp. 150.000. di mulai tgl 14 November 2017, dan seterusnya berjalan dengan skema tersebut samapai lunas di kelompok SAMAN PANGGANG III.PL Hermanto', 989);
INSERT INTO `bimbingan` VALUES (297, 14, 330, '2017-11-14', 'PL datang ke kelompok SAMAN PANGGANG III menanjihkan kesepakatan antara PL dengan Pengurus kelompok, pengurus kelompok mengangsur sesuai dengan kesepakatan yang telah di buat. Rp 150.000', 989);
