INSERT INTO `bimbingan` VALUES (301, 14, 85, '2017-11-30', 'Koordinator PL dan PL datang ke kelompok Jamur Tiram Sanglor II menanyakan progres penyelesaian tunggakan,koordinator PL memberikan surat penyelesaian kepada pengurus kelompok dalam skema 6bulan, Koordinator pl juga menyarankan kepada pengurus kelompok untuk menjualm aset Tanah atau barng yang bisa di jual untuk penyelesaian tunggakan di UPK-PPM PANGGANG.Koordinator PL dan PL menyurvei Tanah yang di jadikan sebagai anggunan untuk di jual bersama yang hasil dari penjualan tanah akan di bayarkan ke UPK-PPM PANGGANG untuk melunasi tunggakan kelompok Jamur Tiram.', 989);
INSERT INTO `bimbingan` VALUES (302, 14, 310, '2017-11-25', 'PL datang ke kelompok Banowati Pundung ketemu dengan Pengurus kelompok untuk menanyakan tunggakan di kelompok tersebut, Anggota kelompok menitipkan angsuran Rp. 500.000 dan anggota lain akan mengangsur di tanggal 30.11.2017 karena anggota yang lain masih kerja proyek di Wates.PL meminta ke peda pengurus kelompok agar segera melunasi sisa tunggakan di 3bulan agar kembali ke trek angsuran lancar,kemacetan ada di semua kelompok Banowati Pundung.', 989);
