INSERT INTO `bimbingan` VALUES (305, 8, 9, '2017-12-18', 'Hari Senin 18 Des 2017\nAngsuran Mawar 2 Bonto-bontoa kurang Rp. 100.000 dari target yg harus dibayar Rp. 6.149.000. Total terbayar Rp. 6.049.000\nTerdapat Tunggakan pada kelompok tersebut sebesar Rp. 2.375.000,- sampai dengan bulan ini atas nama KR. NANNA dengan rincian sbb :\nJumlah Pinjaman 5.000.000,-\nAngsuran 475.000 /bulan\nTunggakan sementara sejak bulan Agustus (angs. 2) s/d Desember (angs. 6) Rp. 2.375.000.....................  ', 2);
