INSERT INTO `bimbingan` VALUES (311, 18, 3188, '2017-12-21', 'pencairan perguliran di desa kedawung kelompok gang krajan dihadiri oleh semua anggota,ada 3 anggota yang tidak bisa masuk direkomendasi pencairan karena tidak mendapat rekomendasi dari tim pendanaan. Untuk desa kedawung belum bisa memasukan anggota baru karena masih banyaknya kelompok yang menunggak. ', 1423);
INSERT INTO `bimbingan` VALUES (312, 18, 3026, '2017-12-20', 'Ketua kelompok dlingo indah ibu Sartini sedang diJakarta sehingga angsuran kelompok belum bisa masuk dan 1 anggota ibu Munjariyah belum mengirimkan uang ke keluarganya.', 1423);
INSERT INTO `bimbingan` VALUES (313, 18, 2958, '2017-12-19', 'Kunjungan ke ketua kelompok serbaguna bersama ibu Ana,identifikasi tunggakan kelompok ternyata dipakai oleh ketua kelompok\nMasuk ansuran hari itu sebesar Rp 2.800.000.', 1423);
