INSERT INTO `bimbingan` VALUES (371, 18, 3026, '2018-01-08', 'Hasil identifikasi Kel Dlingo, bahwa tunggakan ada pada beberapa anggota\n1. Bu Sartini 3 bulan = 900.000  memakai punya anggota 700.000\n2. Bu Munawarotun  300.000\n3. Munjariyah 900.000\n4. Juni 200.000\n5.Sriyati 200.000\n6. Asiyah 600.000\n7. Siti khotijah.200.000', 1423);
