INSERT INTO `bimbingan` VALUES (375, 8, 93, '2018-01-11', 'Melakuka Kunjungan kelompok dalam rangka identifikasi Masalah Tunggakan. Hasil yang dicapai :\nTunggakan sebesar Rp. 5.411.000,- adalah tunggakan atas nama Ketua kelompok (Bakti Ibu) an. SYAMSIAR NIK. 7303045510790001 Alamat Labbo Dusun Pattiro. Dana tersebut merupakan Angsuran kelompok yang digunakan yang bersangkutan secara pribadi.', 1);
INSERT INTO `bimbingan` VALUES (376, 8, 87, '2018-01-11', 'Identifikasi kelompok Bermasalah. Tunggakan Klpk Kasih Ibu Labbo sebesar Rp. 5.643.100,- adalah tunggakan an. ST. SYAMSIAH dan menjadi tunggakan pribadi, jabatan Ketua Kelompok. Dana tersebut merupakan angsuran Anggota yang dipergunakan yang bersangkutan secara pribadi', 1);
INSERT INTO `bimbingan` VALUES (377, 8, 80, '2018-01-11', 'Identifikasi Kelompok bermasalah: Tunggakan Kelompok sebesar Rp. 9.463.500,- adalah tunggakan an. ERNIWATI NIK. 7303045808780003 Jabatan Ketua kelompok. Dana tersebut adalah angsuran anggota yang digunakan yang bersangkutan secara pribadai. Masalah yang bersangkutan adalah Gagal Usaha (ternak ayam potong) sehingga sempat menggunakan angsuran tersebut untuk membiayai usaha yang dimaksud. yang bersangkutan menunjukkan etikad yang baik untuk membayar namun masih terlilit utang ditempat dan orang lain selain di UPK.', 1);
INSERT INTO `bimbingan` VALUES (378, 8, 79, '2018-01-11', 'Identifikasi kelompok bermasalah : Klp tersebut memiliki Tunggakan Rp. 1.846.100,-  dari tunggakan tersebut adalah tunggakan an. DARMI Nik. 7303045108860004 Jabatan Ketua Kelompok. dana tersebut digunakan yg bersangkutan secara pribadi. dan menjadi tunggakan pribadi bukan lagi tunggakan kelompok.', 1);
