INSERT INTO `bimbingan` VALUES (395, 13, 281, '2018-01-20', 'Hasil bimbingan pengisian administrasi kelompok Bunga Sakura pada hari ini, mohon untuk melanjutkan pengisian buku administrasi kelompok sesuai yang telah dipelajari bersama. Untuk segera diselesaikan diantaranya:\n-Buku Kas harian \n-Buku Realisasi Angsuran\n-Buku Bank kelompok\nsetelah dikerjakan mohon untuk dikoreksikan ke UPK dan dilanjutkan pengerjaan buku administrasi lainnya.', 1182);
