INSERT INTO `bimbingan` VALUES (522, 14, 91, '2018-03-02', 'pl datang ketemu dengan bpk sriyanto dan belum bisa angsur karena uang macet di dagangan kayu belum di bayar Pl suruh datang lagi tgl 25-3-2018 dan kalau udah ada uang akan nitip saldo Rp 11.100.000.', 989);
INSERT INTO `bimbingan` VALUES (523, 14, 23, '2018-03-02', 'pl datang ke kelompok Sitisendari panggang 1, rumah kosong.saldo Rp.2.210.000.', 989);
INSERT INTO `bimbingan` VALUES (524, 14, 67, '2018-03-02', 'Pl datang ke kelompok Fajar Lestari Gebang rumah kosong  tetapi ketemu dengan tetangga ibu yusmiyati dan ibu keni saldo RP 770.000', 989);
INSERT INTO `bimbingan` VALUES (525, 14, 258, '2018-03-03', 'Pl  datang di kelompok Dele saputri ketemu dengan swaminya ibu ketua  bpk Suryadi dan mau nitip tgl 24-02-12018 saldo Rp.12.240.000.', 989);
INSERT INTO `bimbingan` VALUES (526, 14, 52, '2018-03-03', 'Pl  datang ke kelompok rumah kosong ,Pl menghubungi lewat via telpon pak warno sedang diladang, dan dia bilang mau nitip angsuran di tgl 26-03-2018 saldo Rp 2.460.000', 989);
INSERT INTO `bimbingan` VALUES (527, 14, 68, '2018-03-03', 'pl datang ke kelompok rumah suwung, dan ketemu dengan tetangga dan mereka bilang ibu dewi ke ladang pulang sore,dan akan kembali tanggal 25-03-2018 saldo Rp 2.870.000', 989);
INSERT INTO `bimbingan` VALUES (528, 14, 26, '2018-03-03', 'tidak ketemu dengan ibu Sunarti beliau bekerja di Jakarta saldonya Rp.3.180.000', 989);
INSERT INTO `bimbingan` VALUES (529, 14, 59, '2018-03-05', 'Pl datang ke kelompok sumber makmur sanglor I,tidak ketemu dengan pengurus kelompok, beliau kerja di palembang, bercerai dengan suaminya.saldo Rp. 6.500.000', 989);
INSERT INTO `bimbingan` VALUES (530, 14, 53, '2018-03-06', 'Pl datang ke kelompok ketemu dengan istri maryadi,ibu erni bilang hari rabu maryadi mau angsur lewat transfer, saldo tunggakan Rp. 1.530.000', 989);
INSERT INTO `bimbingan` VALUES (531, 14, 27, '2018-03-05', 'Pl datang ke rumah Bp sariman, rumah kosong.\nsaldo tunggakan Rp. 3.240.000', 989);
INSERT INTO `bimbingan` VALUES (532, 14, 223, '2018-03-00', 'Pl datang ke kelompok, ketemu dengan pengurus kelompok Ibu surajinem, pengurus kelompok nitip angsuran Rp. 200.000\nsaldo tunggakan 10.460.000', 989);
INSERT INTO `bimbingan` VALUES (533, 14, 94, '2018-03-06', 'Pl datang ke kelompok ,ketemu dengan pengurus kelompok Bp Susanto,\nnitip angsuran Rp. 200.000.\nsaldo tunggakan Rp. 600.000', 989);
INSERT INTO `bimbingan` VALUES (534, 14, 210, '2018-03-07', 'PL datang ketemu dengan salah satu anggota kelompok bernama ibu tugini, dan menjelaskan bahwa ketua kelompok pergi kerja ke jakarta dan jarang pulang.anak nya juga kerja,saldo tunggakan masih Rp 5.895.000', 989);
INSERT INTO `bimbingan` VALUES (535, 14, 208, '2018-03-07', 'PL datang ke rumah ibu sutiyem ketua kelompok dan rumah kosong, kata tetangga  baru keladang pulang sore hari,keterangan ibu jumirah.saldo tunggakan Rp2.575.000', 989);
INSERT INTO `bimbingan` VALUES (536, 14, 134, '2018-03-07', 'PL datang ketemu Bp darso sadiyun. dan menjelaskan bahwa kelompok sudah lunas sudah angsur ke petugas UPKD (bp hardi santoso) dan th 2014 bersama TPM sudah datang kerumah Bp hardi dan BP hardi sudah mengakui bahwa kelompok ini sudah angsur lunas, saldo tunggakan Rp7.800.000', 989);
INSERT INTO `bimbingan` VALUES (537, 14, 131, '2018-03-07', 'PL datang ketemu Bp Mudoso dan menurut penjelasan nya bahwa kelompok sudah lunas karena sudah setor ke petugas UPKD, BP hardi santoso.dan waktu bareng TPM th 2014 bp hardi santoso sudah ketemu dengan bp mudoso dan bp hardi sudah mengakui nya.saldo tunggakan Rp3.200.000', 989);
INSERT INTO `bimbingan` VALUES (538, 14, 60, '2018-03-08', 'PL datang ketemu dengan ketua kelompok dan menjelaskan bahwa tunggakan tertumpu pada ibu endah herwanti,dan harapan bp suhadi untuk bisa ketemu dengan ibu endah herwanti. saldo tunggakan Rp 9.250.000', 989);
INSERT INTO `bimbingan` VALUES (539, 14, 64, '2018-03-07', 'PL datang ketemu ibu  sumarsi ketua kelompok ,menjelaskan bahwa tunggakan masih ada di anggota dan mau di kumpulkan. ibu ketua sudah lunas.saldo tunggakan Rp3.692.000', 989);
INSERT INTO `bimbingan` VALUES (540, 14, 24, '2018-03-08', 'PL datang kerumah ibu tusilah selaku ketua kelompok dan hanya ketemu agung sodaranya karena ibu tusilah baru pergi ngajar,PL datang untuk mengantar surat tagihan dan undangan.saldo tunggakan Rp 6.405.000', 989);
INSERT INTO `bimbingan` VALUES (541, 14, 63, '2018-03-08', 'PL datang  ketemu dengan suami pengurus kelompok yg bernama bp sutari,menjelaskan bahwa ibu indarti pergi kerja ke taiwan dengan kontrak kerja 3 th dan baru dapat 1,5 th,bp sutari tidak mengetahui periha pinjaman di upk karena pada saat angkat kredit bp sutari kerja di sumatra.saldo tunggakan Rp 6.000.000', 989);
INSERT INTO `bimbingan` VALUES (542, 14, 69, '2018-03-07', 'PL datang ketemu dengan bp wakijan dan kelompok ini rutin angsur di tgl 25 tiap bln nya,saldo tunggakan Rp 450.000', 989);
INSERT INTO `bimbingan` VALUES (543, 14, 296, '2018-03-06', 'PL datang  tidak ketemu dengan pengurus kelompok karena bp dwi aryanto pergi ke klaten dan sudah pisah dengan istri nya.mantan istrinya kerja di  jogja  keterangan dari tetengganya ibu wiwid.saldo tunggakan Rp 564.000', 989);
INSERT INTO `bimbingan` VALUES (544, 14, 92, '2018-03-08', 'PL datang kerumah bp sukoco ketua kelompok dan rumah dalam keadaan kosong,di telp  bp sukoco blang mau nitip angsuran tgl 20-3-2018.saldo tunggakan Rp1.100.000', 989);
INSERT INTO `bimbingan` VALUES (545, 14, 6, '2018-03-08', 'PL datang ke rumah bp rajiyo tapi kosong,menurut keterangan tetangganya bp rajiyo pergi ke wonosari jagong pulang sore, saldo tunggakan Rp 11.240.000', 989);
INSERT INTO `bimbingan` VALUES (546, 22, 575, '2018-03-14', 'Dikunjungi pada tanggal 14 Maret 2018, ditemui ketua kelompok (Praptiningsih), tunggakan akan diangsur  setelah padi dijual (perkiraan seminggu)', 1492);
INSERT INTO `bimbingan` VALUES (547, 22, 575, '2018-03-14', 'Kelompok ini sudah menunggak lama tetapi pembayarannya lama dan dengan jumlah yang kurang jauh dibanding jumlah tunggakan. Dikunjungi pada tanggal 14 Maret 2018, ditemui ketua kelompok (Praptiningsih), tunggakan akan diangsur  setelah padi dijual (perkiraan seminggu)', 1492);
INSERT INTO `bimbingan` VALUES (548, 22, 574, '2018-03-14', 'Kelompok ini sudah menunggak lama, tetapi angsurannya sedikit tidak sesuai dengan jumlah tunggakan. Pada Selasa tanggal 6 Maret 2018 dikunjungi bersama Polsek dan Danramil serta Satpol PP. Hasilnya akan diangsur mulai akhir Maret 2018, membuat surat pernyataan pengakuan hutang dan kesanggupan pembayaran/angsuran. ', 1492);
INSERT INTO `bimbingan` VALUES (549, 22, 574, '2018-03-06', 'Kelompok ini sudah menunggak lama, tetapi angsurannya sedikit tidak sesuai dengan jumlah tunggakan. Pada Selasa tanggal 6 Maret 2018 dikunjungi bersama Polsek dan Danramil serta Satpol PP. Hasilnya akan diangsur mulai akhir Maret 2018, membuat surat pernyataan pengakuan hutang dan kesanggupan pembayaran/angsuran. ', 1492);
