INSERT INTO `bimbingan` VALUES (553, 7, 448, '2018-03-14', 'Pada saat pencairan yang dillaksanakan sesuai jadwal (terlampir) anggota yang hadir hanya 13 orang sebab ada salah satu anggota yang mengundurkan diri a/n RATNA ANDRYANI karena besar pinjaman tidak sesuai dengan pengajuan (disetujui TV 1.000.000,-)', 366);
INSERT INTO `bimbingan` VALUES (554, 7, 891, '2018-03-15', 'Kelompok penganggsuran selalu terlambat dan ikatan tanggung renteng tidak berjalan baik, sehingga riwayat pengangsuran tidak bagus. Ada indentifikasi bahwa pinjaman tidak sesuai dengan realisasi di masing-masing orang, Pengurus juga lupa besaran pinjaman tahun yang lalu sebab ada kaitannya tentang uang yang dipakai oleh seserang yang tidak termasuk dalam keanggotaan disamping itu buku administrasi ketika d Verifikasi tidak dapat menunjukkan.', 366);
INSERT INTO `bimbingan` VALUES (555, 7, 3988, '2018-03-17', 'salah satu anggota a/n Mutmainah menggunakan dana untuk keperluan pribadi (membenahi teras rumah yg ambruk) di bulan Feb 2018\nDibulan Maret kelompok mengangsur namun tidak penuh sebab ada salah satu anggota a/n wilmawati tidak melakukan kewajibannya selama 2 bulan yaitu bulan feb-mart 2018', 366);
INSERT INTO `bimbingan` VALUES (556, 7, 450, '2018-03-18', 'Kelompok melakukan pengangsuran pada bulan maret sedikit demi sedikit dengan penanganan pendamping kelompok SPP. Tetap tertangani secara intensif untuk progress penagiahan dan penyelesaian masalah kelompopk di desa Duwet Krajan.', 366);
INSERT INTO `bimbingan` VALUES (557, 18, 514, '2018-03-20', 'Tabungan wajib kelompok amanah sejumlah Rp. 1.100.000,00 ( Satu juta seratus ribu rupiah ) telah di keluarkan dan dimasukan ke angsuran kelompok per tanggal 19 Maret 2018', 1209);
