INSERT INTO `bimbingan` VALUES (559, 18, 599, '2018-03-20', 'Tabungan wajib kelompok flamboyan sejumlah Rp. 1.200.000,00 ( Satu juta dua ratus ribu rupiah ) telah dikeluarkan dan dimasukan ke angsuran kelompok per tanggal 19 Maret 2018', 1209);
