INSERT INTO `bimbingan` VALUES (577, 18, 2842, '2018-03-21', 'Anggota yang mengangsur:\n1. Agus Supradi Rp. 150.000\n2. Mukhanip pinjaman Rp. 1.500.000,00 dan sudah ngansur lunas\n3. Supardani Pinjaman Rp. 1.500.000,00, angsuran pertama sejumlah Rp. 150.000, 00 di setorkan ke ketua kelompok dan sudah ngasur selain di ketua 9 x Rp. 150.000,00 s.d bln Maret 2018 berarti masih kurang 2 X ansuran yaitu sejumlah Rp. 300.000,00', 1209);
INSERT INTO `bimbingan` VALUES (578, 18, 3088, '2018-03-21', '1. Angsuran sejumlah Rp. 10.542.000,00 adalah angsuran a.n alm Tarsinah yang diambilkan dari dana alokasi cadangan resiko yang di keluarkan per tanggal 27 Februari 2018 dan hanya hapus buku bukan hapus mutlak, dan apabila di kemudian hari ada angsuran yang masuk akan menjadi pendapatan lain-lain', 1209);
INSERT INTO `bimbingan` VALUES (579, 4, 6868, '2018-03-21', 'pengajuan ke dua pinjamannya dipakai untuk MT ke-2.  pinjaman meningkat 2x dari pinjaman lama.', 130);
INSERT INTO `bimbingan` VALUES (580, 18, 2987, '2018-03-21', '1. Kurangan angsuran s.d bulan Maret 2018 a,n Sri Rohyani kurang 6x dengan total sebesar Rp. 3.600.000,00 dengan pinjaman sejumlah Rp. 6.000.000,00  ', 1209);
