INSERT INTO `bimbingan` VALUES (582, 18, 585, '2018-03-22', 'Tgl 1 Maret 2018 angsuran sejumlah Rp. 1.233.000,00 dengan perincian:\n1. SUdaryanti            =Rp. 685.000,00\n2. Siti Nur Fatimah   =Rp. 205.500,00\n3. Ngadiatun             =Rp. 137.000,00\n4. Rustini                   =Rp. 137.000,00\n5. Tunjiati                  =Rp.   68.500,00', 1209);
