INSERT INTO `bimbingan` VALUES (584, 18, 585, '2018-03-22', 'Tgl 8 Maret 2018 angsuran sejumlah Rp. 1.979.500,00 dengan perincian:\n1. Waginem Rp. 1.500.000,00\n2. Endah Rp. 342.500,00\n3. Muslimah Rp. 137500,00', 1209);
INSERT INTO `bimbingan` VALUES (585, 18, 585, '2018-03-22', 'Tgl 14 Maret 2018 agsuran A.n Siti Nur Fatimah, sejumlah Rp. 261.000,00\ndengan keterangan sbb:\nPinjaman Rp. 3.000.000,00 dengan angsuran setiap bulan sejumlah Rp. 205.500,00 \nsementara untuk angsuran 2 bulan sejumlah Rp. 411. 000,00 dan dikurangi tabungan wajib Rp. 150.000,00 ', 1209);
