INSERT INTO `bimbingan` VALUES (590, 22, 621, '2018-03-27', 'Dikunjungi terakhir pada hari Kamis tanggal 22 Maret 2018, bersama Polsek dan Danramil. Setelah dikumpulkan hanya 5 orang yang hadir. Ketua kelompok tidak mengetahui detail catatannya karena dibawa bendahara yang saat ini bekerja di Surabaya. Dari anggota didapat pengakuan bahwa rata-rata mereka membayar angsuran baru 2 kali. Waktu dimintai surat pernyataan belum bersedia karena pengurus belum koordinasi. Semetara untuk bulan April 2018 anggota mulai akan mengangsur lagi.', 1492);
INSERT INTO `bimbingan` VALUES (591, 22, 1419, '2018-03-22', 'Kunjungan akan dilaksanakan pada tanggal 22 Maret 2018 bersama Polsek dan Danramil, tetapi pengurus tidak mau dikunjungi. Akhirnya diadakan pertemuan di kantor UPK. Ketua kelompok membuat surat pernyataan mulai April akan diangsur minimal Rp. 500.000,-   ', 1492);
INSERT INTO `bimbingan` VALUES (592, 18, 585, '2018-03-27', 'CATATAN pinjaman riil di kelompok saat dipKetuai Bu Ani S :\n1. Indah S : SPK 6jt Riil 5 Jt\n2. Yulianti : SPK 15jt Riil 13jt\n3. Atin : SPK 15jt Riil : 13jt\n4. Diana : SPK 2jt Riil:2jt\n5. Siti Nurfatimah :SPK 4jt Riil : 3jt\n6. Rustini : SPK 6jt Riil 2jt\n7. Nurfatonah : SPK 15jt Riil 13jt\n8. Ngadiyatun : SPK 2 Riil 2jt\n9. Waginem : SPK 15jt Riil : 14jt\n10. Sudaryanti : SPK 15jt riil : 10jt', 1207);
