INSERT INTO `bimbingan` VALUES (595, 18, 740, '2018-03-27', 'Pencairan Perguliran Kel Seroja Prigi, di Kantor UPK, sebesar Rp.50.000.000,;((Lima puluh juta rupiah) diterima oleh Sdr Umi Indahsari, Karti dan Soimah, ', 1423);
INSERT INTO `bimbingan` VALUES (596, 22, 1421, '2018-03-05', 'Dikunjungi bulan Maret 2018, Kepengurusan sudah tidak berjalan. Ketua kelompok tidak tahu menahu masalah setoran, tetapi siap kalau rumahnya ditempati untuk klarifikasi atau penyelesaian tunggakan. Koordinator Kelompok (sdr. Khusnul Khotimah) tidak diketahui keberadaannya. Ketika di datangi ke rumahnya yang ada hanya anaknya. Kelompok ini sudah diresceduling.', 1492);
INSERT INTO `bimbingan` VALUES (597, 14, 126, '2018-03-02', 'PL datang ketemu dengan  ibu karmi dan menjelas kan kepada PL  bahwa dulu kelompok  sudah angsur ke UPKD ,dan kepada PL bu karmi menunjujkan bukti  kwitansi. saldo tunggakan Rp 1.800.000', 989);
INSERT INTO `bimbingan` VALUES (598, 14, 136, '2018-03-02', 'PL datang tidak ketemu dengan bp supadi,rumah dalam keadaan kosong,PL akan kembali tgl 02-04-2018', 989);
INSERT INTO `bimbingan` VALUES (599, 14, 288, '2018-03-02', 'PL datang kekelompok  rumah kosong,karena pengurus kelompok kerja Proyek dan pulang tidak  tentu, agenda PL datang lagi tgl 13-3-18', 989);
INSERT INTO `bimbingan` VALUES (600, 14, 288, '2018-03-02', 'PL datang kekelompok  rumah kosong,karena pengurus kelompok kerja Proyek dan pulang tidak  tentu, agenda PL datang lagi tgl 13-3-18', 989);
INSERT INTO `bimbingan` VALUES (601, 14, 190, '2018-03-28', 'PL datang ketemu dengan ketua  kelompok  ibu iswandari, dan nitip angsuran Rp 100.000 dan tgl 2-4-18 mau nitip lagi.saldo tunggakan  Rp 3.500.000', 989);
INSERT INTO `bimbingan` VALUES (602, 14, 128, '2018-03-02', 'PL datang ketemu Bp yanto wiharjo pengurus kelompok, menjelas kn kepada Pl bahwa dulu pak yanto adalah ketua RT dan pak yanto tidak tahu harus mencari kemana data pemanfaat karena pak yanto tidak merasa berhutang dan  di jadikan ketua juga tidak tahu karena dulu hanya di suruh mengumpul kan Foto copy KTp,saldo tunggakan Rp5.628.000', 989);
INSERT INTO `bimbingan` VALUES (603, 14, 268, '2018-03-28', 'PL datang hanya ketemu tetangga nya bernama ibu widiyati rumah pak wariso kosong karena  pergi kerja proyek dan pulang  tidak tentu bisa 2/3 minggu.saldo tunggakan Rp 5.280.000', 989);
INSERT INTO `bimbingan` VALUES (604, 14, 16, '2018-03-03', 'PL datang tidak ketemu ibu heni,hanya ketemu ibunya ibu amin,dan menjelaskan  bahwa ibu heni dilkat di wonosari. saldo tunggakan Rp3.300.000', 989);
