INSERT INTO `bimbingan` VALUES (674, 13, 401, '2018-04-19', 'Kelompok Dasawisma Cucu Campa mengalami tunggakan yang perlu penanganan serius, kita sudah mengidentifikasi tunggakan masing-masing anggota dan sudah membuat surat pernyataan akan tetapi sampai saat ini masih belum tuntas, tentunya permasalahan dikelompok ini berasal dari  Ketua pengurus dan anggota peminjam.', 1097);
INSERT INTO `bimbingan` VALUES (675, 13, 262, '2018-04-19', 'Kelompok fatayat Pudakittimur termasuk kelompok yang baik tidak pernah ada tunggakan, beberapa bulan lagi akan lunas sehingga perlu pengajuan proposal lagi untuk medapatkan pinjaman kembali, dalam bimbingan ini kita menanyakan permasalahan apa yang dihadapi kelompok ini selama setahun, dan menyarankan untuk melengkapi semua berkas proposal baik KK ataupun KTP masing-masing anggota, serta mencari anggota baru yang mempunyai keinginan untuk pinjam uang. ', 1097);
