INSERT INTO `bimbingan` VALUES (678, 13, 262, '2018-04-10', 'Kelompok fatayat Pudakittimur termasuk kelompok yang baik tidak pernah ada tunggakan, beberapa bulan lagi akan lunas sehingga perlu pengajuan proposal lagi untuk medapatkan pinjaman kembali, dalam bimbingan ini kita menanyakan permasalahan apa yang dihadapi kelompok ini selama setahun, dan menyarankan untuk melengkapi semua berkas proposal baik KK ataupun KTP masing-masing anggota, serta mencari anggota baru yang mempunyai keinginan untuk pinjam uang. ', 1097);
INSERT INTO `bimbingan` VALUES (679, 13, 263, '2018-04-10', 'Kelompok Fatayat 2 Pudakitbarat beberapa bulan lagi akan lunas, sehingga untuk memperpanjang pinjaman kelompok perlu pembuatan proposal baru yang dilengkapi dengan foto copy KTP dan KK, Dalam bimbingan ini kita menanyakan permasalahan yang dihadapi kelompok selama satu tahun, dan meminta saran dan kritikan dari kelompok untuk kemajuan kita bersama, kita juga menyarankan agar kelompok menambah anggota peminjam agar orang-orang yang ini meminjam uang bisa difasilitasi.', 1097);
