INSERT INTO `bimbingan` VALUES (704, 14, 274, '2018-05-13', 'PL datang ke kelompok PK ngudi makmur padem mengadakan pertemuan kelompok untuk mengklarifikasi tunggakan yang ada di kelompok PK Ngudi Makmur Padem. Tunggakan Rp. 8.221.300, kelompok nitip angsuran Rp.693.000,jadi saldo tunggakan bulan mei Rp. 7.528.300.\ndan di sepakati dengan pertugas dari UPK dengan skema 6 bulan Lunas. di mulai tgl 21-06-2018', 989);
INSERT INTO `bimbingan` VALUES (705, 14, 109, '2018-05-25', 'PL datang kekelompok ketemu dengan ibu sumaryani dan melanjut kan  skema yang 3x lunas ibu sumaryani keberatan jadi ibu sumaryani mengajukan ke 6x.jadi setiap bulan ibu sumaryani mengangsur Rp3.900.000. dengan jaminan sebidang tanah pekarangan dan bangunan milik suaminya yaitu milik bp supomo,apabila sampai jatuh tempo belum lunas jaminan itu bisa di uangkan.', 989);
INSERT INTO `bimbingan` VALUES (706, 14, 270, '2018-05-09', 'PL datang kekelompok ketemu dengan semua anggota kelompok yang macet,dan ada kesepakatan untuk melumasi tumggakan selama 6 bulan lunas,setiap bulan kelompok mengangsur Rp 254.200, total saldo tunggakan Rp 1.525.000.dengan jaminan  sebidang tanah pekarangan.', 989);
INSERT INTO `bimbingan` VALUES (707, 14, 210, '2018-06-12', 'PL datang kekelompok dan anggota kelompok yang belum lunas berkumpul dan  terjadi kesepakatan  untuk melunasi pinjaman selama 6 bulan lunas,dengan angsuran setiap bulan RpRp 889.200 dengan total tunggakan Rp5.835.000 dengan jaminan  sebidang tanah pekarangan,', 989);
INSERT INTO `bimbingan` VALUES (708, 14, 332, '2018-05-25', 'PL datang ketemu dengan ibu rukini dan ibu musini yang masih mempunyai tunggakan di upk dan terjadi kesepakatan untuk melunasi  di 6 bulan lunas.total tunggakan Rp 2.600.000 jadi setiap bulan mengangsur Rp435.000 dengan jaminan 6 ekor kambing.', 989);
