INSERT INTO `bimbingan` VALUES (715, 13, 198, '2018-05-31', 'setelah identifikasi hasil kunjungan ke kelompok. ada beberapa faktor penyebab terjadinya tunggakan , a.l:\n1. pengurus kelompok / ketua kurang tertib dalam hal pencatatan atau administrasi\n2. angsuran anggota kelompok dasawisma cucu campa 5 di setorkan ke kelompok lain ( dasawisma cucu campa 1) dengan tujuan agar kelompok dasawisma cucu campa 1 segera lunas dan segera cair.\n3. anggota kelompok melakukan pembayaran /angsuran selain ke pengurus kelompok (TPM) TANPA SEPENGETAHUAN pengurus kelompok', 1098);
INSERT INTO `bimbingan` VALUES (716, 13, 204, '2018-05-31', 'beberapa faktor penyebab adanya tunggakan, a.l:\n1. ada anggota yang sedang pergi ke luar negeri (malaysia) yang belum mengangsur a/n: nur madiya dan nur Jumaida selama -  3 bulan.', 1098);
INSERT INTO `bimbingan` VALUES (717, 13, 210, '2018-05-09', 'kelompok ini cukup bagus  dan pernah mendapatkan IPTW karena angsuran lancar dan tepat waktu. namun pada saat verifikasi kelompok di rumah pengurus kelompok, ada beberapa yang belum bisa hadir di karenakna komunikasi antara pengurus dan anggota kurang terjalin dengan baik. sehingga ada beberapa anggota yang menyusul .', 1098);
INSERT INTO `bimbingan` VALUES (718, 18, 537, '2018-06-28', 'Angsusran tgl 19 Maret 2018 sejumlah Rp. 425.000,00 adalah menggunakan tabungan wajib', 1209);
