INSERT INTO `bimbingan` VALUES (720, 14, 22, '2018-08-06', 'PL datang ke ketua kelompok dan sesuai dengan apa yang telah disekma selama 6x angsuran lunas. bu darwanti  nitip angsuran Rp 450.000. saldo  tunggakan Rp 2.200.000', 989);
INSERT INTO `bimbingan` VALUES (721, 14, 71, '2018-06-05', 'PL berkomunikasi  dengan penanggung jawab tunggakan  ibu sujiyem melalui telp,karena ibu sujiyem  berada di jakarta,dan ibu sujiyem punya itikad baik dengan mentransfer Rp 800.000, saldo tunggakan masih Rp 2.434.000', 989);
INSERT INTO `bimbingan` VALUES (722, 14, 71, '2018-06-28', 'PL berkomunikasi  dengan penanggung jawab tunggakan  ibu sujiyem melalui telp,karena ibu sujiyem  berada di jakarta,dan ibu sujiyem punya itikad baik dengan mentransfer Rp 800.000, saldo tunggakan masih Rp 2.434.000', 989);
INSERT INTO `bimbingan` VALUES (723, 14, 12, '2018-06-28', 'Pl datang kekelompok ketemu dengan arifin, dan  sumedi.  nitip angsuran Rp 650.000. walau belum  sesuai dengan skema  tapi sudah ada sedikit itikad baik. saldo tunggakan Rp 7.230.000', 989);
INSERT INTO `bimbingan` VALUES (724, 14, 258, '2018-06-29', 'PL datang kekelompok ketemu dengan ibu sarjinem dan sudah ada sedikit itikad baik, ibu sarjinem nitip  angsuran  Rp 1.000.000. saldo tunggakan rp9.790.000', 989);
INSERT INTO `bimbingan` VALUES (725, 14, 211, '2018-06-30', 'PL datang kekelompok ketemu dengan ibu sarmi,sedikit beritikad baik nitip Rp 100.000,walau belum sesuai dengan skema 6x lunas.saat ini saldo masih Rp6.180.000', 989);
INSERT INTO `bimbingan` VALUES (726, 14, 303, '2018-06-30', 'PL datang ketemu dengan bp dwi,h dan sedikit  ada itikad baik  nitip angsuran Rp 100.000,saldo tunggakan masih Rp 3.705.000', 989);
INSERT INTO `bimbingan` VALUES (727, 14, 85, '2018-06-30', 'PL datang ketemu dengan ibu sulasmi untuk mengambil angsuran  bu sulasmi nitip Rp 1.200.000, saldo tunggakan Rp 27.700.000', 989);
INSERT INTO `bimbingan` VALUES (728, 14, 294, '2018-06-30', 'PL datang kekelompok dan ketemu dengan  ibu murtini, dan sudah ada sedikit itikad baik,ibu murtini nitip Rp 100.000. saat ini saldo tunggakan masih  Rp4.200.000', 989);
INSERT INTO `bimbingan` VALUES (729, 14, 302, '2018-06-08', 'PL DATANG KETEMU DENGAN IBU SEPIYATI DAN ADA SEDIKIT ITIKAD BAIK DENGAN NITIP ANGSURAN RP 400.000.saat ini saldo tunggakan Rp  535.000.', 989);
INSERT INTO `bimbingan` VALUES (730, 14, 270, '2018-06-08', 'PL datang kekelompok dan  anggota kelompok sudah ada itikad baik dengan nitip angsuran Rp 400.000. saat ini saldo tunggakan Rp 1.075.000', 989);
INSERT INTO `bimbingan` VALUES (731, 14, 53, '2018-06-07', 'PL datang kekelompok dan  ketemu dengan istri sumaryadi dan katanya nanti mau transfer, karena sumaryadi berada di jogja kerja.  dan sumaryadi  transfer sebesar Rp 250.000, saat ini saldo tunggakan masih Rp 780.000', 989);
INSERT INTO `bimbingan` VALUES (732, 13, 512, '2018-07-04', 'kelompok barokah 2 ini termasuk kelompok yang aktif, lancar tanpa tunggakan.ada 2 anggota kelompok yang sempat berhenti dalam hal kepeminjaman kemudian bergabung kembali ditahun 2018. dan juga ada penambahan 1 anggota baru.', 1098);
