INSERT INTO `bimbingan` VALUES (734, 14, 117, '2018-07-05', 'Pl datang ke kelompok ketemu pengurus  nitip angsuran Rp. 50.000..pl akan melakukan pendekatan kepada kelompok agar angsurannya sesuai dg SPK.', 989);
INSERT INTO `bimbingan` VALUES (735, 4, 4506, '2018-07-10', 'sejak jatuh tempo, terdapat beberapa nama menunggak 3 bulan al : wasrinah, lizul fadho, dan soestri. sementara angsuran anggota misbahus sudur 2 ada yang dimasukkan ke angsuran misbahus sudur 1 oleh ketua kelompok. sehingga pada klp misbahus sudur 2da tunggakan senilai 19 jt. sementara klp misbahus sudur 1 tdk ada tunggakan di sistem. kenyataannya peminjam bismahus sudur 1 banyak yang menunggak al: siti asmanah, wiwik indayani, basiroh, sumiyatun, mustofiatun, saadah, dan ada nama tdk ada dlm SPK dan menunggak al : Nadhifa dan Nursiyatun ', 130);
INSERT INTO `bimbingan` VALUES (736, 4, 4569, '2018-07-10', 'ada tunggakan 7.517.500, beberapa nama al: siti sofiah (2 jt), supri (1 jt), juniartiningsih (3jt). dan ada dua nama kelompok lama sri rohmiyati (330 rb), sri riwayati (500 rb).', 130);
