INSERT INTO `bimbingan` VALUES (743, 14, 55, '2018-07-07', 'Tunggakan Rp 13.000.000, \ndi lakukan bimbingan kelompok dan klarifikasi tunggakan\nRp. 6.400.000 Sufya Eni W\nRp. 6.600.000 Maryanto\nibu Eni Akan angsur di setiap tgl 25.\nuntuk Bp Maryanto karena sudah pergi dari girisuko akan di lakukan pencvarian,menurut info Bp maryanto dagang di Parangtritis, Bp dukuh Sugiyanto bersedia membantu mencari di parangtritis sehabis lomba Dusun.\n', 989);
INSERT INTO `bimbingan` VALUES (744, 11, 5479, '2018-07-11', 'Kelompok ini mempunyai tunggakan sebesar Rp. 10.242.494 sesuai dengan rekening koran riwayat angsuran, tersebar di (3) Tiga orang anggota, dengan rincian sbb : \n1. A.n Deti sebesar Rp. 8.500.000\n2. A.n Aroh Rp. 775.000\n3. A.n Ineu H Rp. 967.495\nDari ketiga org tsb saudari Ineu akan mengembalikan lunas diakhir bulan Juli, A.n Deti akan berusaha terus sampai proses registrasi /Verifikasi Kelompok, A.n Aroh menunggu proses selanjutnya', 2614);
INSERT INTO `bimbingan` VALUES (745, 11, 5593, '2018-07-11', 'Kelompok ini mempunyai tunggakan Rp. 20.000.000 sesuai dengan Rekening Koran tersebar di 4 org anggota, dengan rincian nama org sbb :\n1. Jeje\n2. Ita\n3. Hapidin\n5. Nina', 2614);
INSERT INTO `bimbingan` VALUES (746, 14, 220, '2018-07-11', 'Tunggakan Rp. 7.200.00\nPenanggung jawab ibu Tumijem, akan angsur di tanggal 29-07-2018,kemacetan ada di ibu tumijem.', 989);
INSERT INTO `bimbingan` VALUES (747, 11, 5593, '2018-07-12', 'Berdasarkan hasil pertemuan dengan Ketua kelompok dan dikonfrontir langsung bersama Anggota kelompok (Nasabah) yang mempunyai tunggakan dengan total Rp. 20.000.000,- maka didapatkan data tunggakan dengan Nama : 1. Jeje Fatimah (Rp. 10.000.000), 2. Ita Rosita (Rp. 5.000.000), 3. Nina (Rp. 1.800.000). sedangkan sisanya yang berjumlah Rp. 3.200.000 merupakan tunggakan yang disalurkan oleh kelompok ke Non Anggota yaitu ke A.n Hapidin dikarenakan ada sisa uang yang dikembalikan oleh Peminjam (anggota) yang tidak bersedia menerima uang pencairan sebesar hasil / kesepakatan pada waktu verifikasi.\nAkhirnya, dengan hasil musawarah disepakati bahwa tunggakan a.n Hapidin yang berjumlah Rp. 3.200.000,- semuanya ditanggungjawab oleh Ibu Mamah Suryamah selaku Pengurus Kelompok.\nSelanjutnya untuk mengatasi tunggakan tersebut masing-masing penunggak bersedia untuk memperpanjang masa setoran dengan : a.n Jeje Fatimah akan mengangsur kembali pinjaman selama 10 bulan dengan perhitungan setoran bulanannya sebesar Rp. 1.000.000. a.n Nina akan mengangsur selama 5 bulan dengan setoran sebesar Rp. 360.000 /bulan. a.n Ita Rosita akan mengangsur selama 10 bulan dengan angsurana bulanan sebesar Rp. 525.000.\nWaktu penyetoran disamakan dengan setoran biasa yaitu maksimal tgl. 20 tiap bulannya.', 2616);
INSERT INTO `bimbingan` VALUES (748, 14, 362, '2018-07-13', 'Di lakukan pembinaan kelompok untuk klarifikasi tunggakan dan pinjaman pada masing-masing anggota, di kelompok ini ada salah satu anggota yang pergi ke irian jaya atas nama ibu Woro Windarti, petugas UPK memberikan penjelasan kepada anggota kelompok bahwa tanggungan pinjaman yang harus di selesaikan masing-masing anggota sesuai yang tertera di SPK.\npada waktu itu pembinaan kelompok nitip angsuran Rp. 1.161.000, akan nitip angsuran lagi di tgl 25 bulan ini', 989);
INSERT INTO `bimbingan` VALUES (749, 14, 52, '2018-07-24', 'Tunggakan Rp 2.310.000. Pl datang ke kelompok ketemu dengan pengurus Bp suwarno nitip angsuran Rp. 200.000, saldo tunggakan sampai hari ini tgl 24 juli 2018 Rp. 2.110.000', 989);
INSERT INTO `bimbingan` VALUES (750, 14, 269, '2018-07-25', 'Tunggakan Rp. 2.850.000\nPL datang ke kelompok ketemu dengan ibu Sikemiyati, nitip angsuran Rp. 100.000, saldo tunggakan sampai hari ini Rp. 2.750.000 PL akan kembali lagi ke kelompok tgl 25/8/2018.', 989);
