INSERT INTO `bimbingan` VALUES (759, 14, 208, '2018-07-28', 'Tunggakan Rp. 2.525.000\nPl datang ke kelompok ketemu pengurus kelompok ibu Sutiyem dan nitip angsuran Rp. 100.000, saldo tunggakan sampai tgl 28-07-2018 Rp. 2.425.000, Pl kembali ke kelompok bulan depan di tanggal yang sama.', 989);
