INSERT INTO `bimbingan` VALUES (761, 14, 53, '2018-07-13', 'Tunggakan Rp.780.000\npl datang ke kelompok ketemu dengan pengurus, nitip angsuran Rp. 300.000, saldo tunggakan sampai tgl 13-07-2018 Rp. 480.000,bulan depan kembali ke kelompok dengan tanggal yang sama', 989);
INSERT INTO `bimbingan` VALUES (762, 14, 23, '2018-07-16', 'Tunggakan Rp. 2.160.000\npl datang ke kelompok,pengurus kelompok nitip angsuran Rp. 50.000, saldo tunggakan sampai hari ini tgl 16-07-2018 Rp. 2.110.000', 989);
INSERT INTO `bimbingan` VALUES (763, 14, 274, '2018-07-28', 'Tunggakan Rp. 6.808.300\nPl datang ke kelompok, ketemu dengan pengurus dan menitipkan angsuran Rp. 400.000, saldo tunggakan sampai tgl 28-07-2018 Rp. 6.408.300,pl agendakan setiap seminggu sekali datangi kelompok', 989);
