INSERT INTO `bimbingan` VALUES (765, 14, 302, '2018-07-28', 'tunggakan Rp. 535000\npl datang ke kelompok ketemu dengan pengurus,dan angsur di tgl 16-07-2018 Rp. 50.000 dan di tgl 28-07-2018 Rp. 50.000 total angsuran yg di titipkan Rp. 100.000. saldo tunggakan sampai tgl 28-07-2018 Rp. 435.000, Pl berinisiatif datangi seminggu sekali', 989);
