INSERT INTO `bimbingan` VALUES (770, 14, 335, '2018-08-10', 'Tunggakan Rp. 5.770.000\nPl datang ketemu dengan pengurus kelompok, nitip angsuran Rp. 150.000, saldo tunggakan Rp. 5.620.000. PL kembali ke kelompok di tanggal 10-09-2018.', 989);
INSERT INTO `bimbingan` VALUES (771, 10, 3575, '2018-08-13', 'Pada Tanggal 13 Agustus 2018 ada tunggakan di anggota atas nama peminjam Agus dan Santo', 597);
INSERT INTO `bimbingan` VALUES (772, 14, 209, '2018-08-03', 'Tunggakan Rp 3.190.000 Pl datang ke kelompok dan bertemu dengan bu Mariah.Yang bersangkutan telah menyetujui skema 6 bulan yang telah disepakati walaupun setiap bulan tidak full dalam pembayaran  akan tetapi sanggup melunasi di tgl 23-11-2018,dengan jaminan tunjuk 3 ekor kambing jika yang bersangkutan mengingkari janji.Dan yang bersangkutan nitip angsuran sebesar Rp 150.000.-Total tunggakan sampai dengan saat ini Rp 3.040.000.-', 989);
INSERT INTO `bimbingan` VALUES (773, 14, 98, '2018-08-03', 'Tunggakan Rp 489.500 dan ketemu bp tugiran dan nitip Rp 150.000. saldo per 03-08-2018 Rp 339.500. PL kembali tgl 16-08-2018', 989);
