INSERT INTO `bimbingan` VALUES (815, 11, 5600, '2018-08-30', 'Hasil dari beberapa kunjungan dapat disimpulkan bahwa tunggakan kel. Cendana ini sampai bulan Juli 2018  tersebar di 2 (dua) orang yaitu a.n Ibu Rohmayati (Alm) sebesar Rp. 5.615.000,- || Namun untuk tunggakkan Sdri. Rohmayati ini Ketua Kelompok sudah menyanggupi untuk melunasinya karena ada pertalian hutang antara Ketua Kelompok dan Almh. sedangkan satu lagi ada di saudara Maman (Maman ini adalah non-anggota terdaftar yang menempel pada pinjaman saudari Lia) Pinjaman saudari Lia adalah 8jt namun dibagi dengan saudara Maman sehingga pinjaman Saudari Lia hanya sebesar Rp. 5.000.000,-  dan saudara Maman Rp. 3.000.000,-. Setoran saudari Lia menurut pengakuan Ketua kelompok sampai saat ini Lancar sedangkan pinjaman saudara Maman tidak lancar hingga saudara Maman mempunyai tunggakkan sebesar Rp. 850.000,-.\n', 2616);
INSERT INTO `bimbingan` VALUES (816, 11, 5479, '2018-08-30', 'Pada kunjungan hari ini, ada titik terang dari Ketua kelompok tentang tunggakkannya yg berjumlah Rp. 9.225.000,- bahwasannya ketua Kelompok Bersedia melunasi Hutang secara KESELURUHAN kepada UPK yaitu pada Tgl. 10 September 2018 sesuai dengan yang tertera pada -Surat Perjanjian Pelunasan Hutang- yang sudah diikrarkan dan ditandatangani oleh Ketua Kelompok dan Pihak UPK dalam hal ini yang mewakili UPK adalah Kabag. Keu.', 2616);
INSERT INTO `bimbingan` VALUES (817, 11, 5596, '2018-08-30', 'Kel. Mutiara 1 ini menerima dana pinjaman dari UPK sebesar Rp. 113.000.000,-. Namun setelah ditelusuri ketika terjadi Kemacetan maka didapatkan bahwa Realisasi Penerimaan Pinjaman tidak sesuai dengan Rekomendasi dan Realisasi dari UPK, ada beberapa Anggota yang menerima Pinjaman dari Kel. Melebihi hasil rekomendasi dan ada juga yang kurang.\nPinjaman a.n Aan Hasanah yang seharusnya 10jt malah dibagi dengan Sdr. Holis, hingga Holis ini menerima sebesar Rp. 6jt yang notabene Sdr. Holis ini adalah Non-anggota terdaftar.\nPinjaman sdri. Tiktik yang seharusnya 8jt nyatanya hanya menerima Rp. 6jt karena sisanya yg 2jt diberikan ke Nasabah lain yaitu Sdri. Eti sebesar Rp. 2jt.\nPinjaman sdri. Patonah yang berjumlah Rp. 8jt semuanya diberikan / disalurkan kepada Sdr. Eti.\nSdri. Ilah-pun sama kasusnya dengan yg lain yaitu tidak menerima utuh karena hanya menerima Rp. 5jt yang seharusnya 7jt, yg 2jt lagi dibagi / disalurkan kpd. Sdri. Eti.\nLalu sdri. Eti yang seharusnya menerima Pinjaman sebesar Rp. 8jt menjadi 22jt dengan rincian @dari Tiktik 2jt, @dari Patonah 8jt dan @dari Ilah 2jt sedangkan pinjaman Eti sesungguhnya adalah Rp. 8jt.\n========>>>>>', 2616);
INSERT INTO `bimbingan` VALUES (818, 11, 5610, '2018-08-30', 'Kel. Sabilulungan tidak hanya merealisasikan pinjaman kepada anggota kel. yang terdaftar namun direalisasikan jg kepada orang yg tidak terdaftar (non anggota).\nNama-nama penerima yang bukan anggota ialah : 1. Miftahudin Rp. 2jt, ||2. Yanti Rp. 2,5jt ||3. Hendra Rp1jt ||4. Imas Rp. 1,5jt ||5. Eva Rp. 1jt dan||6. Ajat Rp. 500rb.\nada beberapa pinjaman yang diterima Nasabah terdaftar sesuai dan tidak sesuai dengan reslisasi dari UPK yaitu diantaranya :\n1. Ruhiat dari (UPK = 8JT) dan dari (Kel = 8jt) -SESUAI-\n2. Rohimah / Mamah dari (UPK = 8JT) dan dari (Kel = 8jt) -SESUAI-\n3. Yulianti dari (UPK = 10JT) dan dari (Kel = 10jt) -SESUAI-\n4. Dedeh dari (UPK = 10JT) dan dari (Kel = 9jt)\n5. Asep Dedi dari (UPK = 10JT) dan dari (Kel = 9jt)\n6. Sobri dari (UPK = 10JT) dan dari (Kel = 7jt)', 2616);
INSERT INTO `bimbingan` VALUES (819, 14, 310, '2018-08-30', 'Saldo tunggakan Per Anggota :\n1. Sarinah      : 5.210.000\n2. Wakinem   : 3.380.000\n3. Rubiyanti   : 2.800.000\n4. Jumiyati     :     915.000\n', 989);
INSERT INTO `bimbingan` VALUES (820, 14, 362, '2018-08-27', 'PL datang ke kelompok dan nitip angsuran Rp 1.561.000. janjian lagi dengan PL tgl 27-09-2018,saldo tunggakan masih berjalan.', 989);
