INSERT INTO `bimbingan` VALUES (822, 23, 1378, '2018-08-31', 'Per Agustus 2018 Ambarwati mengangsur 300ribu namun tidak disetor ke bank karena dikembalikan sebagai tabungan anggota.. Tunggakan awal 2.990.000 sekarang menjadi 2.690.000', 1763);
INSERT INTO `bimbingan` VALUES (823, 11, 5600, '2018-08-31', 'Bulan Agustus Kel. Cendana setor Rp. 7.220.000 sehingga kumulatif tunggakan kel. ini total 18.895.000.\nBerdasar pengakuan ketua kel. bahwa uang setoran bulan Agustus 2018 sebagian terpakai yaitu sebesar Rp. 9.200.000 (untuk setoran yang terpakai ini yg 9,2jt akan dibayar pada hari Senin, 03 September 2018).\nsetelah dibayarpun kelompok tetep mempunyai tunggakan yang tersebar di a.n Rohmayati (Alm.) sebesar Rp. 6.665.000, Maman Rp. 850.000 dan Ada uang yang terpakai oleh Ketua Kel. sebesar Rp. 2.180.000 sehingga Total tunggakan sebesar Rp. 9.695.000 dengan Asumsi setoran yang terpakai dibulan agustus yg berjumlah 9.200.000 lunas dibayar.', 2616);
INSERT INTO `bimbingan` VALUES (824, 11, 5482, '2018-08-31', 'Setelah berbicara langsung dengan nasabah yang menunggak Sdr. Boid menurut pengakuannya memang betul mempunyai tunggakan sebesar 194.996 dan tidak bisa membayar itu karena \"pabaliut\" dengan keperluan lain dan akan diusahakan.\nditekankan bahwa bulan september harus masuk supaya ada progres.\nnamun ketua kelompok berinisiatif untuk bermusyawarah dgn pengurus yg lain untuk mengusahakan uang supaya ada, dan ada atau tidak uang ketua kelompok hari Senin, 3 September 2018 akan datang ke UPK.', 2616);
