INSERT INTO `bimbingan` VALUES (841, 11, 5600, '2018-09-06', 'Kelompok ini mempunyai tunggakan sebesar Rp. 13.345.000. sesuai dengan rekening koran, tersebar di empat(4) orang pemanfaat dengan rincian sbb : 1. Romyati (alm) Rp.5.615.000. 2. Maman Rp. 850.000, 3. Aan 2.600.000, Isroh Rp. 5.130.000. Berdasarkan hasil konfirmasi dengan pengurus kelompok siap untuk mengembalikan sekaligus dengan waktu belum ditentukan.', 2614);
