INSERT INTO `bimbingan` VALUES (845, 18, 443, '2018-07-18', '18 juli 2018 pak Ajib s angsur Rp. 1.000.000 jadi total tunggakan ajib Rp. 5.787.000 sobirin Rp. 3.702.000 total tunggakan klpk Rp. 9.489.000', 1220);
