INSERT INTO `bimbingan` VALUES (859, 22, 573, '2018-09-13', 'Ada pembayaran 4 orang 1. Ngarpi (Rp. 100.000), 2. Sukarti (Rp. 100.000), 3. Maspiatun  (Rp. 100.000), 4. Koridah (Rp. 100.000)', 1492);
INSERT INTO `bimbingan` VALUES (860, 28, 126, '2018-09-19', 'Kunjungan Ke Muryani\nSaat ini belum bisa memenuhi kesanggupan pada saat monitoring yaitu tgl 25 Agustus untuk membayar kekurangan. Kesanggupan nanti pada saat jatuh tempo akan berusaha melunasi.', 2356);
