INSERT INTO `bimbingan` VALUES (868, 11, 5484, '2018-09-25', 'Kel. ini sampai dengan bulan Agustus mempunyai tunggakkan sebesar Rp. 4.250.000 dengan rincian tunggakan perbulan sebesar #Juni Rp. 1.500.000,- #Juli Rp. 1.375.000,- #Agustus Rp. 1.375.000.\nMenurut pengakuan Pengurus dalam hal ini ketua Kelompok tunggakan tersebut tersebar di-2 orang Nasabah yaitu a.n Sariah dan a.n Memey (Ibu', 2616);
