INSERT INTO `bimbingan` VALUES (2294, 18, 3185, '2021-02-23', 'Angsuran masuk sejumlah Rp. 375.000,00 adalah menggunakan tabungan wajib', 1209);
INSERT INTO `bimbingan` VALUES (872, 22, 611, '2018-09-24', 'Tunggakan diakibatkan karena adanya pengelolaan yang salah oleh pengurus kelompok, Beberapa anggota pinjamannya tidak sesuai dengan pengajuan  ', 1492);
INSERT INTO `bimbingan` VALUES (873, 22, 611, '2018-09-25', 'Sudah diklarifikasi ke anggota ternyata anggota sudah bayar semua', 1492);
INSERT INTO `bimbingan` VALUES (874, 22, 620, '2018-09-24', 'Sudah diklarifikasi ke kelompok, yang mengurusi adalah sdri. Khusnul Khotinah\n', 1492);
INSERT INTO `bimbingan` VALUES (875, 28, 142, '2018-09-25', 'Tim mendatangi rumah penunggak. Sdri Sumarsih namun tidak bisa ketemu yang bersangkutan, dan hanya ketemu ibunya.  Tim titip pesankepada ibunya agar sdri Sumarsih segera melunasi tunggakan yang ada di UPK sebesar Rp. 4.285.000,-', 2354);
INSERT INTO `bimbingan` VALUES (876, 11, 5651, '2018-09-27', '1. Tunggakan Padi sampai Bulan September adalah sebesar Rp. 4.180.002 yang mana seluruhnya digunakan oleh ketua kelompok.', 2742);
INSERT INTO `bimbingan` VALUES (877, 19, 114, '2018-09-27', '27/8 pinjam tanggung renteng 368.000\n27/9 dikembalikan tanggung renteng 96.000', 2379);
