INSERT INTO `bimbingan` VALUES (880, 14, 70, '2018-09-29', 'Tunggakan Rp. 8.950.000\nPenanggung jawab Ibu Parjinem, Pengurus kelompok nitip angsuran Rp. 100.000.\nsaldo tunggakan Rp. 8.850.000', 989);
INSERT INTO `bimbingan` VALUES (881, 14, 220, '2018-09-29', 'Tunggakan Rp. 6.200.000\nPL datang ke kelompok ketemu pengurus kelompok Ibu Tumijem nitip angsuran Rp. 300.000, saldo tunggakan sampai tgl 29-09-2018 Rp. 5.900.000', 989);
INSERT INTO `bimbingan` VALUES (882, 27, 92, '2018-10-01', 'Buku kas masih perlu dicek,krn register pinjaman kelompok selisih lagi 960.000 dgn buku kas,tolong setiap tutup buku akhir bulan saldonya ditulis,Register Yg Lain tolong lanjutkan', 2265);
INSERT INTO `bimbingan` VALUES (883, 23, 1378, '2018-10-02', '27 September angsuran 100.000 sehingga sisa tunggkan menjadi 2.290.000', 1763);
INSERT INTO `bimbingan` VALUES (884, 11, 5602, '2018-10-02', 'Setelah dikonfirmasi tunggakkan kel. Mutiara 2 yang berjumlah Rp. 1.988.500 s.d bulan September 2018 menurut pengakuan dari Ketua Kelompok itu tersebar di-2 nama yaitu a.n Elis (Ketua Kelompok Mutiara sendiri) sebesar Rp. 1.564.500 dan di a.n Idah Rp. 424.000.', 2616);
INSERT INTO `bimbingan` VALUES (885, 11, 1529, '2018-10-03', 'tunggakan 8625000 atas penyelewengan anggota atas nama ria \npenyelesaian akan dilakukan mediasi dengan membuat surat pernyataan kesanggupan membyar 1,5 bulan maksimal', 2314);
INSERT INTO `bimbingan` VALUES (886, 27, 4, '2018-10-05', 'Buku kas masih perbaikan,karena saldo bln ini -(mines),buatkan buku pinjaman kas berupa register dikelompok dgn buku tulis biasa,pastikan pinjaman dikelompok supaya ada pembayaran minimal bunga setiap bulan ', 2265);
INSERT INTO `bimbingan` VALUES (887, 27, 60, '2018-10-05', 'Buku kas masih perlu perbaikan karena salah jumlah dikolom sampai bulan ini,register pinjaman kas tolong ditulis pinjaman pd tgl pinjaman(misalnya dipinjam bulan september bulan oktober sdh bayar ) bukan dibulan oktober baru dimasukkan diregister.', 2265);
INSERT INTO `bimbingan` VALUES (888, 27, 109, '2018-10-05', 'Buku kas sdh belen dgn register simpanan dan register pinjaman,register pinjaman tidak cocok dgn kartu pinjaman,diregister lebih lagi 6000pembayaran kelompok.', 2265);
INSERT INTO `bimbingan` VALUES (889, 27, 93, '2018-10-05', 'Buku kas sdh belen dgn register yg lain,tlg kas kelompok digulirkan,supaya modal berkembang,karena selanjutnya kelompok sdh lunas dan ngamprah baru,pastikan ada aturan dan sangsi kelompok', 2265);
INSERT INTO `bimbingan` VALUES (890, 27, 23, '2018-10-05', 'Buku kas sdh belen,pastikan pinjaman dikelompok ada pembayaran setiap bulan, administrasi yg lain lanjutkan', 2265);
INSERT INTO `bimbingan` VALUES (891, 27, 6, '2018-10-05', 'Buku kas tolong dibuat berlanjut,karena pinjaman awal sdh lunas dan lanjut pinjaman baru,saldo simpanan wajib tolong lanjutkan,kas yg digulirkan juga lanjutkan ', 2265);
INSERT INTO `bimbingan` VALUES (892, 27, 70, '2018-10-05', 'Buku kas masih perbaikan,tolong bawa buku register pinjaman kas dikelompok tolong dibawa setiap bimbingan ,pastikan pinjaman dikelompok ada pembayaran setiap bulan.', 2265);
INSERT INTO `bimbingan` VALUES (893, 27, 70, '2018-10-05', 'Buku kas masih perbaikan,tolong bawa buku register pinjaman kas dikelompok tolong dibawa setiap bimbingan ,pastikan pinjaman dikelompok ada pembayaran setiap bulan.', 2265);
INSERT INTO `bimbingan` VALUES (894, 14, 310, '2018-10-05', 'Tunggakan Rp. 12.205.000\nsarinah nitip angsuran Rp. 200.000, Jumiyati nitip Rp. 50.000, angsuran kelompok masuk Rp.250.000, Pl kembali ke kelompok tgl 15.10.2018. saldo tunggakan sampai hari ini Rp. 11.955.000. \nSarinah. Rp. 5.010.000, Jumiyati Rp. 865.000, Wakinem Rp. 3.280.000. Rubiyanti Rp. 2.800.000', 989);
