INSERT INTO `bimbingan` VALUES (914, 27, 87, '2018-10-08', 'Menurut buku kas perbulan September 2018 total uang kelompok 19.360.000 dengan rincian sbb: di pinjam anggota 9.650.000,Tabungan 4.056.000,tunai 884.000,pengeluaran lainnya 2 540.000 setelah ditotal selisih lagi 2.230.000,tolong cek kembali.\n\nKarena klompk sdh lunas, tlg diarahkan anggota untuk ngamprah baru (adakan rapat klompok.', 2265);
INSERT INTO `bimbingan` VALUES (915, 19, 196, '2018-10-08', '08/10/18 -- TR 270.000', 2379);
INSERT INTO `bimbingan` VALUES (916, 13, 798, '2018-10-01', 'kunjungan kepada kelompok mandiri bertemu dengan anggota atasnama ghufron sudah terselesaikan kewajiban tunggakannya\natasnama p abdul malik bulan kemarin sudah ada progres 500.000 untuk bulan ini belum bisa bertame dg bapak malik tetapi istri beliau samnggup mengangsur lagi tgl 10 oktober 2018\natasnama pak rifai masih belum bisa ditemui .pihak keluarga akan menghubungi apabila pak rifai sudah pulang', 2786);
INSERT INTO `bimbingan` VALUES (917, 13, 800, '2018-10-02', 'berkoordinasi anggota 2 kelompok \np.selamet tunggakannya akan diangsur bulan ini sebagian dan kekurangannya dilunasi minggu depan\npkusen tunggakanyang semula 4.710.000 setelah diadakan pendekatan beliau membayar 2.000.000 dan pada ahir bulan oktober akan di bayarkan kekurangan tunggakan tersebut', 2786);
INSERT INTO `bimbingan` VALUES (918, 13, 792, '2018-10-08', 'berkoordinasi dengan pak kusno selaku ketua kelompok . untuk sementara belum bisa ditemui karena masih bekerja disurabaya karena sudah janji ada progres tgl 8 ada progres masuk 200.000', 2786);
INSERT INTO `bimbingan` VALUES (921, 13, 771, '2018-10-02', 'berkordinasi dengan burohmah mengenai tungakan2 kelompok menurut pengakuannya bahwa tunggakan ada di anggota dan sebagian ada di kepala desa setelah di kita konfirmasi kepada anggota , maka sebagian anggota sanggup memberikan progres pada pertengahan bulan oktober', 2786);
INSERT INTO `bimbingan` VALUES (920, 13, 794, '2018-10-04', 'kunjungan nkepada pak mudin uman dan berkordinasi terkait tunggakan ,,sementara ada progres untuk bulan ini 1.000.000 dan pada saat bopcair kurang lebih ahir bulan ada tambahan progres masuk lagi\n', 2786);
INSERT INTO `bimbingan` VALUES (922, 13, 799, '2018-10-02', 'kunjungan terhadap pak harianto terkait tunggakan kelompok sanggup memberikan progres tgl 9 oktober nunggu panen ayam selesai', 2786);
INSERT INTO `bimbingan` VALUES (923, 13, 799, '2018-10-09', 'kunjungan terhadap pak harianto terkait tunggakan kelompok yang sedianya  sanggup memberikan progres tgl 9 oktober untuk progres ada angsuran masuk sebesar Rp.300.000 ', 2786);
INSERT INTO `bimbingan` VALUES (924, 13, 792, '2018-10-07', 'kunjungan terhadap ketua kelompok maju bersama ,untuk progres akan di bayarkan tgl 7 oktober 2018 menunggu gajian ', 2786);
INSERT INTO `bimbingan` VALUES (925, 13, 792, '2018-10-03', 'kunjungan terhadap ketua kelompok maju bersama ,untuk progres akan di bayarkan tgl 7 oktober 2018 menunggu gajian ', 2786);
INSERT INTO `bimbingan` VALUES (926, 13, 773, '2018-10-10', 'menemui ketua kelompok sedap malam dan berkoordinasi terkait tunggakan kelompok, menurut pengakuan beliau tungggakan kelompok ada pada bendahara , pihak upk sudah melayangkan surat tagihan terhadap yang bersangkutan ', 2786);
INSERT INTO `bimbingan` VALUES (927, 13, 773, '2018-10-03', 'menemui ketua kelompok sedap malam dan berkoordinasi terkait tunggakan kelompok, menurut pengakuan beliau tungggakan kelompok ada pada bendahara , pihak upk sudah melayangkan surat tagihan terhadap yang bersangkutan ', 2786);
INSERT INTO `bimbingan` VALUES (928, 13, 774, '2018-10-03', 'kunjungan dan bimbingan terhadap kelompok berkah terkait tunggakan baru yang sebelumnya tidak pernah menunggak ,pihak ketua sanggup menyelesaikan tunggakan pada pertengahan bulan oktober dan saat ini ada progres Rp.2.042.000', 2786);
INSERT INTO `bimbingan` VALUES (929, 13, 530, '2018-10-03', 'kunjungan kerumah bu lilik selaku ketua kelompok mahadewi,untuk sementara beliau belum bisa ditemui menurut informasi dari keluarga beliau pindah ke perumahan bph  blok L untuk nomornya masih belum tahu', 2786);
INSERT INTO `bimbingan` VALUES (930, 13, 788, '2018-10-04', 'koordinasi dengan pak rubai masih belum bisa membayarkan tunggakan menunggu dana desa cair', 2786);
INSERT INTO `bimbingan` VALUES (931, 13, 793, '2018-10-04', 'koordinasi dengan pak sugiato selaku ketua kelompok ,menurut informasi dari ketua kelompok beberapa anggota sedang mengalami pailit termasuk pak sugianto sendiri ,setelah dilakukan pendekatan maka besok tanggal 5 akan ada progres', 2786);
INSERT INTO `bimbingan` VALUES (932, 13, 793, '2018-10-05', 'koordinasi dengan pak sugiato selaku ketua kelompok ,untuk progres saat ini ada masuk Rp. 500.000', 2786);
INSERT INTO `bimbingan` VALUES (933, 13, 582, '2018-10-05', 'koordinasi dengan bu santi progres akan di realisasikan hari sabtu besok', 2786);
INSERT INTO `bimbingan` VALUES (934, 13, 582, '2018-10-08', 'koordinasi dengan bu santi progres akan di realisasikan hari nanti siang menunggu anggota2 yanglain yang belum membayar', 2786);
INSERT INTO `bimbingan` VALUES (935, 27, 889, '2018-10-10', 'Administrasi masih perlu bimbingan,karena kelompok baru,tolong bimbingan berturut2 minimal 3x sesuai arahan UPK', 2265);
INSERT INTO `bimbingan` VALUES (936, 27, 6, '2018-10-10', 'Buku Kas tolong dilanjutkan,register pinjaman dibuat baru,karena pinjaman yg baru sdh lunas,Simpanan wajib lanjutkan dari saldo yg dulu ditambah simpanan yg baru.', 2265);
INSERT INTO `bimbingan` VALUES (937, 25, 0, '2018-10-11', 'setelah bertemu dengan suami dari yang nunggak. disepakati ada pemasukan 200.000 tiap tanggal 25 dan akan di selesaikan selama 21 Bulan', 2417);
INSERT INTO `bimbingan` VALUES (938, 13, 617, '2018-10-09', 'kunjungan ke balai desa menemui bu nur iffa untuk konfirmasi tunggakan beliau , tunggakan akan di bayarkan paling lambat ahir bulan menunggu dana add dan akan dititipkan kepada saudari dwi', 2786);
