INSERT INTO `bimbingan` VALUES (940, 13, 810, '2018-10-09', 'pencairan dana bergulir untuk kelompok kurma sebesar Rp.36.000.000 dengan jumlah pemanfaat 12 orang', 2786);
INSERT INTO `bimbingan` VALUES (941, 13, 605, '2018-10-10', 'kunjungan kepada kelompok matahari menemui bu rawi terkait tunggakan oleh salah satu anggota kelompok ,untuk sementara anggota yang bersangkutan belum bisa diremui , akan dipastikan besok atau dalam satu minggu ini ada progres angsuran tunggakan masuk', 2786);
INSERT INTO `bimbingan` VALUES (942, 13, 605, '2018-10-11', 'kunjungan kepada kelompok matahari menemui bu rawi terkait tunggakan oleh salah satu anggota kelompok ,untuk sementara anggota yang bersangkutan masih juga belum bisa ditemui , akan dipastikan besok minta di temui lagi oleh petugas upk saran dari ketua kelompok ,mengingan anggota kelompok tersebut perlu pendampingan intensif', 2786);
INSERT INTO `bimbingan` VALUES (943, 13, 798, '2018-10-10', 'menemui anggota kelompok atasnas pak abdul malik ,untuk saat ini ada progres masuk sebesar Rp.500.000 dan sisanya tinggal Rp.500.000 di selesaikan dibulan depan', 2786);
INSERT INTO `bimbingan` VALUES (944, 13, 616, '2018-10-11', 'kunjungan terhadap kelompok mangga terkait angsuran yan menunggak dan sudah diingatkan berulang kali tetapi progresnya masih belum bisa maksimal ,kesanggupan ketua kelompok akan segera menarik angsuran kepada setiap anggota u.untuk progres akan dibayarkan pada minggu depan paling lambat tanggal 20', 2786);
INSERT INTO `bimbingan` VALUES (945, 13, 594, '2018-10-11', 'koordinasi began ketua kelompok dan pengurus mengenai tunggakan kelompok sebenarnya ada pada anggota yang semuanya termasuk kategori perangkat sehingga untuk angsurannya mengikuti dana add cair untuk progres akan di bayarkan hari senin tanggal 22', 2786);
INSERT INTO `bimbingan` VALUES (946, 25, 347, '2018-10-12', 'dalam penagihan terakhir di dapati klo ybs tidak ada niatan buat membayar. UPK sudah koordinasi dengan Pemerintah desa, karena YBS merupakan istri dari perangkat desa, YBS janji tanggal 1 akan ada angsuran masuk,', 2417);
INSERT INTO `bimbingan` VALUES (947, 25, 0, '2018-10-12', 'setelah ditagih janji membayar akhir bulan Oktober ini', 2418);
INSERT INTO `bimbingan` VALUES (948, 25, 448, '2018-10-12', 'setelah di lakukan pendekatan secara personal ke suami penunggak, sanggup membayar tiap tanggal 25 sebesar 200.000', 2417);
INSERT INTO `bimbingan` VALUES (949, 1, 71, '2018-10-12', 'Kelompok ini layak \ndengan ......', 241);
INSERT INTO `bimbingan` VALUES (950, 13, 525, '2018-10-12', 'koordinasi dengan ketua kelompok terkai tunggakan ,untuk progres akan diselesaikan di bulan depan ,mengingatkan juga bahwa tunggaka itu termasuk angsuran terahir untuk jasa juga belum terbayarkan \nselanjutnya menemui anggota kelompok atas nama bu nunuk saat ini masih belum ada progres ,secepatnya dalam minggu ini ada progres masuk ', 2786);
INSERT INTO `bimbingan` VALUES (951, 13, 776, '2018-10-12', 'kunjungan keketua kelompok kebetulan yang bersangkutan adalah perangkat desa sehingga harus menemui di balai desa sekalian memberikan insentif kepada kepala desa\nketerangan dari bu atik selaku ketua kelompok anggota yang menunggak atas nama b.khoiriyah untuk minggu depan akan ada progres angsuran tunggakan ,sedangkan pak jai sampai saat ini belum ada kabar karena yg bersangkutan berada di surabaya', 2786);
INSERT INTO `bimbingan` VALUES (952, 13, 605, '2018-10-12', 'kembali mengunjungi pak junaidi selaku penanggunjawab tunggakan ,,saat ini ada warga dusun yang meninggal dunia dan beliau ikut takziah sehingga tidak bisa ditemui ', 2786);
INSERT INTO `bimbingan` VALUES (953, 13, 774, '2018-10-03', 'sekaligus menanyakan dan mencari keterangan tentang dana tanggung renteng ,menurut keterangn beliau dana tanggung renteng sudah dimasukkan kedalam rekening kelompok', 2786);
INSERT INTO `bimbingan` VALUES (954, 13, 605, '2018-09-10', 'koordinasi dengan pak junaidi salah satu suami dari anggota yang menunggak beliau sanggup mengangsur sampai selesai progres saat ini Rp.200.000', 2786);
INSERT INTO `bimbingan` VALUES (955, 13, 582, '2018-09-08', 'kunjungan terhadap ketua kelompok terkait tunggakan ,untuk saat ini ada angsuran masuo Rp.500.000 selanjutnya hari senin dalam minggu selanjutnya ada tambahan 2.000.000', 2786);
INSERT INTO `bimbingan` VALUES (956, 13, 582, '2018-09-07', 'kunjungan terhadap ketua kelompok rossella ,pihak ketua sanggup mengangsur tunggakan besok tanggal 8', 2786);
INSERT INTO `bimbingan` VALUES (957, 0, 0, '2018-09-06', 'koordinasi dengan kelompok munggusejah tera (ketua kelompok ) pak carik siap melunasi tunggakan ahir bulan atau paling lambat awal bulan oktober nunggu add cair', 0);
INSERT INTO `bimbingan` VALUES (958, 0, 0, '2018-09-06', 'koordinasi dengan ketua dan pengurus kelompok tunas muda ,untuk angsuran bulan ini belum bisa terealisasi , kesanggupan dari kelompok untuk tunggakan akan dibayarkan awal bulan oktober pada saat add atau tunjangan perangkat desa sudah tercairkan', 0);
INSERT INTO `bimbingan` VALUES (959, 0, 0, '2018-09-05', 'koordinasi dan kunjungan lapangan kepada kelompok mangga terkait tunggakan anggota memang belum ada yang mengangsur ,kesanggupan ada realisasi tanggal 10 september 2018', 0);
INSERT INTO `bimbingan` VALUES (960, 0, 0, '2018-09-05', 'koordinasi dengan ketua kelompok , angsuran tunggakan akan dititipkan kepada mbak dwi pada tanggal 17 menunggu gajian', 0);
INSERT INTO `bimbingan` VALUES (961, 22, 1597, '2018-10-15', 'Hasil bimbingan kelompok terkait tunggakan diklarifikasi sebagai berikut :\n1. KTP pasangan suami/istri banyak yang tidak benar (bukan pasangannya)\n2. Pencairan ke anggota tidak sesuai pengajuan, setelah pencairan ke kelompok uang \n    ditarik kembali oleh SM (oknum koordinator kelompok), dan sebagian anggota \n    dicairkan atau bahkan hanya dipakau namanya.\n3. Sebagian angsuran dari anggota dipakai SM (oknum koordinator kelompok)\n4. Pengurus kelompok hanya dicairkan 6 orang dan tidak sesuai juga dengan \n    pengajuan.\n5. Akan dilunasi menunggu pencairan dari tempat laian', 1492);
INSERT INTO `bimbingan` VALUES (962, 13, 799, '2018-10-15', 'kunjungan terhadap kelompok dan menemui beberapa anggota yang menunggak \natasnama pak kusen progres masuk Rp.2000.000 ,- sisanya yang Rp.710.000,- di bayarkan besok atau lusa\nyang atas nama pak selamet progres masuk bulan ini Rp.800.000,- sisanya di angsur lagi bulan depan', 2786);
