INSERT INTO `bimbingan` VALUES (1012, 13, 565, '2018-10-24', 'SURAT PETNYATAAN BU KIKI MELANI\nmenyatakan bahwa tunggakan sebesar Rp.16.000.000 masih belum terbayar dan sanggup mengangsur setiap bulan Rp. 500.000 kemudian dengan bantuan tim akan membicarakan secara baik2 kepada keluarga sampaibatas waktu yang ditentukan yaitu Desember tanggal 20 tahun 2018', 2786);
INSERT INTO `bimbingan` VALUES (1013, 13, 793, '2018-10-24', 'SURAT PERNYATAAN BPK SUGIANTO : \nBahwa saya selaku ketua kelompok bertanggungjawab atas apa yang saya lakukan ,saya bersedia mengembalikan pinjaman yang ada pada saya dan setiap bulannya saya akan mengangsur sampai saya menerima uang sepen dari desa saya th.2019 disekitar bulan 8 .\ndan saya bersedia mengembalikan atau melunasi tunggakan tersebut pada th 2019 bulan 8 ,dan tiap bulannya saya angsur 1.000.000 sampai mendapat sepen', 2786);
INSERT INTO `bimbingan` VALUES (1014, 13, 530, '2018-10-24', 'SURAT PERNYATAAN BU LILIK MAHMUDAH :\nTunggakan sebesar Rp. 34.675.000 . akan saya bayar pada bulan desember sekitar ahir bulan tanggal 26-29 desember 2019', 2786);
INSERT INTO `bimbingan` VALUES (1015, 13, 624, '2018-10-24', 'SURAT PERNYATAAN BPK.KASNAWI(SUAMI BU SUNARSIH):\nMempunyai tunggakan sebesar 2.484.000 dan saya sanggup melunasi pada januari 2019 tanggal 16 ,dan saya mengangsur setiap tanggal 20 npovember 2018', 2786);
