INSERT INTO `bimbingan` VALUES (1061, 27, 30, '2018-10-31', 'Buku Kas masih perlu perbaikan karena IPTW yg sudah diterima 2x (1.200.000) ditulis 1x dengan jumlah 960.000.Register simpanan dan register pinjaman tolong dilanjutkan,Register Pinjaman Kas Tolong Dicocokan dengan buku kas,supaya kas yg dimiliki cocok.', 2265);
