INSERT INTO `bimbingan` VALUES (1074, 14, 128, '2018-11-03', 'saldo tunggakan Rp 5.628.000 itu berada di bp suharno,ketua kelompok bp yanto wiharjo  dulunya adalah ketua RT dan bersama anggota lain hanya di jadikan atas nama. dan bp suharno pergi ke riau sudah tidak pernah kembali ke rumah lagi,rumah dan pekarangan sudah di jual.', 989);
