INSERT INTO `bimbingan` VALUES (1079, 13, 799, '2018-11-06', 'koordinasi denganketua kelompok (p.harianto ) untuk tunggakan yang jadi tanggungan beliau akan dititipkan kepada mbak dwi minggu depan\nkunjungan kepada pak munakli selaku anggota yang menunggak ada angsuran tunggakan sebesar 400.000 sehingga tunggakan untuk p. munali saja tinggal 1.300.000 per tanggal 06-11-18', 2786);
