INSERT INTO `bimbingan` VALUES (1082, 14, 373, '2018-11-05', 'Saldo tunggakan Rp 1.700.000 PL datang ketemu dengan  ibu rugiyanti dan belum bisa angsur karena suaminya kerja di solo belum pulang, tgl 25-11-2018 PL datang kembali.', 989);
INSERT INTO `bimbingan` VALUES (1083, 14, 332, '2018-11-05', 'saldo tunggakan Rp 2.600.000 PL datang kerumash ibu rukini dalam keadaan kosong Pl datang lagi tgl 15-11-2018. saldo tunggakan ada di ibu musini dan rukini.', 989);
INSERT INTO `bimbingan` VALUES (1084, 14, 131, '2018-11-05', 'saldo tunggakan Rp 3.200.000 PL datang ketemu dengan bp mudoso dan  membuat surat pernyataan yang isinya kelompok sedyo rukun sudah lunas, dulu setor ke hardi santoso.(UPKD). dan kapan pun mau di ajak ketempat atau ketemu dengan bp hardi santoso bp mudoso beserta anggoat siap dan mau.', 989);
INSERT INTO `bimbingan` VALUES (1085, 14, 204, '2018-10-30', 'PL datang ke kelompok ketemu dengan istri dari pak Murdiyono dan mempunyai kesepakatan bahwa angsuran di ambil setiap hari senin,dan di bulan ini terkumpul angsuran sebanyak Rp 730.000 dengan begitu tunggakan sampai dengan bulan ini setelah di kurangi angsuran tersebut Rp 7.300.000,-', 989);
INSERT INTO `bimbingan` VALUES (1086, 14, 204, '2018-11-05', 'PL datang ke kelompok ketemu dengan istri dari pak Murdiyono dan nitip angsuran Rp 100.000 janjian lagi seharusnya tgl 12-11-2018 tetapi suaminya belim bekerja kembali dan mohon ambil angsuran di tgl 19-11-2018 ', 989);
INSERT INTO `bimbingan` VALUES (1087, 13, 605, '2018-11-07', 'kunjungan ke dusun lundo kekediaman pak junaidi terkait kesanggupannya mengangsur tunggakan tanggal ini. setelah dikonfirmasi pakjunaidi minta tambahan waktu lagi karena masih belum ada pemasukan ,pakjunaidi bersedia membayar tunggakan pada tanggal 20 November 2018', 2786);
INSERT INTO `bimbingan` VALUES (1088, 13, 530, '2018-11-08', 'kunjungan ke bulilik untk sementara ini pihak terkait tidak bisa ditemui karena masih berada di sekolahan ', 2786);
