INSERT INTO `bimbingan` VALUES (1090, 13, 582, '2018-11-08', 'SURAT PERNYATAAN BU SANTI :\nSaya benar2 bersedia bertanggungjawab terhadap kelompok rosella yang saya ketuai bahwa benar dana tersebut dipakai oleh anggota dan saya pribadi ,,alasan tidak bisa mengangsur karena tunggakan itu untuk menutup dana pinjaman yang telah dibawa anggota saya yang tidak bertanggungjawab ,atas nama sumarni Rp.6.000.000 jasa 900.000 tunggakan total 15.200.000  itu benar2 ada disaya selaku ketua sebesar Rp. 8.300.000', 2786);
