INSERT INTO `bimbingan` VALUES (1257, 27, 47, '2018-12-13', 'Buku kas masih perbaikan,register simpanan wajib dgn simpanan pokok boleh digabung dgn catatan kelompok bisa menjelaskan apabila krosceknya kebuku kas tidak cocok. pastikan kas yg ada ditangan, tolong digulirkan,register pinjaman kas sdh cocok dgn kartu', 2265);
