INSERT INTO `bimbingan` VALUES (1259, 27, 52, '2018-12-13', 'Buku Kas tlg perbaiki karena dari awal saldonya min,Register simpanan dan register pinjaman lanjutkan,tolong buat catatan pinjaman kas karena kas sdh digulirkan', 2265);
INSERT INTO `bimbingan` VALUES (1260, 27, 53, '2018-12-13', 'Buku kas sudah cocok dgn register simpanan dan register pinjaman,pastikan pinjaman kan dikelompok minimal ada pembayaran bunga setiap bulan,bawa buku bimbingan setiap bimbingan.', 2265);
INSERT INTO `bimbingan` VALUES (1261, 27, 61, '2018-12-13', 'Buku Kas sdh cocok dgn register yg lain,pastikan pinjaman kas dikelompok,saldo kas masih ditangan,usahakan kas jangan terlalu besar ditangan,klu bisa ditabung dgn jumlah satu kali angsuran untuk jaga2 siapa tahu ada yg kurang bayar.', 2265);
INSERT INTO `bimbingan` VALUES (1262, 27, 10, '2018-12-13', 'buku kas sdh cocok dgn register pinjaman dan register simpanan, saldo kas boleh digulirkan dgn bunga kesepakatan kelompok, pendapatan bunga tabungan dimasukkan dibuku kas.', 2265);
INSERT INTO `bimbingan` VALUES (1263, 27, 3, '2018-12-13', 'buku kas sdh cocok dgn register simpanan register pinjaman serta pinjaman kas.\nadministrasi yg lain lanjutkan.', 2265);
INSERT INTO `bimbingan` VALUES (1264, 27, 56, '2018-12-13', 'Buku kas masih dibuat baru,karena administrasi yg dibuat bendahara diambil alih oleh ketua.Register pinjaman dan register simpanan tolong dibuat sampai bulan november 2018,pastikan pinjaman dibawah ada catatan,berapa sudah punya modal dikelompok.', 2265);
INSERT INTO `bimbingan` VALUES (1265, 27, 34, '2018-12-13', 'Buku Kas cocok dgn Pinjaman dikelompok,pastikan pinjaman dikelompok ada pembayaran pokok,register pinjaman dan register simpanan sdh cocok dgn buku kas dan kartu.', 2265);
INSERT INTO `bimbingan` VALUES (1266, 27, 38, '2018-12-13', 'buku kas sudah cocok dgn register pinjaman dan register simpanan,serta pinjaman kas pastikan pinjaman dikelompok ada pembayaran pokok dikelompok setiap bulan administrasi yg lain lanjutkan', 2265);
INSERT INTO `bimbingan` VALUES (1267, 27, 68, '2018-12-13', 'buku kas sudah belen dgn registerpinjaman dan simpanan,pastikan pinjaman dikelompok,tolong bawa catatan pinjaman dikelompok setiap bimbingan, tlg buatkan buku bimbingan karena dari awal sdh kasi catatan sampai sekarang belum punya buku bimbingan.', 2265);
INSERT INTO `bimbingan` VALUES (1268, 27, 75, '2018-12-13', 'buku kas masih perlu perbaikan,pastikan pinjaman dikelompok karena saldo tidak cocok dg kekayaan yg dimiliki sesuai dgn keterangan ketua,administrasi yg lain tlg di buatsampai bulan ini (November 2018)', 2265);
INSERT INTO `bimbingan` VALUES (1269, 27, 25, '2018-12-13', 'buku kas sdh cocok dgn register simpanan dan register pinjaman tolong lanjutkan,catatan pinjaman kas tolong dibuat lebih jelas,pastikan pinjaman di kelompok', 2265);
