INSERT INTO `bimbingan` VALUES (1339, 13, 800, '2019-01-07', '31 0kt.kunjungan kepada anggota kelompok atas nama pak slamet terkait tunggakan sejumlah 5.970.000, progres saat ini dibayar Rp 500.000 sisa 5.470.000\n\n26 nov kunjungan kepada anggota kelompok atas nama pak slamet terkait tunggakan sebesar 5.470.000 dibayar sebesar @300.000 sehingga sisa tunggakan adalah 5.170.000 di lunasi pada tanggal 11 desember 2018 ketika panen ayam.\n\n11.desember kunjungan kepada anggota kelompok atas nama pak slamet terkait tunggakan sebesar 5.170.000 dibayar sebesar @500.000 sehingga sisa tunggakan adalah 4.670.000 di angsur pada ahir bulan desember 2018\n\n28 desember 2018 kunjungan kepada anggota kelompok atas nama pak slamet terkait tunggakan sebesar 4.670.000 dibayar sebesar @300.000 sehingga sisa tunggakan adalah 4.370.000\n\n07 januari 2019: kunjungan kepada anggota kelompok atas nama pak slamet terkait tunggakan sebesar 4.670.000 dibayar sebesar @300.000 sehingga sisa tunggakan adalah 4.370.000\nsaat ini progres 400.000 sisa tunggakan 3.970.000', 2786);
INSERT INTO `bimbingan` VALUES (1340, 13, 799, '2019-01-07', 'kunjungan kepada pak harianto sementara tidak bisa ditemui ,pak kusman progres tanggal 12 januari, begitujuga pak munali yang kewajiban tunggakan khusus beliau tinggal 400 rb akan dilunasi pada tanggal 12 januari juga.\n', 2786);
