INSERT INTO `bimbingan` VALUES (1343, 27, 82, '2019-01-09', 'Buku kas masih perbaikan,karena dari awal pencairan dak pernah bimbingan sehingga banyak perbaikan.tolong jumlah komulasinya ditulis setiap bulan,Register Pinjaman dan register simpanan dilanjutkan sampai bulan Desember 2018,', 2265);
INSERT INTO `bimbingan` VALUES (1344, 27, 74, '2019-01-09', 'buku kas masih perlu perbaikan,pastikan pinjaman dikelompok,dan pembayaran setiap bulan minimal bunga, register pinjaman dan simpan tolong dijumlah setiap bulan untuk memudahkan mengkroscek nya, ', 2265);
INSERT INTO `bimbingan` VALUES (1345, 28, 178, '2018-12-31', 'Kekurangan a.n Subani sebesar Rp. 3.000.000,-\nSebenarnya kesanggupan akhir bulan ini diselesaikan.\nBaru bisa membayar Rp. 950.000,-\nSisa kekurangan Rp. 2.050.000,- \nKesanggupan bulan berikutnya', 2356);
INSERT INTO `bimbingan` VALUES (1346, 28, 34, '2018-12-31', 'Penagihan Kekurangan kelompok sbb\nWidodo bayar Rp. 1.060.000,-\nHardiman bayar Rp. 1.370.000,-\nKekurangan Rp. 400.000,-\nKelompok kurang disiplin , kesanggupan selalu meleset\n', 2356);
INSERT INTO `bimbingan` VALUES (1347, 28, 2, '2018-12-31', 'Penagihan kekurangan bulan Desember\nSaryati titip Rp. 700.000,-\nMasih ada kekurangan Rp. 300.000,-\nKelompok kurang disiplin\nKesanggupan, kalu sudah ada akan langsung disetor ke UPK', 2356);
INSERT INTO `bimbingan` VALUES (1348, 28, 23, '2018-12-31', 'Angsuran selalu tidak penuh\nTugiyati titip Rp. 3.850.000,-\nKekurangan ada di 3 orang Yaitu \n1. Tugiyati\n2. Sutarmi\n3. Satirah\nTotal kekurangan sampai saat ini Rp. 10.302.000,-\nKesanggupan :\n1. Tugiyati  :  setelah selesai kredit motor\n2. Sutarmi  : pada bulan Januari s/d february akan transfer pelunasan\n3. Satirah   : tidak jelas\n\nPenanganan yang sudah dilaksankan :\n1. Penagihan rutin dan surat tagihan\n2, Monitoring secara berkala oleh Tim ', 2356);
INSERT INTO `bimbingan` VALUES (1349, 28, 133, '2018-12-03', 'Kekurangan Rp. 23.260.000,- yang disinyalir penyelewengan dari angsuran anggota .\nPenanganan yang sudah dilaksankan :\n1. Penagihan rutin dan surat tagihan\n2. Monitoring secara rutin oleh Tim\n3. Sidak oleh Tim pada sore dan malam hari\n4. Pemanggilan ke kantor UPK BKAD Kec Lendah 2x\n\nHasil :\n1. Kesanggupan yang disampaikan pada saat penagihan dan monitoring selalu tidak tepat / bohong\n2. Dua kali pemanggilan selalu mangkir\n3. Pernah datang ke kantor tapi kesanggupannya untuk hadir lagi bersama istrinya untuk membuat pernyataan juga ingkar\n4. Titip angsuran Rp. 500.000,-', 2356);
INSERT INTO `bimbingan` VALUES (1350, 0, 0, '2019-01-09', 'buku kas masih perlu bimbingan minimal 3x berturut -turut supaya tidak terjadi kesalahan berlarut larut.Register pinjaman dan simpanan dan dijumlah tolong dibuat setiap bulan, pastikan pinjaman dikelompok supaya ada pembayaran minimal bunga,\n\n', 0);
INSERT INTO `bimbingan` VALUES (1351, 0, 0, '2019-01-09', 'buku kas masih perlu bimbingan minimal 3x berturut -turut supaya tidak terjadi kesalahan berlarut larut.Register pinjaman dan simpanan dan dijumlah tolong dibuat setiap bulan, pastikan pinjaman dikelompok supaya ada pembayaran minimal bunga,\n\n', 0);
