INSERT INTO `bimbingan` VALUES (1459, 13, 600, '2019-02-01', 'KUNJUNGAN Terhadap anggota kelompok kelapa atas nama bu kholifah sebagai anggota yang menunggak, Rp.2.600.000,- untuk progres  dibayar 200.000 sehingga tunggaklan tinggal 2.400.000', 2786);
INSERT INTO `bimbingan` VALUES (1460, 0, 0, '2019-02-04', 'Buku Kas masih perlu Perbaikan,Iptw dan pinjaman Kas belum masuk\nRegister Simpanan dan Register pinjaman lanjutkan,buatkan buku pinjaman kas kelompok,karena kas sdh digulirkan,,bawa buku tulis biasa untuk buku bimbingan dan register pinjaman kas,bimbingan berikutnya semua buku tlg dibawa', 0);
INSERT INTO `bimbingan` VALUES (1461, 27, 859, '2019-02-04', 'Buku Kas Masih Perlu Perbaikan,Iptw,dan Pinjaman kas belum masuk,register pinjaman dan register simpanan tolong lanjutkan,buatkan buku pinjaman kas karena kas sudah digulirkan.bawa buku tulis biasa untuk buku bimbingan dan register pinjaman kas ', 2265);
INSERT INTO `bimbingan` VALUES (1462, 27, 16, '2019-02-04', 'Buku kas masih perbaikan,tolong diawal bimbingan minimal 3x berturut turut,supaya tidak tejadi kesalahan berlarut.register pinjaman kas dan simpanan tolong dibuat setiap bulan dan, dan jumlah kebawah,pastikan pinjaman dibawah supaya ada pembayaran bunga setiap bulan', 2265);
