INSERT INTO `bimbingan` VALUES (1471, 22, 1597, '2019-02-12', 'Sudah berkali-kali dilakukan penagihan tetapi jawaban yang didapat berbeda-beda, berjanji dengan mencari pinjaman dari pihak ketiga, tetapi tidak ada hasilnya. Mulai Bulan November sampai Desember tidak ada angsuran yang masuk. Terakhir UPK diajak ke beberapa anggota kelompok yang masih menunggak tetapi jumlah uang yang teridentifikasi jauh dari tunggakan.', 1492);
