INSERT INTO `bimbingan` VALUES (1512, 11, 5602, '2019-02-26', 'Kelompok ini samapai dengan bulan Februari pertanggal 26-02-2019 mempunyai tunggakan sebesar Rp. 11.074.000 sesuai dengan kartu angsuran dan rekening koran.\nTunggakan tersebut  ada d beberapa anggota, diantaranya : \n1. Idah Kp. Dugreup Rp. 272.000\n2. Kokom Kp. Baros Rp. 791.000\n3. Iroh Kp. Cipicung Rp. 1.042.000\n4. Nunung Kp. Cipicung Rp. 530.000\n5. Nunung Apad Kp Cipicung Rp. 318.000\n6. Santi Kp. Cipicung Rp. 190.000\n7. Musaropah Kp. Ciseueur Rp. 70.000\n8. Elis Nurhayati Rp. 7.861.000', 2614);
