INSERT INTO `bimbingan` VALUES (1895, 11, 5643, '2019-07-30', 'Per-tanggal 30 Juli 2019 kelompok ini masih mempunyai tunggakan sebesar Rp. 17.625.000,- (menurut data di UPK).\nSetelah ditemui didapatkan data tunggakan sebagai berikut :\n1. Anita (Paniis) Rp.2.205.000,- (menunggak setoran selama 3x,dengan setoran /bulan sebesar Rp. 735.000) alasan nunggak ada masalah dikeluarga hingga akhirnya pindah ke Bojonggambir dan sekarang berada di Kalimantan.\n2. Titim (Cileutik) Rp. 1.050.000,- belum setor 1 bulan alasan nunggak masalah keuangan\n3. Astri (Cileutik) Rp. 2.100.000,- (menunggak setoran selama 2x,dengan setoran /bulan sebesar Rp. 1.050.000) alasan menunggak masalah keuangan\n4. Nuryani (Cileutik) Rp. 210.000,-\n5. Maesaroh (Pangangonan) Rp. 6.300.000,- (menunggak setoran selama 6x,dengan setoran /bulan sebesar Rp. 1.050.000) alasan menunggak karena punya anak yang sedang di Dunia Pendidikan (Mondok   Sekolah) tepatnya di Pesantren Nurul Wafa yang tiap bulannya harusmenyediakan biaya sebesar Rp. 1.200.000,-', 2616);
INSERT INTO `bimbingan` VALUES (1896, 11, 5643, '2019-07-30', 'terusan No. 5 >> Sehingga berimplikasi pada setoran ke UPK karena besarnya biaya yang harus dikeluarkan itupun belum termasuk biaya hidup sehari-hari.\n6. Lela (Pangangonan) Rp. 730.000,- Alasan menunggak karena masalah keuangan\n7. Isah (Pangangonan) Rp. 350.000,- Alasan menunggak karena masalah keuangan\n8. Herni (Cileutik) Rp. 1.400.000,- Alasan menunggak karena masalah keuangan\n9. Maryati (Pangangonan) Rp. 2.100.000,- Alasan menunggak karena masalah keuangan\n10. Aay (Pangangonan) Rp. 500.000,- Alasan menunggak karena masalah keuangan', 2616);
INSERT INTO `bimbingan` VALUES (1897, 11, 5643, '2019-07-30', 'Selanjutnya menurut Ketua Kelompok Masalah lain yang timbul dikarenakan adanya anggota/nasabah yang meminjam ke Bank Keliling sehingga yang tadinya setor bagus jadi bermasalah karena harus setoran mingguan ke Bank keliling.\n\nKemudian sebenarnya sudah ada uang masuk dari nasabah sebesar Rp. 780.000,- namun tidak langsung disetorkan ke UPK karena Ketua Kelompok Beranggapan terlalu kecil dan ingin menunggu hingga diatas angka 1jt, namun sebelum mencapai nominal sesuai yang diharapkan sudah ada Kel. lain dari Desa yang Berbeda (Kel. Ibu Heni Jayaguna yang uangnya diambil oleh sekretarisnya yg bernama Lilis) meminjam uang dengan Alasan untuk Pelunasan setoran ke UPK sehingga akhirnya uang tersebut dipinjamkan kepada Kelompok tersebut.\n\nSetelah ditemui langsung Untuk blok Cileutik khusus, sudah ada kesanggupan dari Sdri. Astri untuk meng-handle semuanya (yaitu u/ Nasabah a.n Astri, Titim, Nuryani dan Herni) yg berjumlah total Rp. 4.760.000,- yang akan diusahakan dibayar akhir bulan / 31 Juli 2019.', 2616);
INSERT INTO `bimbingan` VALUES (1898, 11, 5602, '2019-07-30', 'Hasil dari kunjungan hari ini 30 Juli 2019 didapatkan Data tunggakan sebagai berikut :\n1. Idah Rp. 272.000,-\n2. Kokom Rp. 685.000,-\n3. Elis (Ketua Kelompok) Rp. 7.830.000,-\nSehingga total tunggakan Rp. 7.830.000,- hanya tersebar di 3-orang dengan tunggakan terbesar ada di Ketua Kelompok Sdri. Elis dan masuk setoran saat dikunjungi / ditagih sebesar Rp. 120.000,- (Tunggakan Elis Rp. 7.710.000,-', 2616);
