INSERT INTO `bimbingan` VALUES (1930, 11, 5600, '2019-09-18', 'Seluruh Tunggakan Kel. Cendana sampai saat ini hanya berada pada Satu Orang yaitu Ketua Kelompok, Menurut pengakuan Ketua Kelompok bahwa Seluruh tunggakkan akan diselesaikan bersamaan dengan berakhirnya masa setoran Kel. Cendana dan setelah Rumah ybs Laku terjual (Sudah ada yang menawar namun belum deal)', 2616);
INSERT INTO `bimbingan` VALUES (1931, 11, 5626, '2019-09-25', 'Kelompok ini mempunyai tunggakan sebesar Rp. 2.803.000, dengan 2 kali tunggakan yaitu pada bulan agustus dan september 2019, menurut pengakuan Ketua Kelompok murni seluruh tunggakan bersumber dari Ketua Kelompok sendiri 1 orang.\nAlasan menunggak karena usaha warungan yang ia jalankan sedang mengalami penurunan omset pendapatan (malah pernah suatu hari cuma mendapat pemasukan 6.000 dalam satu hari).\nSelanjutnya, menurut beliau tunggakan akan diangsur sekuatnya dan menurut beliau juga bulan depan insaalloh sudah bisa normal lagi karena akan ada barang yang dilelang.', 2616);
INSERT INTO `bimbingan` VALUES (1932, 4, 4763, '2019-09-30', 'pembayaran tunggakan dengan sistem penjualan garam di kantor UPK dan di Koperasi. setiap hari ada transaksi penjualan garam setiap hari pula dimasukkan angsuran', 130);
INSERT INTO `bimbingan` VALUES (1933, 11, 5593, '2019-10-03', 'Tunggakkan Kel. Nusa Indah tercatat ada pada :\n1. Juju Juariah (Almh.) nasabah yang meninggal dengan pinjaman sebesar Rp. 10.000.000,- sampai saat ini klaim asuransi belum cair sehingga otomatis menjadi tunggakkan.\n2. Tita, ybs mempunyai tunggakan karena masalah keuangan di keluarga dengan tunggakan sekitar 5jt-an\n3. Yayah, ybs sekarang posisinya ada di Jakarta dan yang bertanggungjawab atas pembayaran pinjamannya adalah anaknya yg dalam beberapa bulan tidak bisa setor karena masalah keuangan\n4. Jeje, belum pernah bayar dgn pinjaman 10jt.', 2616);
INSERT INTO `bimbingan` VALUES (1934, 23, 1354, '2019-10-23', 'pencairan 18 Oktober 2019 tabungan prastiono 500.000 Supriono 200.000 Tariono 200.000 Siti Mufarokah 100.000 Tamari 225.000 Jamiatun 375.000 Rokhim 150.000 Hermanto 100.000 total 1.850.000', 1761);
INSERT INTO `bimbingan` VALUES (1935, 10, 3725, '2019-11-13', 'kelompok Ken Arok sudah melewati jatuh tempo pelunasan, tetapi masih memiliki tunggakan sebesar Rp. 16.877.500-, setelah melakukan kunjungan ke kelompok tersebut kendala yang ada adalah uang setoran dari anggota kelompok masih dipakai oleh ketua kelompok.', 494);
INSERT INTO `bimbingan` VALUES (1936, 11, 5626, '2019-12-04', 'Sampai saat tunggakan yang dimiliki oleh kel, ini tertumpu pada satu orang yaitu Ketua Kel. a.n N. Nina Herlina dengan alasan Kondisi keuangan yang tidak baik yang diakibatkan oleh kondisi pendapatan warung yang menurun karena persaingan dan disisi lain beliau-pun pernah tertipu dengan investasi usaha yang ditawarkan oleh orang luar.\ndan sumber keuangan satu2nya saat ini hanya dari pendapatan warung tersebut, sehingga berdampak pada penyetoran atas pinjamannya sendiri.', 2616);
INSERT INTO `bimbingan` VALUES (1937, 18, 363, '2019-12-28', 'tunggakan di salipah sejumlah 2.988.000\nanggota yang lain digabung dengan klp. Lestari', 1222);
INSERT INTO `bimbingan` VALUES (1938, 4, 4098, '2019-12-31', 'NOR KAMILAH sudah 4 bulan minggat dan belum bayar angsuran.', 105);
INSERT INTO `bimbingan` VALUES (1939, 10, 3637, '2020-01-15', 'Kelompok ini akan melakukan pengajuan pinjman disarankan agar melakukan pertemuan kelompok dan mengajukan proposal pinjaman sesuai dengan kebutuhan anggota karena dalam riwayat anggsuran terdapat tunggakan karena ketua/pengurus kelompok sedang sakit parah', 594);
INSERT INTO `bimbingan` VALUES (1940, 11, 1863, '2020-01-23', 'Kelompok ini dari segi ansuran kurang lancar tapi pada saat jatuh tempo kelompok ini dapat melunasinya', 1591);
INSERT INTO `bimbingan` VALUES (1941, 10, 2893, '2020-02-04', 'kunjungan di temui oleh anak dari pemanfaat. dari hasil kunjungan, ketua kelompok mengangsur sebesar Rp 100.000,-. ', 596);
INSERT INTO `bimbingan` VALUES (1942, 10, 2933, '2020-02-04', 'kunjungan di temui oleh ketua kelompok, dan tunggakan disebabkan oleh anggota kelompok atas nama Lilik. dari hasil kunjungan, anggota kelompok mengangsur sebesar Rp 100.000,-. ', 596);
INSERT INTO `bimbingan` VALUES (1943, 10, 2957, '2020-02-04', 'kunjungan di temui oleh ketua kelompok, tunggakan disebabkan oleh ketua kelompok dari hasil kunjungan, ketua kelompok mengangsur sebesar Rp 100.000,-. ', 596);
INSERT INTO `bimbingan` VALUES (1944, 10, 1928, '2020-02-04', 'kunjungan ditemui oleh saudara dari Ketua kelompok, tunggakan disebabkan oleh penyalahgunaan oleh ketua kelompok. dan juga dari hasil kunjungan diketahui bahwa ketua kelompok dan keluarga ada dikalimantan', 596);
INSERT INTO `bimbingan` VALUES (1945, 10, 1925, '2020-02-04', 'dari hasil kunjungan ke Ketua kelompok, ditemukan bahwasanya tunggakan tersebut sebesar Rp 263.000,- terdapat pada koodinator kelompok atas nama Imam Hanafi dan ketua kelompok tidak mengetahui adanya tunggakan tersebut', 596);
