INSERT INTO `bimbingan` VALUES (1948, 10, 1924, '2020-02-04', 'Dari hasil kunjungan didapati bahwasannya ansuran ketua dan anggota kelompok ditagih oleh salah satu anggota atas nama Su dan oleh anggota kelompok tidak disetorkan/disalahgunakan oleh anggota tersebut.', 621);
