INSERT INTO `bimbingan` VALUES (2098, 4, 6691, '2020-04-20', 'Pembinaan, kelompok Adem ayem tidak mau bayar meskipun di paksa, dengan Alasan Corona, \nmenurut sharing bank BPTN Mekar bulan maret dan april juga tidak mau bayar.\njumlah anggota yg di ajukan juga sama 15 orang.\nsatu kebonagung cuma kelompok ini yg tidak mau bayar menurut BTPN mekar.\nhasil pembinaan kelompok diarahkan untuk bayar kalo tidak bisa penuh bisa 70% atau 50% nya, dan bayar lebih  di saat sudah mampu untuk membayar ', 1883);
