INSERT INTO `bimbingan` VALUES (2115, 23, 2843, '2020-06-18', 'KELOMPOK SEJAHTERA PADA BULAN APRIL SEMUA ANGGOTA KELOMPOK TIDAK ADA YG MEMBAYAR TAPI MEREKA BERJANJI PADA WAKU JATUH TEMPO LUNAS AKAN MEMBAYAR 2 KALI ANGSURAN JADI PELUNASANYA TIDAK MUNDUR SATU BULAN .AKAN TETAPI MULAI SAAT ITU ANGSURAN JADINYA MUNDUR MUNDUR JUNI SAJA ANGSURANYA JADI TANGGAL 20 JADI INTINYA TIAP AWAL BULAN HARUS MENGINGGATKAN ANGSURAN', 1765);
INSERT INTO `bimbingan` VALUES (2116, 23, 2691, '2020-06-18', 'KELOMPOK INI AWALNYA BAGUS WALAU MEMANG LAMA LAMA ADA KENDALA ANGSURAN SEMUA ANGGOTA KELOMPOK JADINYA MUNDUR TANGGAL BAHKAN SAMPAI TGL 15 KEATAS TAPI INTINYA TIAP AWAL BULAN MESTI DI WA DULU MENGINGATKAN ANGSURAN DAN YG PALING SULIT ADALAH BU ENDRIANA ANGSURANYA MULAI BULAN MARET SELALU KURANG KURANG DAN YG BULAN MEI BU SITI JUGA MULAI ADA KEKURANGAN 140 RIBU ,KELIHATANYA MEMANG KELOMPOK INI TIDAK BISA DI BERI PINJAMAN BANYAK KARENA BISA JADI MEREKA ADA ANGSURAN DI EKP MEKAR ATAU SYARIAH ATAU BINA ARTA JADI KALAU PUN DI CAIRKAN TODAK BISA DI TAMBAH UNTUK BU ENDRIANA MUNGKIN LEBIH BAIK PENGAJUNA DEOAN DI CORET SAJA TAPI BIARKAN TETAP PENGAJUAN TAPI TIDAK USAH DI REALISASIKAN ,KARENA KALAU TIDAK DI MOTIVASI PINJAM NANATINYA BU ENDRIANAN TIDAK AKAN SELESAI', 1765);
INSERT INTO `bimbingan` VALUES (2117, 23, 2691, '2020-06-18', 'KELOMPOK INI AWALNYA BAGUS WALAU MEMANG LAMA LAMA ADA KENDALA ANGSURAN SEMUA ANGGOTA KELOMPOK JADINYA MUNDUR TANGGAL BAHKAN SAMPAI TGL 15 KEATAS TAPI INTINYA TIAP AWAL BULAN MESTI DI WA DULU MENGINGATKAN ANGSURAN DAN YG PALING SULIT ADALAH BU ENDRIANA ANGSURANYA MULAI BULAN MARET SELALU KURANG KURANG DAN YG BULAN MEI BU SITI JUGA MULAI ADA KEKURANGAN 140 RIBU ,KELIHATANYA MEMANG KELOMPOK INI TIDAK BISA DI BERI PINJAMAN BANYAK KARENA BISA JADI MEREKA ADA ANGSURAN DI EKP MEKAR ATAU SYARIAH ATAU BINA ARTA JADI KALAU PUN DI CAIRKAN TODAK BISA DI TAMBAH UNTUK BU ENDRIANA MUNGKIN LEBIH BAIK PENGAJUNA DEOAN DI CORET SAJA TAPI BIARKAN TETAP PENGAJUAN TAPI TIDAK USAH DI REALISASIKAN ,KARENA KALAU TIDAK DI MOTIVASI PINJAM NANATINYA BU ENDRIANAN TIDAK AKAN SELESAI', 1765);
INSERT INTO `bimbingan` VALUES (2118, 23, 3057, '2020-06-18', 'KELOMPOK INI MULAI ANGSURAN PERTAMA BAGUS KUNCINYA TETAP DI WA DULU ANGSURAN DI AMBIL SESUAI JATUH TEMPO DAN MESTI DI AMBIL DI RUMAH BENDAHAR KELOMPOK ,TAPI BULAN JUNI 2020 ANGSURAN YG SESUAI JATUH TEMPO HANYA 3 ORANG YAITU BU NANA  BU SUPARTI ,BU FADLIKA  YG LAIN MUNDUR 3 HARI YAITU BU RASMIANA ,BU FADLIN ,BU MARTINI NYA TAPI MASIH TIDAK LEBIH DARI 4 HARI DARI PENCAIRAN SEMOGA SELAMAYA TETAP BISA KONSISTEN ', 1765);
INSERT INTO `bimbingan` VALUES (2119, 23, 2498, '2020-06-18', 'KELOMPOK INI MULAI ADA DAMPAK COVID 19 ANGSURANYA JADI KUIRANG KURANG KUSUNYA BU BU IDA ATAU BU ANITA APAKHA KARENA DAMPAK ATAU APA YG BULAN MEI SAJA KURANG 700 RIBU TAPI SUDAH DI BAYAR [ADA ANGSURAN BULAN JUNI DAN JUNI BU ANITA KURANG 199 RIBU DAN BU MIN KURANG 160 RIBU JANJI AKAN DI BAYAR DI ANGSURAN BULAN JULI 2020', 1765);
INSERT INTO `bimbingan` VALUES (2120, 23, 1259, '2020-06-23', 'Angsuran 5.525.000 kurang bu gusrina 460.000 160.000,bu parti 160.000,sukini 180.000', 1765);
INSERT INTO `bimbingan` VALUES (2123, 23, 1259, '2020-06-23', 'bu parti dan sukini bayar kekurangan 340.000\n', 1765);
INSERT INTO `bimbingan` VALUES (2122, 23, 1259, '2020-06-23', 'minggu 7 juni bu gusrina bayar 300.000 kurang kurang 330.000 blm denda ', 1765);
INSERT INTO `bimbingan` VALUES (2124, 23, 1270, '2020-06-24', 'Atas nama neni masih ada tunggan angsuran 1.365.000 dan bu lasmini masih ada tunggan 344.000 pada hari ini bu neni angsuran 25.000 dan bu lasmini angsuran 20.000', 1765);
INSERT INTO `bimbingan` VALUES (2125, 23, 2942, '2020-06-24', 'kelompok ini pengajuannya mundur satu bulan jadi lunas baru pengajuan tapi tetap iptw tidak dapat hanya setidaknya tidak mucul tungganan', 1765);
INSERT INTO `bimbingan` VALUES (2126, 23, 1363, '2020-06-24', 'angsuran kelompok ini masih blm bisa lunas tapi masih ada itikad baik untuk angsuran walau kurang kurang dengan rincian \n1.bp imam pinjaman 15.000.000 belim angsuran janji akir bulan \n2bu arsusi pinjaman 11.000.000 angsuran masih bayar 1.000.000kurang 3.327.000\n3.bu lastri pinjaman 7.000.000 angsuran 1.000.000 kurang 1.754.000\n4. bu endang pinjaman 3.000.000 masih angsuran 200.000 kurang 980.000\n5. bu puji pinjaman 5.000.000 masih angsuran 1.000.000 kurang 967.000\nsemua dimotifasi agar bulan ini semua bisa nitip angsuran lagi agar nilai tunggan di kelompok tidak begitu besar .\nhanya saja memang kelompok ini ketika jatuh tempo lunas mesti melunasi entah bagaimana usaha mereka ,setidaknya tidak muncul tunggaan ketka jatuh tempo  lunas', 1765);
INSERT INTO `bimbingan` VALUES (2127, 23, 2477, '2020-06-24', 'Kelompok ini pada tahun ini tahun terparah apalagi ada covid 19 alasanya usaha sangat sepi mulai bulan maret ada 1 orang yg kurang .april satu orang yg bayar hanya 600,000 satu kelompok ,bulan meu blm bayar sama sekali .\njadi bulan juni akirnya tunggaan agak banyak total tunggan sementara setelah di potong angsuran bulan ini \n1. bu dini kurang 2.820.000\n2. bu narti kurang 580.000.\n3. bp yono kurang 960.000\n4. yatemi kurang 1520000 \n5. bu utami kurang 1.460.000\njasa 2% di etor kre upk hanya bu dini terkadang tidak setor fuul 2%', 1765);
INSERT INTO `bimbingan` VALUES (2130, 23, 2841, '2020-06-25', '1.Bu boinah angsuran 230.000 kurang 60.000\n2. Bu tutik angsuran 171.500\n3. Bu markini angsuran 600.000 kurang 280.000', 1765);
INSERT INTO `bimbingan` VALUES (2131, 23, 2841, '2020-06-25', '1.Bu markini angsuran 200 kurang 80.000\n2.Bu supik 280.000 kurang 270.000 \n3.Bu diah 200.000 kurang 290.000\n4.Bu boinah kurangb60.000\ntotal tungganan di anggota 700.000 tunggan di kantor 310.000 sisanya ada tabungan ', 1765);
INSERT INTO `bimbingan` VALUES (2129, 23, 2841, '2020-06-25', 'angsuran pada kelompok ini mulai pada mulai bulan maret mulai ada kekurangan yaitu pada anggota atas bu markini kurang 300.000 dan bulan april tidak ada yg angsuran  karena ada covid 19 ,bulan mei mulai ada angsuran masuk .                  ', 1765);
