INSERT INTO `bimbingan` VALUES (2168, 10, 3607, '2020-07-20', 'Tunggakan sebesar Rp 9.017.500,- terdapat pada ketua kelompok atas nama Ernawati', 596);
INSERT INTO `bimbingan` VALUES (2169, 0, 0, '2020-07-21', 'I} Kelompok libra jaya 2 pencairan 5 september 2019 total realisasi 63.000.000 dengan rincian \n1.sutini 20.000.000\n2.sriatun 8.000.000\n3.solikah 20.000.000\n4.srianah 20.000.000\n5.silismiati5.000.000\nII). Akan tetapi di perjalanan angsuran ke 3 ada permasalahan karena bu sutiani selaku ketua kelompok meninggalkan rumah ,saya arik selaku pendamping kelompok sudah berkali kali ke anggota keluarga tetap tidak ada jawaban kepastian keberadaan bu sutiani .dan bahkan ternyata pinjaman bu srianah yg di penerimaan sejumlah 10 juta ternyata peminjam hanya memakai 2 juta saja yg lain di pinjmakana lagi ke orang lain .\nIII) setelah kami telusuru ke yg pinjam atas nama ternyata bu sutiani pinjam uang ke orang orang yg di pijamai di bawah tangan jadi dengan alasan itu merka tidak mau membayarnya dengan alasan busutiani pinjam uang mereka malah lebih besar dari yg merka pinjam.\nIV)oleh karenanya mulai angsuran ke 3 kita langsung ke salh satu anggota kelompok untuk angsuran denagn memberlakukan jasa sejumlah 2 persen dengan harapn selisihnya bisa untuk menutup sebagian tunggaan akan tetapi di angsuran yg ke 10 bu silikah minta agar yg 0.5% yg terbayrkan di kita selama 8 kali angsuran di kembalikan akirnya angsuran bu solikah yg 0.5% kita potongkan angsuran yg terakir dengan alasan kemanusiaan di kala musim usaha yg muylai sulit karena covid 19\nV)dengan ini kita rincikan jika tidak di potong tabungan total tunggan kelompok ini sebesar 25.760.000 karena ada tabungan di awal 1.650.000 dan selisih 0.5% dari anggota yg tidak kami kembalikan maka total tunggaan bu sutiani sejumlah 22.690.000 jadi selisih 2.800.000 yg berasal dari tabungan awal 1650.000 dan 0.5% selain bu solik 1.150.000', 0);
INSERT INTO `bimbingan` VALUES (2170, 0, 0, '2020-07-21', 'I} Kelompok libra jaya 2 pencairan 5 september 2019 total realisasi 63.000.000 dengan rincian \n1.sutini 20.000.000\n2.sriatun 8.000.000\n3.solikah 20.000.000\n4.srianah 20.000.000\n5.silismiati5.000.000\nII). Akan tetapi di perjalanan angsuran ke 3 ada permasalahan karena bu sutiani selaku ketua kelompok meninggalkan rumah ,saya arik selaku pendamping kelompok sudah berkali kali ke anggota keluarga tetap tidak ada jawaban kepastian keberadaan bu sutiani .dan bahkan ternyata pinjaman bu srianah yg di penerimaan sejumlah 10 juta ternyata peminjam hanya memakai 2 juta saja yg lain di pinjmakana lagi ke orang lain .\nIII) setelah kami telusuru ke yg pinjam atas nama ternyata bu sutiani pinjam uang ke orang orang yg di pijamai di bawah tangan jadi dengan alasan itu merka tidak mau membayarnya dengan alasan busutiani pinjam uang mereka malah lebih besar dari yg merka pinjam.\nIV)oleh karenanya mulai angsuran ke 3 kita langsung ke salh satu anggota kelompok untuk angsuran denagn memberlakukan jasa sejumlah 2 persen dengan harapn selisihnya bisa untuk menutup sebagian tunggaan akan tetapi di angsuran yg ke 10 bu silikah minta agar yg 0.5% yg terbayrkan di kita selama 8 kali angsuran di kembalikan akirnya angsuran bu solikah yg 0.5% kita potongkan angsuran yg terakir dengan alasan kemanusiaan di kala musim usaha yg muylai sulit karena covid 19\nV)dengan ini kita rincikan jika tidak di potong tabungan total tunggan kelompok ini sebesar 25.760.000 karena ada tabungan di awal 1.650.000 dan selisih 0.5% dari anggota yg tidak kami kembalikan maka total tunggaan bu sutiani sejumlah 22.690.000 jadi selisih 2.800.000 yg berasal dari tabungan awal 1650.000 dan 0.5% selain bu solik 1.150.000', 0);
INSERT INTO `bimbingan` VALUES (2171, 0, 0, '2020-07-21', 'I} Kelompok libra jaya 2 pencairan 5 september 2019 total realisasi 63.000.000 dengan rincian \n1.sutini 20.000.000\n2.sriatun 8.000.000\n3.solikah 20.000.000\n4.srianah 20.000.000\n5.silismiati5.000.000\nII). Akan tetapi di perjalanan angsuran ke 3 ada permasalahan karena bu sutiani selaku ketua kelompok meninggalkan rumah ,saya arik selaku pendamping kelompok sudah berkali kali ke anggota keluarga tetap tidak ada jawaban kepastian keberadaan bu sutiani .dan bahkan ternyata pinjaman bu srianah yg di penerimaan sejumlah 10 juta ternyata peminjam hanya memakai 2 juta saja yg lain di pinjmakana lagi ke orang lain .\nIII) setelah kami telusuru ke yg pinjam atas nama ternyata bu sutiani pinjam uang ke orang orang yg di pijamai di bawah tangan jadi dengan alasan itu merka tidak mau membayarnya dengan alasan busutiani pinjam uang mereka malah lebih besar dari yg merka pinjam.\nIV)oleh karenanya mulai angsuran ke 3 kita langsung ke salh satu anggota kelompok untuk angsuran denagn memberlakukan jasa sejumlah 2 persen dengan harapn selisihnya bisa untuk menutup sebagian tunggaan akan tetapi di angsuran yg ke 10 bu silikah minta agar yg 0.5% yg terbayrkan di kita selama 8 kali angsuran di kembalikan akirnya angsuran bu solikah yg 0.5% kita potongkan angsuran yg terakir dengan alasan kemanusiaan di kala musim usaha yg muylai sulit karena covid 19\nV)dengan ini kita rincikan jika tidak di potong tabungan total tunggan kelompok ini sebesar 25.760.000 karena ada tabungan di awal 1.650.000 dan selisih 0.5% dari anggota yg tidak kami kembalikan maka total tunggaan bu sutiani sejumlah 22.690.000 jadi selisih 2.800.000 yg berasal dari tabungan awal 1650.000 dan 0.5% selain bu solik 1.150.000', 0);
