INSERT INTO `bimbingan` VALUES (2209, 23, 1376, '2020-07-21', 'Kelompok libra jaya 2 realisasi pada 5 September 2019 total 63.000.000 dengan rincian \n1. sutini 20.000.000\n2.siti solikah 20.000.000\n3.sriatun 8.000.000\n4.srianah 10.000.000\n5.sulismiati 5.000.000', 1765);
INSERT INTO `bimbingan` VALUES (2210, 23, 1376, '2020-07-21', 'Akan tetapi di tengah perjalan tepatnya di angsuran yg ke tiga busutiani meninggal rumah dan saya arik dan mantan bendahar upk santi sudah berkali kali kerumah dan ke keluarga bu sutiani tidak ada ke jelasan bu sutiani dan bahkan untuk membayarkan keluarga tidak bersedia ', 1765);
INSERT INTO `bimbingan` VALUES (2211, 23, 1376, '2020-07-21', 'akirnya di angsuran ke tiga anggota bayar yg di koordinir bu solikah dengan jasa di kelompok sebesar 2% dengan harapn bisa mengurangi tunggan atas nama bu sutiani dan ternya kita juga baru mengetahui bahwa pinjaman bu srianah yg di data kantor tertulis sejumalh 10 juta dia hanya pakai 2 juta saja yg lain di pinjman ke orang lain oleh sutiani ', 1765);
INSERT INTO `bimbingan` VALUES (2212, 23, 1376, '2020-07-21', 'Dan ketika kita klarifikasi ke orang yg pinjam di luar nama data kantor memang di akui akan tetapi mereka mengatakan bahwa uang mereka di abwa bu sutiani malah lebih besar dari yg mereka terima dari bu stiani dengan kata lain mereka tidak mau membayarkan pinjaman atas nama tersebut', 1765);
INSERT INTO `bimbingan` VALUES (2213, 23, 1376, '2020-07-21', 'Akirnya di angsuran ke 3 anggota membayar dengan jasa yg harus terbayarkan sejunlah 2% dengan hara[pn aklan sedikity mengurangi jumlah tunggan di kantor akan tetapi di angsuran yg kesepuluh bu solikah minta agar yg 0.5% yg di bayarkan minta di kembalikan alasanya ekonomi lagi sulit jadi keberatan kalau jasannya tidak di kembalikan ', 1765);
INSERT INTO `bimbingan` VALUES (2214, 23, 1376, '2020-07-21', 'Akirnya dengan alasan kesihan yg 0.5% atas nama bu solikah saja yg saya kembalikan yg lain tidak saya kembalikan bahkan tabungan awlal tidak bisa kami kembalikan karena bu sutianai masih meninggalnkan tunggan di data kantor ', 1765);
INSERT INTO `bimbingan` VALUES (2215, 23, 1376, '2020-07-21', 'jika tidak di kurangi tabunga awal dan selisih 0.5% yg masih tersisa total tunggan bu sutiani sejumlah 25.760.000 akan tetapi karena ada tabungan awal sejumlah 1.650.000 dan selisih 0.5 % dan terkadang bu srianah menambah angsuranya denagn alasan tanggung jawab sejumlah1.420.000', 1765);
INSERT INTO `bimbingan` VALUES (2216, 23, 1376, '2020-07-21', 'Jadi total tunggan yg menjadi tanggungan sutiani sampai lunas setalh kami potongkan tabungan dan 0.5% dan dari sebagian bu srianah sebesar 22.690.000', 1765);
INSERT INTO `bimbingan` VALUES (2217, 23, 1376, '2020-07-21', 'disini say coba hitungan selain tabungan yaitu 0.5% \n1.sriatun 40.000x8=320.000\n2.srianah 10.000x8=80.000\n3.sulismiati25.000x8=200.000\ntotal 600.000\njadi yg 820.000 adalah uang bu srianah yg dia bayarkan sebagai bukti tanggung jawab karena nama dia yg pinjam di data kantor yg di angsurkan tiap bulan ', 1765);
INSERT INTO `bimbingan` VALUES (2218, 23, 1376, '2020-07-21', 'dengan rincian tangguan sutiani sampai lunas murni yg harus dia bayarkan \n1.sutiani 2.300.000 x8=18.400.000\n2. Srianah 920.000x8=7.360.000\njadi total 25.760.000', 1765);
INSERT INTO `bimbingan` VALUES (2219, 0, 0, '2020-07-22', 'Pada bulan juli nilai tunggan sudah mulai ada perkembangan yg baik anggota yg awalnya menunggak di bulan maret april muali ada pergerakan angsuran kecuali bu munti yg memang meninggalkan rumah ', 0);
INSERT INTO `bimbingan` VALUES (2220, 0, 0, '2020-07-22', 'Pada bulan juli nilai tunggan sudah mulai ada perkembangan yg baik anggota yg awalnya menunggak di bulan maret april muali ada pergerakan angsuran kecuali bu munti yg memang meninggalkan rumah ', 0);
INSERT INTO `bimbingan` VALUES (2221, 23, 1306, '2020-07-22', 'Pada bulan juli mulai ada perbaikan angsuran tunggaan di bulan maret april mulai ada pengurangan ', 1765);
INSERT INTO `bimbingan` VALUES (2222, 23, 1306, '2020-07-22', 'Hanya tinggal sebagian anggota saja yaitu bu munti yg memang mulai angsuran ketiga di bulan maret meninggalkan rumah dan pinjamanya sebesar 15 juta jadi satu kali angsuran 1,725,000 kali 4 kali angsuran yg perjuli ini tunggan bu munti sebesar 6.900.000', 1765);
INSERT INTO `bimbingan` VALUES (2223, 23, 1306, '2020-07-22', 'serta tunggan an bu nur rahayu 3.675.000 di bulan maret april belum di angsur tapi angsuran mei juni julidi bayar lunas dan sisa angsuran bu dian yg mulai ada penurunan karena di angsurperbulan yg perjuli hanya tinggal 600.000 saja adapun bu ariatin sudah lunas ', 1765);
INSERT INTO `bimbingan` VALUES (2224, 23, 1306, '2020-07-22', 'Jadi perbulan juli tunggaan total \n1. bu munti 1.725.000 X 4=6.900.000\n2.bu nur rahayu 3.675.000\n3.bu dian 600.000 \nTotal 11.175.000 \nkecuali bu munti perbulan ada pengurangan karena mereka berjanji akan mengangsur sisa tunggan akan di bayarkan bersama dengan angsuran ', 1765);
