INSERT INTO `bimbingan` VALUES (2236, 23, 1263, '2020-08-14', 'Kelompok ini selama bergabung hampir 10 tahun tidak pernah menunggak ,pengajuan selalu di sesuaikan sesuaikan ,painem thn 2019 pernah pinjm 6 juta,restanti thn 2018 pinjam 7 juta .soleha thn 2018 pinjam 10 juta.leli 2018 pinjam 12 juta.sumiatun 2020 pinjam 10 juta dan selalu dapat iptw', 1765);
INSERT INTO `bimbingan` VALUES (2238, 18, 3088, '2020-09-24', '1. CAIR 9/12/2019 JML 76.000.000\n2. DARYANTI SPK 12JT RIIL 17JT\n3. KUSNIYATI SPK 15JT RIIL 15JT\n4. NURWATI SPK 13,5JT RIIL 11JT\n5. DWI SULASTRI SPK 15JT RIIL 15JT\n6. TRI WP SPK 3JT RIIL 3JT\n7. RASIYEM SPK 13,5JT RIIL 12JT\n8. RIWEN SPK 4JT RIIL 3JT\nKETERANGAN TUNGGAKAN :\n* BULAN APRIL MEI SEMUA ANGGOTA TDK ANGSUR SEBESAR Rp. 14.600.000\n*TARGET ANGSURAN S/D SEPTEMBER 65.700.000\n*ANGSURAN MASUK KE UPK 41.485.500\n* TUNGGAKAN SEBSAR Rp. 24.214.500 DG RINCIAN SBB\n   - ANGS APRIL MEI : Rp. 14.600.000\n   - Kusniyati Rp. 1.500.000\n   - Dwi Sulastri Rp. 400.000\n   - Nurwati   Rp. 1.500.000\n   - Tri WP Rp. 200.000\n   - Daryanti Rp. 6.014.500\nTotal    Rp. 9.614.500\nRincian tunggakan anggota per September 2020 sbb :\na. Kusniyati       Rp. 4.500.000\nb. Dwi Sulastri  Rp. 3.400.000\nc. Nurwati         Rp.  3.700.000\nd. Tri WP           Rp.      800.000\ne. Rasiyem       Rp.   2.400.000\nf.  Riwen          Rp.       600.000\ng. Daryanti       Rp.   9.414.500\ntotal                  Rp. 24.214.500', 1207);
