INSERT INTO `bimbingan` VALUES (2241, 18, 3170, '2020-03-23', 'CATATAN PINJAMAN RIIL DI KELOMPOK :\n1. Toyibah Rp. 8.000.000\n2. sufroti Rp. 5.000.000\n3. Yulia (Domplengan)\n4. Perni Rp. 18.000.000\nTunggakan angsuran :\n1. Perni sisanya\n2. Toyibah 6.000.000 (4 bln yg ngangsur)\n3. Sufroti 1 bulan  kekurangan (Rp. 2.090.000)\n4. Yulia (domplengan)', 1207);
