INSERT INTO `bimbingan` VALUES (2244, 18, 5926, '2020-06-10', 'tunggakan bulan mei 20 :\na. Uli Rp.400.000x 3bulan =Rp. 1.200.000 (berhenti kerja)\nb. Mini Astutui Rp. 500.000x3bulan =Rp. 1.500.000\nc. B munjriyah pinjaman Rp.2.500.000 minggat usaha mandeg\nd. Sulis rumahnya bawahnya bu muhirotun (suami bunuh diri pinjaman Rp. 2.000.000)\nSPK belum disetor\n', 1207);
