INSERT INTO `bimbingan` VALUES (2254, 18, 676, '2020-06-17', 'Tunggakan s/d bulan Mei Rp. 11.420.000, dari anggota belum ada yang masuk.\nBulan November tanam modal Ketua kelompok sekiatar Rp. 5.000.000 dipake Ketua kelompok dan sisanya di anggota.\nTanam modal untuk usaha catering Bu Supartini (mamanya Bani) ternyata penipu sekarang dah diproses secara hukum.\nKesanggupan mulai bulan depan diangsur dan anggota lain tetap mengangsur seperti biasa. Tiap bulan hrs masuk walopun punya angsuran selain Ketua.', 1207);
INSERT INTO `bimbingan` VALUES (2255, 18, 507, '2020-06-17', 'a. Bu Ludiasih usaha jualan celengan di tempat wisata pinjaman Rp.4.000.000, terakhir angsur bulan februari 2020.tunggakan mulai Maret 2020.\nb. Bu Yanti usaha genteng pinajaman Rp. 8.000.000 nunggak mulai maret 2020\nc. Bu Sulastri usaha catering track sama jual makanan kecil di lingkungan proyek.proyek skrg berhenti. pinjaman Rp. 4.000.000, mulai nunggak bulan februari 2020.\nd. Bu Khusnul pinjaman Rp. 8.000.000 tapi dikembalikan 2 minggu setelah pencairan dan ahirnya dibagi kepada : Yanti (5jt), SSulastri (1,5jt) dan Ludiasih (1,5jt).\njadi  pinjaman Yanti 13jt, Sulastri 5,5jt dan Ludiasih 5,5jt\nKESANGGUPAN :\nBulan Juli 2020 mengangsur sesuai kemampuan\nTunggaan per mei 2020 sebesar Rp. 5.100.000 (pokok jasa)', 1207);
INSERT INTO `bimbingan` VALUES (2256, 18, 3116, '2020-07-15', 'Tunggakan di Bu Siti Muntaqiah Di SPK Rp. 15.000.000 Riil Rp. 10.000.000 dan yang Rp. 5.000.000 dipinjam bu susmiyatun.\nTunggakan b siti Muntaqiah sebesar 5x angsuarn s/d Juli 2020.\nalasan nunggak : biaya skripsi, biaya sekolah anak dll.\nKesanggpuan : Diangsur sesuai kemampuan.', 1207);
