INSERT INTO `bimbingan` VALUES (2260, 10, 3607, '2020-09-29', 'tunggakan terdapat pada anggota kelompok atas nama Siti Soleha Rp 3.400.000,- Hosnawiyah Rp 350.000,- dan ketua kelompok atas nama Ernawati Rp 9.900.000,-.\nTerdapat penyalahgunaan pinjaman sebesar Rp 19.500.000,- oleh ketua kelompok, yang mana pinjaman tersebut tidak disalurkan pada anggota kelompok yang terdapat pada SPK, melainkan dipinjamkan pada orang lain.', 596);
