INSERT INTO `bimbingan` VALUES (2267, 18, 751, '2020-10-16', 'tgl 16 Oktober 2020  ada kesanggupan dr ketua kelompok untuk ngangsur setiap bulan.\nsisa pinjaman seluruhnya di ketua klp.\nTab klp sudah masuk 30 Des 2017 sebesar Rp. 1.632.000', 1222);
INSERT INTO `bimbingan` VALUES (2268, 18, 3185, '2020-10-20', 'INFORMASI Bu Samijah Suami, Bu Samijem suami kerja di Jakarta.\nBu. Darisem juga kerja dfi Jakart, suaminya di Peniron tp tdk ketemu.\nBu. Annisahketemu janji minggu depan mau angsur ke UPK 250.000 tapi kemudian suaminya kasih 500.000, alasan suami tidak tahu menahu ttg pinjaman istrinya namun dai akan tanggung jawab melunasinya.', 1207);
