INSERT INTO `bimbingan` VALUES (2272, 10, 3667, '2020-11-04', 'pada tanggal 31 oktober 2020 anggota kelompok an Isnaeni meninggal dunia karena sakit, kemungkinan tunggakan bulan november disebabkan karena anggota tsb. dan sudah mengajukan penghapusan pinjaman.', 595);
