INSERT INTO `bimbingan` VALUES (2286, 18, 5835, '2021-01-28', 'Tunggakan Riil di UPK s.d tgl 28 Januari 2021 adalah sejumlah Rp. 1.200.000,00, dan Tunggakan Riil di kelompok adalah sejumlah Rp. 2.200.000,00 adapun tunggakan tersebut ada pada 2 orang Yaitu:\n1. Eni Budiarti Rp. 1.000.000,00\n2. Khusnawasih Rp. 1.200.000,00', 1209);
