INSERT INTO `bimbingan` VALUES (2289, 18, 5835, '2021-02-01', 'Hasil klarifikasi antara Ketua UPK dan BP  ( Titi Ananingsih dan Akhmad Masruri )ke Ketua kelompok yaitu Ibu Eni Budiarti, adl sbb:\nTunggakan Riil di kelompok adalah sejumlah Rp. 2.200.000,00 ada pada:\n1. Khusnawasih  Rp. 1.200.000,00\n2. Eni Budiarti Rp. 1.000.000\n', 1209);
INSERT INTO `bimbingan` VALUES (2290, 18, 5926, '2021-02-01', 'Hasil Klarifikasi yang di lakukan oleh UPK dan BP ( Titi Ananingsih dan akhmad Masruri ) dengan Ketua Kelompok yaitu Uli Rahmadani adalah\nTunggakan masih ada pada:\n1. Munjiah Rp. 2.750.000,00\n2. Sulis Fajar Ria Rp. 2.400.000\n3. Uli Rahmadani  Sisa Tunggakan', 1209);
INSERT INTO `bimbingan` VALUES (2291, 18, 3090, '2021-02-04', 'Berdasarkan informasi dari Pak Syamsul dan Pak Amin, ada salah satu anggota yang angsuran nya masih kurang yaitu a.n Toni Fardiansah dengan pinjaman Rp. 1.000.000,00 dan menurut informasi Toni masih kurang dari 4 bulan yang lalu dan sudah beberapa kali di talangi oleh Pak Amin', 1209);
INSERT INTO `bimbingan` VALUES (2292, 11, 2839, '2021-02-10', 'DI Validasi tgl 03/2/2021 oleh Pak Dadan dan Ibu Ai Imat:\nPinjaman an. Ipah Tidak ada di tempat sedang TKW\nPinjaman an. Devi juga sama tidak ada ditempat', 2575);
INSERT INTO `bimbingan` VALUES (2293, 18, 2978, '2021-02-11', 'Angsuran masuk sejumlah Rp. 494.000,00 adalah angsuran a.n Nahariyah ( Istri pak Muhsinun ) dan angsuran tsb menggunakan uang Suport Kades ( Insentif pembinaan tahun 2020 )', 1209);
INSERT INTO `bimbingan` VALUES (2295, 18, 5450, '2021-03-04', 'Tanggal 4 Maret 2021 Angsuran masuk sejumlah Rp. 440.000,00 adalah a.n sbb:\n1. Elli S                      Rp. 110.000,00\n2. Sugiarti                 Rp. 110.000,00\n3. Rita Ekawati         Rp. 110.000,00\n4. Wiji                        Rp. 110.000,00\nAngsuran tsb untuk bulan Januari 2021\n\nTgl 4 Maret 2021 Angsuran masuk Rp. 220.000 adalah atas nama:\n1. Elli                          Rp. 110.000,00\n2. Rita Ekawati         Rp. 110.000,00\nAngsuran tersebut untuk angsuran bulan Februari 2021\nAdapun yang masih kurang Adalah:\n1. Wijiati kurang 1X yang bulan februari 2021\n2. Sugiarti kurang 1x yang bulan Februari 2021\n3. Pawit kurang 2 X yang bulan Jan dan februari 2021\n4. Eri Andriyani kurang 2 X yang bulan Januari dan Februari 2021\n5. Nur Hidayah kuran 2 X yang bulan Januari 2021 dan Februari 2021', 1209);
INSERT INTO `bimbingan` VALUES (2296, 18, 5835, '2021-03-08', 'Tgl 8 Maret 2021,,saudara Amril ngangsur Rp. 150.000,00 atas nama istrinya Kusnawasih, jadi per hari ini kurangnya Rp. 1.050.000,00', 1209);
INSERT INTO `bimbingan` VALUES (2297, 18, 599, '2021-03-12', 'Angsuran masuk a.n Nur Fatmah sejumlah Rp. 25.000,00 ', 1209);
INSERT INTO `bimbingan` VALUES (2298, 11, 2934, '2021-03-17', 'Hasil Validasi Toni Kurniawan : 27/3/2021\nSaldo 3.081.000 menurut Ketua Kelompok (Dedah) ada di :\n1. Jojo (Alm) Istrinya tidak tahu menau\n2. Ateng Jaelani (Kakanya Juhriah) tidak ada di tempat pindah ke Anteg Malatisuka\n3. Asep Rohim, Pindah tempat ke Bandung', 2575);
INSERT INTO `bimbingan` VALUES (2299, 18, 644, '2021-03-19', 'Angsuran a.n Khopiyah masuk sejumlah Rp. 1.900.000,00 dan yang memberi uangnya adalah anaknya yang bernama Nur Khuzaemah yang beralamat di Kelapa sawit, Buluspesantren', 1209);
INSERT INTO `bimbingan` VALUES (2300, 11, 3038, '2021-03-22', 'Hasil Validasi BP. Suryadinata tanggal 22/2/2021 saldo pinjaman sebesar Rp. 1.446.000, berada di Ketua Kelompok Ibu Mumun, tetapi tang bersangkutan sudah pindah alamat menurut keterangan anggota kelompok Ibu Uhan..', 2575);
INSERT INTO `bimbingan` VALUES (2301, 11, 2721, '2021-03-23', 'Hasil Validasi Tanggal 18 Oktober 2017, semua anggota masih punya tunggakan\ntetapi anggota yang bernama Mira Tasmirah dan Ani pindah ke Luar Kota, sedangkan tunggakan pinjamannya ditanggung oleh Ketua Kelompok Ibu Yanti Susanti\n', 2575);
INSERT INTO `bimbingan` VALUES (2302, 11, 2718, '2021-03-23', 'Hasil Validasi tanggal 18 Oktober 2017, saldo pinjaman sebesar Rp. 3.650.000 ada di\n1. Nonong Sadiah Rp. 2.700.000\n2. Aah Satriah Rp. 950.000', 2575);
INSERT INTO `bimbingan` VALUES (2303, 11, 3094, '2021-03-23', 'HAsil Validasi tanggal 13 Desember 2017, saldo pinjaman Rp. 1.050.000,  menurut Ketua Kelompok IIs Parida sudah lunas tidak mempunyai lg pinjaman\nValidator : Imas N dan Dadan Dahlan', 2575);
INSERT INTO `bimbingan` VALUES (2304, 11, 3094, '2021-03-23', 'HAsil Validasi tanggal 13 Desember 2017, saldo pinjaman Rp. 1.050.000,  menurut Ketua Kelompok IIs Parida sudah lunas tidak mempunyai lg pinjaman\nValidator : Imas N dan Dadan Dahlan', 2575);
INSERT INTO `bimbingan` VALUES (2305, 11, 3094, '2021-03-23', 'HAsil Validasi tanggal 13 Desember 2017, saldo pinjaman Rp. 1.050.000,  menurut Ketua Kelompok IIs Parida sudah lunas tidak mempunyai lg pinjaman\nValidator : Imas N dan Dadan Dahlan', 2575);
INSERT INTO `bimbingan` VALUES (2306, 18, 5515, '2021-03-26', '1 Tagihan An Titin Sunarni.Untuk segera melakukan kwajiban Angsurnnya ', 1194);
INSERT INTO `bimbingan` VALUES (2307, 18, 5926, '2021-03-30', 'Berdasarkan data di lapangan, untuk tunggakan a.n Uli Ramadani adalah sejumlah Rp. 6.475.000 dan hari ini Selasa tanggal 30 Maret 2021 Uli ngangsur Rp. 2.500.000 ', 1209);
INSERT INTO `bimbingan` VALUES (2308, 18, 3074, '2021-04-06', 'Angsuran masuk sejumlah Rp. 200.000,00 a.n Bu Baengah ( Turman )', 1209);
INSERT INTO `bimbingan` VALUES (2309, 18, 644, '2021-04-13', 'Tgl 7 April 2021 Angsuran a.n Khopiyah masuk sejumlah Rp. 350.000,00 dan yang memberi uangnya adalah anaknya yang bernama Nur Khuzaemah yang beralamat di Kelapa Sawit, Buluspesantren', 1209);
