INSERT INTO `catatan_bp` VALUES (10, '2018-07-12 10:57:04', 11, 200, '2018-06', 'CATAAN HASIL BADAN PENGAWAS PERIODE 31 JUNI 2018\n\nBUKU KAS,BANK Dll \nBuku kas operasional upk\nbuku kas pinjaman spp\nbuku kas UEP\nBuku kas usaha lain\nbuku kas pinjaman lain\nbuku bank operasional\nbuku bank spp\nbuku bank uep\nbuku bank usaha lain\nbuku pinjaman spp\nbuku pinjaman uep\nbuku pinjaman lainya\nbuku dibayar dimuka\nbuku iventaris\nbuku aktiva tetap\nbuku rupa-rupa aktiva\nbuku hutang \n- hutang kelembagaan\n-hutang dansos\n-hutang bonus upk\n-hutang lain-lain \n-hutang cadangan resiko\nbuku modal SPP\nbuku modal uep\nbuku modal blm\nbuku modal dana hibah pihak ketiga\nbuku modal lain-lain\nsurplus ditahan\npendapatan operasional\npendapatan non operasional\nbiaya dana\nbiaya operasional\nbiaya penghapusan pinjaman\nbiaya non operasional\nperkembangan pinjaman spp\nlaporan cadangan resiko\nlaporan iventaris:\n- biaya dibayar dimuka\n-iventaris\n-aktiva tetap\nneraca ;\naktiva:\nkas operasional uok\nkas pinjaman\nkas pinjaman lainya\nbank operasional\nbank spp\npinjaman:\npinjaman spp\npinjaman uep\npinjaman lainya\nbiayadibayar dimuka;\niventaris\naktiva tetap\nrupa-rupa aktiva\n\nPasiva\nhutang:\nhutang kelembagaan\nhutang dana sos\nhutang  bonus upk\nhutang lain-lain\ncadangan resiko\n\nModal\nmodal spp\nmodal uep\nmodal BLM 20%\nmodal dana hibah\nlain-lain\nsurplus/devisit ditahan\nsurplus /devisit\n\nneraca saldo: 5.661.638.235\nrugi laba ; 516.219.736\nNERACA: 5. 406.847.764\npendapatan operasional:512.904.000\npendapatan non operasional : 3.315.730\ntotal pendapatan : 516.219.736\nbiaya dana: 35 000.000\nbiaya operasional: 219.106.854\nbiaya non operasional: 683.617\ntotal biaya: 254.790.471\nsurplus/devisit 261429.265\n\n laporan perubahan modal pertanggal31 juni 2018\nmodal spp: 2.330.930.400\nmodal BLM: 56.119.100\nmodal dana hibah pihak ketiga: 16. 291.461\nmodal lain-lain:24.271.100\nsurplus / devisit di tahan : 2.675.231.430\nsurplus /devisit berjalan: 261.429.265\ntotal modal: 5.364.352.764\n\nmodal awal spp: 2.387.129.500\naset produktif: 4.305.705.027\nperkembangan dana:1.918.575.527\nprosentase perkembangan : 80%\n\nlaporan penggunaan dana / E budgeting.\ntotal realisasi pendapatan: 539.811.736\ntotal realisasi biaya: 256.436.471.\n\nsurplus/devisit/shu: 283.375.265\n\nklasifikasi tingkat kesehatan\n rasiosaldo kredit beresiko= 40 kategori sehat\nrasio cadangan resiko kredit - 0 kurang sehat\nrasio laba bersih terhadap kekayaan upk = 10 kategori sehat\nrasio biaya operasional 8.75 kategori sehat\nrasio saldo kredit terhadao kelompok upk 7.5 kategori cukup sehat\nrasio kekayaan bersih upk = 10 kategori sehat\ntotal nilai: 76.35 ( cukup sehat).', 2622);
