INSERT INTO `catatan_bp` VALUES (35, '2019-12-26 15:27:43', 11, 199, '2019-12', 'Kesimpulan dan Saran : Berdasarkan Evaluasi semua Transaksi dan bukti Kwitansi serta penunjang lainnya, maka kami menyimpulkan : Bahwa semua Transaksi pada bulan Desember 2019 dapat dipertanggungjawabkan.\nBidang Organisasi dan Manajemen : Sampai dengan bulan Desember 2019, Stabil sesuai dengan SOP.\nKita konsen pada suksesi LPJ tahun buku 2019.\nBidang Usaha dan Administrasi : Menjelang tahun buku 2020, kita canangkan Kontrak Jasa Kepengacaraan guna memacu rabat sesuai target.\nBidang Keuangan dan Permodalan : Memadai pada kapasitasnya.', 2608);
