INSERT INTO `catatan_bp` VALUES (55, '2020-06-29 11:54:48', 23, 144, '2020-06', '1. Laporan keuangan sudah baik mohon dipertahankan\n2. untuk kelompok yang macet segra ditindak lanjuti ke kelompok\n3. Waspadai kelompok yang masuk kolektabilitas 3 keatas\n4. Inventaris kendaraan mohon diamankan , dan bisa digunakan \n    untuk operasional UPK.\n5. Untuk pencairan kelompok peminjam usahakan pencairan \n    didampingi oleh kepala desa ( perangkat Desa ) untuk \n    keamanan.\n6. Setiap pencairan jangan lupa didokumentasikan.', 1846);
