INSERT INTO `catatan_bp` VALUES (57, '2020-06-29 12:27:14', 23, 144, '2019-02', '1. Pencatatan laporan keuangan sudah baik.\n2. Semua transaksi dibukukan dengan baik.\n3. Persiapan MAD tutup buku sudah dipersipakan dengan baik.\n4. kelompok yang masuk daftar kolektabilatas mohon diingatkan agar tidak terjadi kemacetan.\n5. perlu ada pembinaan kelompok secara berkala.\n6. Acara pertemuan ketua kelompok setiap tanggal 10 perbulan sangat baik untuk memantau kondisi kelompok.', 1846);
