INSERT INTO `catatan_bp` VALUES (69, '2020-10-21 10:32:56', 0, 0, '2020-01', 'Jasa pengembalian SPP Bulan Januari  Rp 31.680.500, pendapatan denda SPP Rp 500.00, pendapatan jasa PL Rp 195.000, Bunga bank pengembalian SPP Rp 179.338, Total pendapatan selama bulan Januari Rp 32.554.838.\nBiaya operasional Rp 23.557.858, biaya non operasional Rp 1.091.368, total biaya bulan januari Rp 24.649.226\nSurplus yang diterima selama bulan januari Rp 7.905.612\nJumlah pencairan kredit SPP selama bulan januari Rp 322.000.000, dengan total 5 kelompok SPP, untuk realisasi kredit perorangan tidak ada.\nKas pinjaman SPP yang ada dineraca sudah sesuai dengan buku bank.\nCatatan : mohon tetap dilakukan pinjaman kredit perorangan dengan melihat kondisi keuangan dan lebih mengutamakan kepentingan kredit kelompok.\nKredit perorangan tetap dengan prinsip 5C dan dengan analisa kredit yang lebih cermat.', 0);
INSERT INTO `catatan_bp` VALUES (74, '2020-10-23 10:14:27', 12, 75, '2020-01', 'Jasa pengembalian SPP Bulan Januari Rp 31.680.500, Pendapatan denda SPP Rp 500.000, Pendapatan jasa PL Rp 195.000, Bunga bank pengembalian SPP Rp 179.338, total pendapatan selama bulan Januari Rp 32.554.838\nBiaya operasional Rp 23.557.858, biaya non operasional Rp 1.091.368, total biaya bulan januari Rp 24.649.226\nSurplus yang diterima selama bulan Januari Rp 7.905.612\nTotal pencairan selama bulan Januari Rp 322.000.000, dengan total 5 kelompok.\nKas pinjaman spp dineraca sudah sesuai dengan yang ada di Bank', 906);
INSERT INTO `catatan_bp` VALUES (83, '2020-10-23 12:01:03', 12, 75, '2020-02', 'Jasa pengembalian SPP bulan pebruari Rp 46.837.700, pendapatan jasa PL Rp 500.000, pendapatan lainnya kas SPP 375.000, bunga bank pengembalian SPP 93.200, total pendapatan selama bulan pebruari Rp 47.805.00\nBiaya operasional Rp 32.378.875, biaya non operasional 1.294.140 total biaya bulan pebruari Rp 33.673.015, surplus selama bulan pebruari Rp 14.132.885\nPencairan kelompok selama bulan pebruari Rp 217.500.000 dengan jumlah 6 kelompok \nDilihat dari segi surplus bulan lalu mengalami kenaikan sebesar Rp 78,77%', 906);
INSERT INTO `catatan_bp` VALUES (76, '2020-10-23 10:47:00', 12, 75, '2020-03', 'Jasa pengembailan SPP bulan maret Rp 29.921.500, pendapatan jasa PL Rp 500.000, bunga bank pengembalian SPP 52.558, total pendapatan bulan Maret Rp 30.474.058\nBiaya operasional 31.250.875, biaya non operasional 16.012, total biaya selama bulan maret 31.266.887, devisit Rp 792.829\nPencairan kelompok selama bulan maret Rp 240.051.500, dengan jumlah 5 kelompok.\ndilihat dari segi pendapatan maka bulan maret mengalami devisit disebabkan karena biaya lebih besar daripada pendapatan, karena pendapatan lebih kecil dari pada biaya.\nBuku bank sudah sesuai dengan laporan yang ada dineraca', 906);
INSERT INTO `catatan_bp` VALUES (77, '2020-10-23 10:57:33', 12, 75, '2020-04', 'Jasa pengembalian SPP Rp 45.925.192, pendapatan jasa PL 8.063, bunga bank 31.945, total pendapatan selama bulan April Rp 45.965.200\nBiaya operasional 32.004.875, biaya non operasional 11.889, total biaya selama bulan april 32.016.764\nsurplus selama bulan maret Rp 13.948.436\nRealisasi pinjaman SPP selama bulan April Rp 144.000.000 dengan jumlah 2 kelompok.', 906);
