INSERT INTO `catatan_bp` VALUES (78, '2020-10-23 11:05:31', 12, 75, '2020-05', 'Jasa pengembalian SPP bulan mei Rp 78.949.433, pendapatan lainnya kas SPP 7.320.000, bunga bank pengembalain SPP 51.142, total pendapatan selama bulan mei Rp 86.320.575\nBiaya operasional Rp 57.241.908, Biaya non operasional 15.728, total biaya Rp 57.257.636\nSurplus selama bulan Mei Rp 29.062.939\nRealisasi pinjaman SPP selama bulan Mei Rp 444.050.000 dengan jumlah 4 kelompok.\nmengalami kenaikan surplus sebesar Rp 108%.', 906);
INSERT INTO `catatan_bp` VALUES (79, '2020-10-23 11:15:25', 12, 75, '2020-06', 'Jasa pengembalian SPP Juni Rp 37.386.084, pendapatan jasa PL 387.937, pendapatan lainnya kas SPP 284.400, bunga bank pengembalian SPP 43.017, Total pendapatan bulan Juni Rp 38.101.438\nBiaya operasional Rp 30.212.708, biaya non operasional 14.103, total biaya selama bulan Juni 30.226.811\nSurplus selama bulan Juni Rp 7.874.627\nRealisasi pinjaman SPP selama bulan juni Rp 234.779,200 dengan jumlah 4 kelompok.', 906);
INSERT INTO `catatan_bp` VALUES (80, '2020-10-23 11:25:10', 12, 75, '2020-07', 'Jasa pengembalian SPP selama bulan Juli Rp 41.840.500 pendapatan denda SPP Rp 500.000, pendapatan lainnya kas SPP Rpp 450.000, bunga bank pengembalian SPP 41.537, total pendapatan selama bulan Juli Rp 42.832.037\nBiaya operasional Rp 32.319.908, biaya non operasional 13.807, total biaya selama bulan juli Rp 32.333.715\nSurplus selama bulan juli Rp 10.498.322\nRealisasi pinjaman SPP selama bulan juli Rp 132.000.000 dengan jumlah 4 kelompok', 906);
INSERT INTO `catatan_bp` VALUES (81, '2020-10-23 11:40:01', 12, 75, '2020-08', 'Jasa pengembalain SPP bulan Agustus 80.408,500, pendapatan jasa PL Rp 103.000, pendapatan lainnya kas SPP Rp 2.538.000, bunga bank pengembalian SPP 75.735, Total pendapatan selama bulan agustus Rp 83.125.235\nBiaya operasional 34.428.826, biaya non operasional 20.647, total biaya selama bulan agustus Rp 35.080.473\nsurplus selama bulan agustus Rp 48.044.762\ntotal pencairan SPP selama bulan agustus Rp 336.738.000 dengan jumlah 3 kelompok.\nKenaikan surplus sangat signifikan karena ada pembayaran tunggakan bulan kemarin yang dibayarkan bulan ini.', 906);
INSERT INTO `catatan_bp` VALUES (82, '2020-10-23 11:51:52', 12, 75, '2020-09', 'Jasa pengembalian SPP bulan september Rp 36.992.000, bunga bank pengembalian SPP Rp 117.858, total pendapatan bulan september Rp 37.109.858\nBiaya operasional Rp 30.153.163,biaya non operasional 29.072, total biaya selama bulan september Rp 30.182.235\nTotal surplus selama bulan september Rp 6.927.623\nTotal pencairan SPP selama bulan september Rp 50.000.000 dengan jumlah 1 kelompok.\nuntuk pencairan kredit perorangan dan kelompok perlu dilakukan dengan prinsip kehati hatian, disamping tetap dengan prinsip 5C\npenagihan piutang tetap dilakukan dengan prinsip kekeluargaan dan pendekatan masing - masing individu\nAnggota tetap dilayani secara maksimal', 906);
