INSERT INTO `catatan_bp` VALUES (85, '2020-11-03 10:06:28', 18, 109, '2020-11', 'VI. TEMUAN HASIL AUDIT BADAN PENGAWAS BKAD KECAMATAN KLIRONG\n          KABUPATEN KEBUMEN BULAN JULI SAMPAI DENGAN BULAN \nSEPTEMBER 2020                                 \nA.	Temuan\nTerdapat pelaksanaan verifikasi kelompok SPP Shellomita Desa Tambakprogaten yang tidak sesuai dengan permintaan kekuatan  calon anggota peminjam yang akan membayar angsuran kepada UPK BKAD Kecamatan Klirong.\n\nB.	Kriteria/Resiko\n		Hal ini bertentangan dengan Standar Operasional Prosedure (SOP) yang telah disyahkan melalui Musyawarah Antar Desa dan telah ditanda tangani oleh Ketua BKAD Ã¢â‚¬Å“LestariÃ¢â‚¬Â Kecamatan Klirong tanggal 03 Februari 2016.\n\nC.	Tindak Lanjut\n Ketua  BKAD Ã¢â‚¬Å“LESTARIÃ¢â‚¬Â memerintahkan kepada ketua UPK agar dalam  medeligasikan tugas kepada Staf lebih dipertimbangkan terhadap dampak yang akan terjadi dikemudian hari.\n\nD.	Penanggung Jawab\n 	 Ketua BKAD Ã¢â‚¬Å“LestariÃ¢â‚¬Â Kecamatan Klirong Kabupaten Kebumen.\n\n		Demikian hasil audit keuangan UPK BKAD Kecamatan Klirong untuk tribulan ketiga  (bulan Juli sampai dengan bulan September 2020) untuk menjadikan periksa.\n\nKlirong, 06 Oktober 2020\n\nBADAN PENGAWAS BKAD\nKECAMATAN KLIRONG, KABUPATEN KEBUMEN\n\n1.	Drs. H. Soekono\nKetua\n\n2.	Sulasi Tri Wahyuningsih\nSekretaris\n\n3.	H.Akmad Maskur S.Ag\nAnggota\n\n', 1380);
