INSERT INTO `catatan_bp` VALUES (95, '2021-03-06 10:19:23', 12, 73, '2021-02', 'PEMERIKSAAN BP BULAN PEBRUARI 2021 :\na.	Pemeriksaan Kas Operasional telah sesuai dan sama jadi tidak ada bentuk kekeliruan atau penyimpangan pada posisi kas operasional UPK sebesar Rp. 372.500,-, dan telah dituangkan dalam bentuk lampiran berita acara pemeriksaan Kas Opname yang telah ditanda tangani oleh Banwas.\nb.	Pemeriksaan Rekonsiliasi Penggunaan Dana oleh Pengurus UPK tidak ada bentuk kekeliruan atau penyimpangan pada posisi transaksi penerimaan dan pengeluaran dalam kegiatan usaha pengelolaan oleh Pengurus UPK dengan perolehan saldo akhir yang sesuai dengan nilai saldo bank   dengan saldo kas operasional UPK sejumlah Rp. 916.868.221,-, dan pemeriksaan ini telah dituangkan dalam lampiran Pemeriksaan Rekonsilisasi Penggunaan Dana yg telah tertnda tangani.\nc.	Pemeriksaan Administrasi dan Pencatatan Keuangan yang ada dalam laporan Neraca dan Laporan Operasional Laba Rugi belum ditemukannya adanya bentuk penyimpangan dan kekeliruan dalam proses pencatatan dan pengadministrasiannya, serta pemeriksaan ini telah dituangkan dalam lampiran Pemeriksaan Administrasi dan Pencatatan Keuangan.\n', 880);
INSERT INTO `catatan_bp` VALUES (96, '2021-03-08 11:01:58', 0, 0, '2021-02', '1.  Buku Rekening Bank SPP ditutup pada tanggal 18 Pebruari 2021.\n2.  SPP Penerimaan - Pengeluaran selisih kurang Rp  2.853.000.\n3.  UEP Penerimaan - Pengeluaran selisih lebih  Rp  2.853.000.\n4. Operasinal tidak ada selisih\n', 0);
INSERT INTO `catatan_bp` VALUES (97, '2021-03-17 08:54:26', 12, 75, '2020-10', 'Jasa pengembalian SPP bulan oktober Rp 36.987.000, bunga bank spp Rp 167.085, total pendapatan bulan oktober Rp 37.154.085\nBiaya operasional Rp 31. 445.113, biaya non operasional 2.038.917, total biaya selama bulan oktober \nTotal surplus selama bulan oktober Rp 3.670.055\nTotal pencairan selama SPP selama bulan oktober Rp 240.792.000\nuntuk pencairan kredit perorangan dan kelompok perlu dilakukan dengan prinsip kehati hatian, disamping tetap dengan prinsip 5C\npenagihan piutang tetap dilakukan dengan prinsip kekeluargaan dan pendekatan masing masing individu\nAnggota tetap dilayani secara maksimal.', 906);
INSERT INTO `catatan_bp` VALUES (98, '2021-03-17 09:20:58', 12, 75, '2020-11', 'Jasa pengembalian SPP bulan oktober 105.064.231, pendapatan jasa PL Rp. 392.000, pendapatan lainnya kas SPP Rp 900.000, bunga bank pengembalian SPP Rp 191.028, total pendapatan bulan oktober Rp 106.547.259\nBiaya operasional Rp 31.431.313, biaya non operasional 43.706, total biaya selama bulan okober Rp 31.475.019\nTotal surplus selama bulan oktober Rp 75. 072.240\nTotal pencairan SPP selama bulan oktober Rp 121.522.000\nuntuk pencairan kredit perorangan dan kelompok perlu dilakukan dengan prinsip kehati hatian, disamping tetap dengan prinsip 5C', 906);
INSERT INTO `catatan_bp` VALUES (99, '2021-03-17 09:42:09', 12, 75, '2020-12', 'Jasa pengembalian SPP bulan Desember Rp 101.235.146, pendapatan  jasa PL Rp 2.468.213,bunga bank pengembalian SPP rP 327.501, total pendapatan Rp 104.030.860\nBiaya operasional Rp 32.409.613, biaya non operasional Rp 581.000\nTotal surplus selama bulan desember Rp 71.040.247\nTotal pencairan SPP selama bulan desember Rp 324.455.000\nUntuk pencairan kredit perorangan dan kelompok perlu dilakukan dengan prinsip kehati hatian, disamping tetap dengan prinsip 5C', 906);
INSERT INTO `catatan_bp` VALUES (100, '2021-03-17 10:01:25', 12, 75, '2021-01', 'Jasa pengembalian SPP bulan januari Rp 65.161.562, pendapatan lainnya kas SPP Rp 900.000, bunga bank pengembalian SPP 452.595, total pendapatan Rp 66.514.157\nBiaya operasional Rp 39.010.213, biaya non operasional 7.146.019, total biaya bulan januari 46.156.232\nSurplus yang diterima bulan januari Rp 20.357.925\nKas pinjaman SPP di neraca sudah sesuai dengan yang ada di bank', 906);
INSERT INTO `catatan_bp` VALUES (101, '2021-03-17 10:09:11', 12, 75, '2021-02', 'Jasa pengembalian SPP Bulan Pebruari Rp 40.850.356, pendapatan jasa PL Rp 253.000, pendapatan lainnya kas SPP Rp 1.770.000, bunga bank pengembalian SPP Rp 87.819, total pendapatan selama bulan pebruari Rp 42.961.175\nBiaya operasional Rp 29.434.028, biaya non operasional Rp 23.064\ntotal biaya selama bulan pebruari Rp 29.457.092\nSurplus selama bulan pebruari Rp 13.504.083\nKas pinjaman SPP dineraca sudah sesuai dengan yang ada di bank', 906);
INSERT INTO `catatan_bp` VALUES (102, '2021-03-25 11:51:27', 11, 292, '2021-03', 'Hasil Pemeriksaan Tanggal 25 Maret 2021\nPengawasan Terhadap Absensi Karyawan UPK Periode 26 Feb - 25 Maret 2021, Diharapkan Setiap Karyawan Agar Selalu Memperhatikan Absensinya \nPengawasan Terhadap kelompok Yang Sudah Melakukan Perguliran Agar Diberikan Pembinaan dan Monitoring Setiap Bulannya Termasuk Yang Berkenaan Dengan Kewajiban Setoran ...', 3749);
INSERT INTO `catatan_bp` VALUES (103, '2021-04-15 09:50:48', 2, 3, '2021-03', 'Ada selisih Rp  2.853.000,\nSaldo penerimaan - Pengeluaran = Rp 30.619.188\nDana yang ada di Bank Rp 26.391.188\nDana Kas ditangan  Rp  1.375.000\nJumlah  Rp 27.766.188', 263);
INSERT INTO `catatan_bp` VALUES (105, '2021-06-03 13:30:07', 12, 76, '2021-04', 'A. LAPORAN RUGI LABA\n    1.  Total pendapatan Rp. 19.103.473,-\n    2.  Total biaya Rp. 12.541.131,-\n    3.  Surplus 6.562.342,-\n\nB. BANK SPP Rp. 402.780.279,-\nc. KOLEKTIBILITAS PINJAMAN\n   1.  Kolek I Rp. 485.100.000,-\n   2.  Kolek II Rp. 225.451.000,-\n   3.  Kolek III Rp. 43.590.000,-\n   4.  Kolek IV Rp. 2.300.000,-\n   5.  Kolek V Rp. 804.368.000,-\n\nD. RASIO KREDIT BERISIKO  : nilai 0 (tidak sehat)\n\nE.  REKOMENDASI\n (1)  Pendampingan dan pembinaan terhadap nasabah  dioptimalkan, (2) Pemberian pinjaman dengan mengedepankan kehati-hatian; (3) Lakukan rescedule terhadap pinjaman macet kolek V sesuai SOP, dan (5) Teken kolek V hingga menurun setidaknya 5% per bulan. \n \n\n\n', 919);
