INSERT INTO `desa` VALUES (1200, '14001', 'Panggang', '14001001', 'Giriharjo', '', '', 1, '14', 'ARIS EKO WIDIYANTO, S.Sos.', '', '', '0', 'MUH. HARYANTO', '0', 'SUNARNO', '0', 'Desa Giriharjo terletak di ibukota Kecamatan Panggang, terdiri dari 6 dusun yang meliputi dusun di wilayah pusat ibukota yaitu Dusun Panggang I, Panggang II, Panggang III, serta dusun di wilayah utara yang berbatasan dengan kabupaten Bantul yang meliputi Dusun Banyumeneng I, Banyumeneng II, dan Banyumeneng III', 'T', '0000-00-00 00:00:00', '', '0', '', 'giriharjo', '55872');
