INSERT INTO `desa` VALUES (1202, '14001', 'Panggang', '14001003', 'Giriwungu', '', '', 1, '1', 'TULUS', '', '', '0', 'RENO PRIHARTONO', '0', 'EKO KUS MARWANTO', '0', 'Desa Giriwungu berada di wilayah timur ibukota Kecamatan Panggang yang terdiri dari 5 padukuhan yaitu Dukuh Jurug, Pudak, Pejaten, Klepu, dan Petung', 'T', '0000-00-00 00:00:00', '', '0', '', 'giriwungu', '55872');
INSERT INTO `desa` VALUES (1205, '14001', 'Panggang', '14001006', 'Girikarto', '', '', 1, '15', 'TUYADI', '', '', '0', '', '0', '0', '0', 'Desa Girikarto secara geografis terletak di wilayah paling selatan Kecamatan Panggang berbatasan dengan Samudra Hindia. \nWilayah Desa\nWilayah Desa Girikarto\nNomor Kode                : 34-03-01-2001\nKecamatan                 : Panggang\nKabupaten                  : Gunungkidul\nProvinsi                      : Daerah Istimewa Yogyakarta\n1. Luas dan Batas wilayah\n    a. Luas Desa   : 1393.7000 Ha\n    b. Batas-batas  Wilayah\n       1. Utara  : Desa Girimulyo\n       2. Timur : Desa Krambilsawit\n       3. Selatan: Samudra Hindia\n       4. Barat   : Desa Giriwungu\n2. Kondisi Geografis\n    a. Ketinggan Tanah dari Permukaan Laut          : 200 - 250 m\n    b. Banyaknya Curah Hujan                              : 2.500 mm/Th\n    c. Topografi (dataran rendah, tinggi, pantai)     : 5% - 25% - 70%\n    d. Suhu Udara Rata-rata  : 28 C - 34 C\n3. Orbitasi (jarak dari pusat pemerintahan Desa)\n    a. Jarak dari pusat pemerintah desa     : 8 Km\n    b. Jarak dari Ibukota Kabupaten           : 49 Km\n    c. Jarak dari Kota Provinsi                    : 50 Km\n', 'T', '0000-00-00 00:00:00', '', '0', '', 'girikarto', '55872');
