INSERT INTO `desa` VALUES (2597, '184', 'Godean', '3404040004', 'Sidoagung', '', '', 1, '10', 'Edi Utomo', '', '', '', ' Sigit Suwardianto ,S.Pd.', '', '', '', 'Desa Sidoagung\n\nAlamat  : Jl. Godean km. 10, Sidoagung, Godean, Sleman\n\nTelpon   :  (0274) 797406\n\n\nSidoagung adalah desa di kecamatan Godean, Sleman, Daerah Istimewa Yogyakarta, Indonesia. Pada mulanya Desa Sidoagung merupakan wilayah yang terdiri dari 2 (dua) Kelurahan, masing-masing adalah : Kelurahan Senuko dan Bendungan. Berdasarkan maklumat Pemerintah Daerah Istimewa Yogyakarta yang diterbitkan tahun 1946 mengenai Pemerintahan Kelurahan, maka kelurahan-kelurahan tersebut kemudian digabung menjadi 1 Desa yang otonom dengan nama Desa Sidoagung, yang kemudian secara resmi ditetapkan berdasarkan Maklumat Nomor 5 Tahun 1948 tentang Perubahan Daerah-Daerah Kelurahan.\n\nDesa Sidoagung terdiri dari 8 Dusun yakni :\n	\n1. Bendungan\n2. Sentul Geneng\n3. Gentingan\n4. Godean\n5. Jowah\n6. Kramen\n7. Senuko\n8. Genitem\n', 'T', '0000-00-00 00:00:00', '0', '0', '', 'sidoagung', 'sidoagung');
INSERT INTO `desa` VALUES (2598, '184', 'Godean', '3404040006', 'Sidoarum', '', '', 1, '4', 'Ganefo Sugiartono, SE', '', '', '', '', '', '', '', 'Desa Sidoarum \n\nAlamat: Jalan Godean km 6,5 Sidoarum Godean Sleman Yogyakarta 55564\n\nDesa Sidoarum merupakan kawasan penyanggga Kota Yogyakarta, sehingga tumbuh sebagai kawasan hunian dan mengalami perkembangan pesat secara ekonomi. Pada mulanya Desa Sidoarum merupakan wilayah yang terdiri dari 2 (dua) Kelurahan, masing-masing adalah : Kelurahan Candran dan Krapyak. Berdasarkan maklumat Pemerintah Daerah Istimewa Yogyakarta yang diterbitkan tahun 1946 mengenai Pemerintahan Kelurahan, maka Kelurahan-kelurahan tersebut kemudian digabung menjadi 1 Desa yang otonom dengan nama Desa Sidoarum, yang kemudian secara resmi ditetapkan berdasarkan Maklumat Nomor 5 Tahun 1948 tentang Perubahan Daerah-Daerah Kelurahan.\n\n\n    Utara : Desa Sidomoyo Kecamatan Godean.\n    Selatan : Desa Sidokarto Kecamatan Godean dan Desa Ambarketawang, Kecamatan Gamping.\n    Barat : Desa Sidokarto Kecamatan Godean.\n    Timur : Desa Nogotirto Kecamatan Gamping.\n', 'T', '0000-00-00 00:00:00', '0', '0', '', 'sidoarum', 'sidoarum');
INSERT INTO `desa` VALUES (2599, '184', 'Godean', '3404040005', 'Sidokarto', '', '', 1, '6', 'H. Istiyarto Agus S. S.E', '', '', '', '', '', '', '', 'Kantor Kelurahan Sidokarto terletak di Padukuhan Nogosari, Sidokarto, Godean, Sleman, Yogyakarta yang saat ini berdiri dibangun sekitar tahun 1980, pada awalnya seluruh kegiatan pelayanan berada atau terletak di padukuhan Wirokraman, Sidokarto, Godean, Sleman yang saat ini menjadi sarana belajar mengajar PAUD (Pendidikan Anak Usia Dini).\npaud wirokraman\nPAUD Wirokraman\n\nKantor Kalurahan Sidokarto berdiri diatas lahan dengan luas sekitar 3.375 m2, dengan batas sebelah utara Jalan Desa, sebelah timur Jalan Sidokarto, sebelah selatan Pekarangan, sebelah barat Puskesmas Godean II.\n\nKantor Kelurahan Sidokarto memiliki luas bangunan total sekitar 975 m2, dengan pembagian bangunan kantor utama sekitar 175 m2, bangunan gedung sekitar 300 m2, bangunan penunjang sekitar 500 m2.  Guna meningkatkan pelayanan saat ini bangunan Kantor Kelurahan Sidokarto sedang dalam progres renovasi.\n\nSidokarto\n\nSidokarto (Jawa: Sidakarta) adalah desa di kecamatan Godean, Sleman, Daerah Istimewa Yogyakarta, Indonesia. Pada mulanya Desa Sidokarto merupakan wilayah yang terdiri dari 3 (tiga) Kelurahan, masing-masing adalah : Kelurahan Rewulu, Wirokraman, dan Klajoran. Berdasarkan maklumat Pemerintah Daerah Istimewa Yogyakarta yang diterbitkan tahun 1946 mengenai Pemerintahan Kelurahan, maka 3 (tiga) Kelurahan tersebut kemudian digabung menjadi 1 Desa yang otonom dengan nama Desa Sidokarto, yang kemudian secara resmi ditetapkan berdasarkan Maklumat Nomor 5 Tahun 1948 tentang Perubahan Daerah-Daerah Kelurahan.\n\nLuas Wilayah Desa\n\nLuas wilayah Desa Sidokarto sebesar 364 Ha. Luas lahan yang ada terbagi dalam beberapa peruntukan, antara lain untuk pertanian yaitu untuk tanah sawah sebesar 200,94 ha; untuk tanah pekarangan sebesar 115,35 ha; dan untuk tanah tegalan sebesar 10,10 ha sebab keadaan desa Sidokarto jenis tanahnya nyabuk dan subur. Semua tanah sawah dapat diairi dengan irigasi teknis, sehingga sepanjang tahun dapat ditanami padi. Luas lahan yang dipergunakan untuk fasilitas umum adalah sebagai berikut untuk tanah kuburan sebesar 2,19 ha, untuk jalan/sungai sebesar 24,77 ha, dan untuk lain-lain sebesar 10,62 ha.\n\nBatas Wilayah :\n\n  Utara : Kecamatan Mlati\n Timur : Desa Sidomoyo, Desa Sidoarum \n  Selatan: Desa Sidomulyo\n  Barat : Desa Sidoagung\n\nNama Padukuhan :\n1	Jethak I\n2	Jethak II\n3	Klajuran\n4	Semarangan\n5	Ngawen\n6	Wirokraman\n7	Sorolaten\n8	Prenggan\n9	Jetis Prenggan\n10	Rewulu Wetan\n11	Rewulu Kulon\n12	Sembuh Wetan\n13	Nogosari\n14	Dukuh\n\n', 'T', '0000-00-00 00:00:00', '0', '0', '', 'sidokarto', 'sidokarto');
INSERT INTO `desa` VALUES (2600, '184', 'Godean', '3404040002', 'Sidoluhur', '', '', 1, '3', 'Hernawan Zudanto, SE.', '', '', '', 'Fajar Nugroho S.P.', '', '', '', 'Sidoluhur (Jawa: Sidaluhur) adalah Desa di Kecamatan Godean, Kabupaten Sleman, Provinsi Daerah Istimewa Yogyakarta, Negara Indonesia. Sidoluhur dibentuk pada 5 Desember 1946 \n\nDesa Sidoluhur terdiri dari 15 dusun, yaitu :\n1. SOKONILO\n2. BERJO KULON II\n3. BERJO KIDUL III\n4. BERJO WETAN IV\n5. NGABANGAN V\n6. JOWAH VI\n7. PANDEAN VII\n8. KUNDEN VIII\n9. GATAK IX\n10. DADAPAN X\n11. SERANGAN XI\n12. MERTOSUTAN XII\n13. TEBON XIII\n14. KRAGILAN X1V\n15. KRAJAN XV\n\nPotensi Wilayah :\n- Daerah Pertanian.\n- Industri Genteng dan Batu bata.\n- Pusat Oleh-oleh Keripik Belut.\n- Kelompok Peternak Kambing PE.\n- Kelompok Perikanan\n- Pasar Godean ( centra perekonomian ).\n\nBatas Wilayah :\n- Utara : Desa Margoluwih Kecamatan Seyegan\n    \n- Timur : Desa Sidoagung\n\n- Selatan : Desa Sumbersari Kecamatan Moyudan\n\n- Barat  : Desa Sidorejo\n', 'T', '0000-00-00 00:00:00', '0', '0', '', 'sidoluhur', 'sidoluhur');
INSERT INTO `desa` VALUES (2601, '184', 'Godean', '3404040007', 'Sidomoyo', '', '', 1, '7', 'Hariyadi', '', '', '', '', '', '', '', 'Desa Sidomoyo \n\nSidomoyo (Jawa: Sidamaya) adalah desa di kecamatan Godean, Sleman, Daerah Istimewa Yogyakarta, Indonesia. Pada mulanya Desa Sidomoyo merupakan wilayah yang terdiri dari 2 (dua) Kelurahan, masing-masing adalah : Kelurahan Ngrenak dan Karanglo. Berdasarkan maklumat Pemerintah Daerah Istimewa Yogyakarta yang diterbitkan tahun 1946 mengenai Pemerintahan Kelurahan, maka Kelurahan-Kelurahan tersebut kemudian digabung menjadi satu Desa otonom dengan nama Desa Sidomoyo. Desa Sidomoyo kemudian secara resmi ditetapkan berdasarkan Maklumat Pemerintah Daerah Istimewa Yogyakarta Nomor 5 Tahun 1948 tentang Perubahan Daerah-Daerah Kelurahan.\n\nBatas Wilayah :\n\nUtara : Kecamatan Mlati\nTimur : Kecamatan Gamping\nSelatan: Desa Sidoarum\nBarat : Desa Sidokarto, Kecamatan         Mlati\n\nNama Padukuhan :\n1	Simping\n2	Beluran\n3	Karanglo\n4	Dukuh\n5	Tegalan\n6	Karakan\n7	Krandon\n8	Pete\n9	Sawahan\n10	Ngrenak Kidul\n11	Ngrenak Lor', 'T', '0000-00-00 00:00:00', '0', '0', '', 'sidomoyo', 'sidomoyo');
INSERT INTO `desa` VALUES (2602, '184', 'Godean', '3404040003', 'Sidomulyo', '', '', 1, '3', 'Rustho Busono', '', '', '', '', '', '', '', '', 'T', '0000-00-00 00:00:00', '0', '0', '', 'sidomulyo', 'sidomulyo');
INSERT INTO `desa` VALUES (2603, '184', 'Godean', '3404040001', 'Sidorejo', '', '', 1, '10', 'Isharyanto', '', '', '', '', '', '', '', 'Desa Sidorejo \n\nSidorejo (Jawa: Sidareja) adalah desa di kecamatan Godean, Sleman, Daerah Istimewa Yogyakarta, Indonesia. Pada mulanya Desa Sidorejo merupakan wilayah yang terdiri dari 3 (tiga) Kelurahan yakni : Kelurahan Kwagon, Sangonan, dan Jering. Berdasarkan maklumat Pemerintah Daerah Istimewa Yogyakarta yang diterbitkan tahun 1946 mengenai Pemerintahan Kelurahan, maka Kelurahan-Kelurahan tersebut kemudian digabung menjadi satu desa otonom dengan nama Desa Sidorejo. Desa Sidorejo kemudian secara resmi ditetapkan berdasarkan Maklumat Pemerintah Daerah Istimewa Yogyakarta Nomor 5 Tahun 1948 tentang Perubahan Daerah-Daerah Kelurahan.\n\nDesa Sidorejo secara topografi berupa tanah datar, dan merupakan Desa terluas di Kecamatan Godean dengan luas 5,44 Km2 (sekitar 20% luas Kecamatan Godean). Desa ini sebagian besar merupakan kawasan pedesaan yang subur, dan memiliki potensi di bidang pertanian, peternakan dan industri genteng. Sebanyak 7.440 jiwa yang terbagi dalam 2.051 KK tinggal di 13 padukuhan yang ada di desa ini. Di Desa Sidorejo terdapat 259 KK Miskin (Raskin 2009) yang merupakan terendah di Kecamatan Godean.\n\nNama Padukuhan :\n1	Kwagon\n2	Pare Dukuh\n3	Pare Tengah\n4	Pare Kulon\n5	Bantut\n6	Jering VI\n7	Kleben\n8	Jering VIII\n9	Kliwonan\n10	Ganjuran\n11	Sangonan\n12	Kemirisewu\n13	Dongkelan', 'T', '0000-00-00 00:00:00', '0', '0', '', 'sidorejo', 'sidorejo');
