INSERT INTO `kecamatan` VALUES (1, 1, 345001, 'Koperasi Maju', 'Koperasi Jasa Mandiri dan Jujur', '', '', '', '', '', '', 'Sumberarum', 'AHU-00368.AH.02.01', 'Jl. Kebangkitan No 21', '085251637688', 'admin@siupkonline.com', 'demo.arthamari.com', 'demo.arthamari.com', 'Mudah-Cepat-Praktis-Akuntabel', '09:00', '14:00', '18', 12, '500', '2015-01-02', '2015-01-02', '01', '31', '0', '<ol><li>Fitur ini dapat anda gunakan untuk merubah, menambah dan menghapus redaksi SPK;</li><li>Redaksi yang dapat anda ubah, tambah dan hapus yaitu mulai dari Pasal 2 ayat 5, sedangkan selain itu merupakan redaksi standar dalam perjanjian yang memuat data pinjaman</li><li>Gunakan papan ketik dan icon yang tersedia selayaknya mengetik pada Microsoft Word;</li><li>Untuk membuat ayat baru, cukup tekan enter saja, tanpa menuliskan nomor karena akan otomatis membuat nomor sendiri pada dokumen SPK;</li><li>Redaksi tersebut disamping akan atomatis tercopy pada seluruh SPK pinjaman yang anda buat;</li></ol>', '', '', '', '', '', '5', '1', '1', '3', '1', '1', '1.png', '8', '1.jpg', 'Berawal dari Program Nasional Pemberdayaan Masyarakat (PNPM) Mandiri Perdesaan sebagai salah satu program pemerintah yang berorientasi pada peningkatan kualitas hidup masyarakat perdesaan, dalam beberapa tahun terakhir ini telah mampu menjadi ikon dari pembangunan partisipatif yang mengakar di kalangan masyarakat. Hal itu terbentuk karena besarnya kontribusi riil dari program ini terhadap pemberdayaan, peningkatan kualitas hidup dan pemenuhan kebutuhan dasar masyarakat perdesaan. <br><br> Mutlaknya keterlibatan masyarakat langsung dalam seluruh proseskegiatan PNPM ini yang dimulai dari kegiatan sosialisasi, penggalian gagasan,penetapan, pelaksanaan, dan pelestarian kegiatan, mengharuskan pula adanyaketerlibatan banyak pelaku sebagai pelaksana program, baik pelaku di tingkatdesa maupun pelaku program di tingkat kecamatan. Dan salah satu pelakuprogram tingkat kecamatan yang memiliki tugas dan tanggung jawab dalampengelolaan keuangan dan seluruh rangkaian kegiatan PNPM Mandiriperdesaan adalah Unit Pengelola Kegiatan (UPK).', 'https://www.facebook.com/upkonline', 'UPK Jatirogo, PNPM Mandiri Perdesaan, SI UPK Online, Aplikasi UPK Online, Aplikasi Bumdes bersama', 'UPK Jatirogo, PNPM Mandiri Perdesaan, SI UPK Online, Aplikasi UPK Online, Aplikasi Bumdes bersama', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3948.4822210560164!2d114.9616734881608!3d-8.254703632773051!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2dd183d0131edf25%3A0xf961582666c7e8a2!2sJl.+Amerta%2C+Busungbiu%2C+Kabupaten+Buleleng%2C+Bali+81154!5e0!3m2!1sid!2sid!4v1510720926705', 0, 'Manajer Umum', 'Sekretaris', 'Bendahara', 'camat1', '12345', '', 'AS Ransi', '1', '50', '2', '0', '0', '0.3', '0.1', '1250', '10', '', '', '0', '');
INSERT INTO `kecamatan` VALUES (96, 18, 1801, 'UPK', 'Unit Pengelola Kegiatan', 'BKAD', 'Badan Kerjasama Antar Desa', 'BP', 'Badan Pengawas', 'TV', 'Tim Verifikasi', 'Kebumen', '', 'Jalan Tentara Pelajar No 27 A Kebumen', '(0287)3871012', 'upkkeckebumen@yahoo.com', 'upk.dapmkebumen.com', 'kebumen.siupkonline.com', '<table border=\"1\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\" width=\"616\">\r\n<p align=\"center\"><strong>VISI</strong></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"616\">\r\n<p>Menjadi lembaga yang profesional dan akuntabel dalam peningkatan Ekonomi Masyarakat</p>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>\r\n<table border=\"1\" cellspacing=\"0\" cellpadding=\"0\">\r\n<tbody>\r\n<tr>\r\n<td valign=\"top\" width=\"616\">\r\n<p align=\"center\"><strong>MISI</strong></p>\r\n</td>\r\n</tr>\r\n<tr>\r\n<td valign=\"top\" width=\"616\"><ol>\r\n<li>Mengembangkan profesionalisme sumber daya manusia dalam pengelolaan kegiatan bagi kepentingan pemberdayaan masyarakatdan pengentasan kemiskinan</li>\r\n<li>Mengembangkan kegiatan ekonomi produktif dan peningkatan kualitas hidup masyarakat melalui pemberian manfaat nyata bagi &nbsp;Masyarakat kurang mampu</li>\r\n<li>Mengoptimalkan potensi daerah untuk kemakmuran rakyat.</li>\r\n<li>Memperluas jaringan social-ekonomi secara nasional maupun internasional, demi kesejahteraan rakyat</li>\r\n<li>Pemeberdayaan Lembaga Kemasyaraktan dan masyarakat desa sebagai perwujudan perekonomian yang berdaya saing tinggi</li>\r\n<li>Perwujudan tertib administrasi kelembagaan serta peningkatan kualitas pelayanan yang professional dan dinamis.</li>\r\n</ol>\r\n<p>&nbsp;</p>\r\n</td>\r\n</tr>\r\n</tbody>\r\n</table>', '07:30', '16:00', '1.5', 12, ' 500', '2017-03-01', '2016-12-01', '01', '31', 'M1', '', '', '', '', '', '', '3', '2', '', '3', '6', '2', '', '3', '96.JPG', 'Berawal dari Program Nasional Pemberdayaan Masyarakat (PNPM) Mandiri Perdesaan sebagai salah satu program pemerintah yang berorientasi pada peningkatan kualitas hidup masyarakat perdesaan, dalam beberapa tahun terakhir ini telah mampu menjadi ikon dari pembangunan partisipatif yang mengakar di kalangan masyarakat. Hal itu terbentuk karena besarnya kontribusi riil dari program ini terhadap pemberdayaan, peningkatan kualitas hidup dan pemenuhan kebutuhan dasar masyarakat perdesaan. <br><br> Mutlaknya keterlibatan masyarakat langsung dalam seluruh proseskegiatan PNPM ini yang dimulai dari kegiatan sosialisasi, penggalian gagasan,penetapan, pelaksanaan, dan pelestarian kegiatan, mengharuskan pula adanyaketerlibatan banyak pelaku sebagai pelaksana program, baik pelaku di tingkatdesa maupun pelaku program di tingkat kecamatan. Dan salah satu pelakuprogram tingkat kecamatan yang memiliki tugas dan tanggung jawab dalampengelolaan keuangan dan seluruh rangkaian kegiatan PNPM Mandiriperdesaan adalah Unit Pengelola Kegiatan (UPK).', 'https://www.facebook.com/upkonline', '', '', 'https://www.google.co.id/maps/place/UPK+Kecamatan+Kebumen/@-7.6733622,109.6696402,375m/data=!3m2!1e3!4b1!4m5!3m4!1s0x2e654b91ecff4cc7:0x65f36be6c9b67431!8m2!3d-7.6733649!4d109.6707345', 1500096, 'Ketua', 'Sekretaris', 'Bendahara', 'camat96', '12345', '', 'JKS Jaminan kesejahteraan sosial ', '0.75', '60', '1', '0', '0', '0', '0', '0', '', '', '', '0', '');
INSERT INTO `kecamatan` VALUES (97, 18, 1802, 'UPK', 'Unit Pengelola Kegiatan', 'BKAD', 'Badan Kerjasama Antar Desa', 'BP', 'Badan Pengawas', 'TV', 'Tim Verifikasi', 'Pejagoan', '', 'Jalan Kenanga No 48 A Pejagoan', '0287 382849', 'upk_pejagoan@yahoo.com', 'pejagoan.dapmkebumen.com', 'pejagoan.siupkonline.com', '', '08:00', '16:00', '1.25', 12, ' 500', '2017-01-01', '2017-01-01', '01', '31', '7', '<li>Apabila Pihak Kedua dan para pemberi kuasa membayar angsuran dalam jumlah dan waktu yang tidak disesuaikan dengan yang tertera pada jadwal angsuran, maka pembayaran akan diperhitungkan dengan urutan sebagai berikut : Pembayaran kewajiban bunga, pembayaran tunggakan pokok dan baru kemudian kewajiban pembayaran pokok untuk bulan yang berjalan ( denda sama dengan 2% kali dari tunggakan pokok dan bunga ).<br>', '', '', '', '', '', '2', '2', NULL, '2', '1', '4', '', '2', '', 'Berawal dari Program Nasional Pemberdayaan Masyarakat (PNPM) Mandiri Perdesaan sebagai salah satu program pemerintah yang berorientasi pada peningkatan kualitas hidup masyarakat perdesaan, dalam beberapa tahun terakhir ini telah mampu menjadi ikon dari pembangunan partisipatif yang mengakar di kalangan masyarakat. Hal itu terbentuk karena besarnya kontribusi riil dari program ini terhadap pemberdayaan, peningkatan kualitas hidup dan pemenuhan kebutuhan dasar masyarakat perdesaan. <br><br> Mutlaknya keterlibatan masyarakat langsung dalam seluruh proseskegiatan PNPM ini yang dimulai dari kegiatan sosialisasi, penggalian gagasan,penetapan, pelaksanaan, dan pelestarian kegiatan, mengharuskan pula adanyaketerlibatan banyak pelaku sebagai pelaksana program, baik pelaku di tingkatdesa maupun pelaku program di tingkat kecamatan. Dan salah satu pelakuprogram tingkat kecamatan yang memiliki tugas dan tanggung jawab dalampengelolaan keuangan dan seluruh rangkaian kegiatan PNPM Mandiriperdesaan adalah Unit Pengelola Kegiatan (UPK).', 'https://www.facebook.com/upkonline', '', '', '', 1500097, 'Ketua', 'Sekretaris', 'Bendahara', 'camat97', '12345', '', '', '', '', '', '0', '0', '0', '0', '0', '', '', '', '0', '');
INSERT INTO `kecamatan` VALUES (98, 18, 1803, 'UPK DB', 'Unit Pengelola Kegiatan Dana Bergulir', 'PPPM', 'PERKUMPULAN PENGELOLA PEMBERDAYAAN MASYARAKAT ', 'UPL', 'Unit Pengawas Lembaga', 'TV', 'Tim Verifikasi', 'Alian', 'AHU-0014746.AH.01.07.TAHUN 2018', 'Jalan Pemandian No. 70 Desa Krakal', '(0287) 3878083', 'upk_alian@yahoo.com', 'alian.dapmkebumen.com', 'alian.siupkonline.com', '<p style=\"text-align: center;\"><strong>VISI : </strong></p>\r\n<p style=\"text-align: center;\">Menciptakan Kemandirian Masyarakat Demi Terwujudnya Pembangunan dan Kesejahterahan di Kecamatan Alian.</p>\r\n<p style=\"text-align: center;\"><strong>MISI :</strong></p>\r\n<ol>\r\n<li style=\"text-align: center;\">Meningkatkan kapasitas masyarakat dan kelembagaannya;</li>\r\n<li style=\"text-align: center;\">Melestarikan hasil&ndash;hasil kegiatan PPK/PNPM Mandiri Perdesaan serta program lanjutan maupun &nbsp;program sejenis yang meliputi sistim, kelembagaan dan aset;</li>\r\n<li style=\"text-align: center;\">Meningkatkan kualitas dan kuantitas prasarana sarana sosial dasar dan ekonomi masyarakat;</li>\r\n<li style=\"text-align: center;\">Memperluas jaringan kemitraan dalam pembangunan;</li>\r\n<li style=\"text-align: center;\">Mempermudah akses modal usaha bagi kelompok masyarakat miskin</li>\r\n</ol>', '08:00', '15:00', '1.3', 12, ' 500', '2017-03-01', '2016-12-01', '01', '31', '0', '<li>Pihak Pertama akan memberikan Insentif Pengembalian Tepat Waktu (IPTW) sejumlah <b>20% dari jasa</b> yang telah dibayarkan kepada Pihak Kedua jika angsurannya tepat tanggal, tepat waktu dan tepat jumlah dalam satu periode angsuran yang telah disepakati.</li><li>Pihak\nPertama akan memberikan Reward sejumlah <b>10% dari jasa</b> yang telah dibayarkan kepada\nPihak Kedua sesuai\ndengan surat perjanjian pinjaman yang telah disepakati dengan syarat IPTW tidak bisa di berikan.</li><li>Apabila pihak kedua dan para pemberi kuasa membayar angsuran dalam jumlah dan waktu yang tidak sesuai pada jadwal angsuran (terlambat satu bulan) maka akan diberikan sanksi/denda sejumlah <b>0,5% per bulan </b>dan nama kelompok tersebut akan di umumkan di informasi kecamatan dan Desa se-Kecamatan Alian.</li><li>Apabila terjadi kemacetan pinjaman, maka semua anggota menanggung pembiayaan baik yang menyangkut biaya administrasi, pokok pinjaman, jasa pinjaman maupun sanksi/denda  dan apabila terjadi kemacetan suatu kelompok maka UPK tidak akan mencairkan dana perguliran lagi sampai dengan akad penyelesaian terhadap kelompok yang menunggak (tanggung renteng kelompok)</li><li>Penutupan pinjaman sebelum jatuh tempo dapat dilakukan hanya jika kelompok tersebut tidak pernah terlambat dalam angsuran dan angsuran minimal sudah mencapai setengah dari jadwal angsuran yang telah disepakati dengan cara memebayar semua pokok yang belum dibayar ditambah satu bulan jasa di depan. ', '', '', '', '', '', '2', '2', NULL, '3', '1', '2', '98.jpg', '5', '', 'Berawal dari Program Nasional Pemberdayaan Masyarakat (PNPM) Mandiri Perdesaan sebagai salah satu program pemerintah yang berorientasi pada peningkatan kualitas hidup masyarakat perdesaan, dalam beberapa tahun terakhir ini telah mampu menjadi ikon dari pembangunan partisipatif yang mengakar di kalangan masyarakat. Hal itu terbentuk karena besarnya kontribusi riil dari program ini terhadap pemberdayaan, peningkatan kualitas hidup dan pemenuhan kebutuhan dasar masyarakat perdesaan. <br><br> Mutlaknya keterlibatan masyarakat langsung dalam seluruh proseskegiatan PNPM ini yang dimulai dari kegiatan sosialisasi, penggalian gagasan,penetapan, pelaksanaan, dan pelestarian kegiatan, mengharuskan pula adanyaketerlibatan banyak pelaku sebagai pelaksana program, baik pelaku di tingkatdesa maupun pelaku program di tingkat kecamatan. Dan salah satu pelakuprogram tingkat kecamatan yang memiliki tugas dan tanggung jawab dalampengelolaan keuangan dan seluruh rangkaian kegiatan PNPM Mandiriperdesaan adalah Unit Pengelola Kegiatan (UPK).', 'https://www.facebook.com/upkonline', '', '', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d988.6612176694331!2d109.69722070710776!3d-7.6135661196490965!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x0%3A0xb2082992ac47a1!2sUPK+BINA+SEJAHTERA!5e0!3m2!1sid!2sid!4v1489592676187', 1500098, 'Ketua', 'Sekretaris', 'Bendahara', 'camat98', '12345', '', '', '', '', '1', '0', '0', '0', '0', '0', '', '', '', '0', '');
INSERT INTO `kecamatan` VALUES (102, 18, 1804, 'UPK ', 'Unit Pengelola Kegiatan', 'BKAD', 'Badan Kerjasama Antar Desa', 'TP', 'Tim Pengawas', 'TV', 'Tim Verifikasi', 'Adimulyo', '', 'Jalan Kaleng No 21 Desa Kemujan Kecamatan Adimulyo Kode Pos 54363', '081328794110 ', 'upk_adimulyo@yahoo.com', 'adimulyo.dapmkebumen.com', 'adimulyo.siupkonline.com', '', '08:00', '16:00', '1.333333', 12, ' 100', '2017-03-01', '2017-03-01', '01', '31', '0', '<li>Atas kredit tersebut dikenakan denda apabila terjadi tunggakan pinjaman (jumlah angsurannya kurang dari jumlah angsuran yang telah ditetapkan atau melebihi batas jatuh tempo angsuran). Denda yang dikenakan sebesar 2% per bulan dari jumlah tunggakan.</li><li>Apabila pihak kedua dan para pemberi kuasa membayar angsuran dalam waktu tidak sesuai dengan yang tertera pada jadwal angsuran, maka pembayaran akan diperhitungkan dengan urutan sebagai berikut : pembayaran kewajiban jasa, pembayaran denda, pembayaran tunggakan pokok dan kemudian kewajiban pembayaran pokok untuk bulan yang berjalan.</li><li>Apabila pihak kedua dan para pemberi kuasa membayar angsuran sesuai dengan jumlah angsuran dan jadwal angsuran (tidak terjadi tunggakan) sampai pelunasan pinjaman maka akan mendapat Insentif Pengembalian Tepat waktu (IPTW) sebesar 15% dari jasa pinjaman. Bagi kelompok yang pinjamannya terjadi tunggakan maka tidak mendapatkan IPTW.</li>', '', '', '', '', '', '3', '2', NULL, '1', '3', '4', '', '5', '', 'Berawal dari Program Nasional Pemberdayaan Masyarakat (PNPM) Mandiri Perdesaan sebagai salah satu program pemerintah yang berorientasi pada peningkatan kualitas hidup masyarakat perdesaan, dalam beberapa tahun terakhir ini telah mampu menjadi ikon dari pembangunan partisipatif yang mengakar di kalangan masyarakat. Hal itu terbentuk karena besarnya kontribusi riil dari program ini terhadap pemberdayaan, peningkatan kualitas hidup dan pemenuhan kebutuhan dasar masyarakat perdesaan. <br><br> Mutlaknya keterlibatan masyarakat langsung dalam seluruh proseskegiatan PNPM ini yang dimulai dari kegiatan sosialisasi, penggalian gagasan,penetapan, pelaksanaan, dan pelestarian kegiatan, mengharuskan pula adanyaketerlibatan banyak pelaku sebagai pelaksana program, baik pelaku di tingkatdesa maupun pelaku program di tingkat kecamatan. Dan salah satu pelakuprogram tingkat kecamatan yang memiliki tugas dan tanggung jawab dalampengelolaan keuangan dan seluruh rangkaian kegiatan PNPM Mandiriperdesaan adalah Unit Pengelola Kegiatan (UPK).', 'https://www.facebook.com/upkonline', '', '', '<iframe src=\"https://www.google.com/maps/embed?pb=!1m0!3m2!1sid!2sid!4v1489984691819!6m8!1m7!1sa6EU3swtBlrFrzMp3pljCg!2m2!1d-7.6657582437871!2d109.5549324178065!3f319.9419920685482!4f-13.475961276591804!5f0.7820865974627469\" width=\"600\" height=\"450\" frameborder=\"0\" style=\"border:0\" allowfullscreen></iframe>', 1500102, 'Ketua', 'Sekretaris', 'Bendahara', 'camat102', '12345', '', '', '', '', '', '0', '0', '0', '0', '0', '', '', '', '0', '');
INSERT INTO `kecamatan` VALUES (107, 18, 1805, 'UPK DAPM', 'UPK DAPM', 'BKAD', 'Badan Kerjasama Antar Desa', 'BP', 'Badan Pengawas', 'TV', 'Tim Verifikasi', 'Rowokele', '', 'Jl. Raya Kebumen Banyumas RT 005 RW 002  Jatiluhur Rowokele', '(0287) 6642421', 'upknew_rowokele@yahoo.com', 'rowokele.dapmkebumen.com', 'rowokele.siupkonline.com', 'Mandiri dan Terpercaya', '08:00', '16:00', '1.5', 12, ' 500', '2017-03-01', '2017-03-01', '01', '31', '3', '<li>Apabila terdapat kekurangan/tunggakan angsuran maka pihak kedua dan para pemberi kuasa sanggup untuk menyerahkan barang berharga miliknya kepada Pemerintah Desa untuk dilelang dan diuangkan guna melunasi hutang pinjaman yang ada di Unit Pengelola kegiatan (UPK) Kecamatan Rowokele. Adapun mekanisme lelang diserahkan sepenuhnya kepada Pemerintah Desa.<br></li>', '', '', '', '', '', '2', '1', '2', '3', '6', '4', '', '2', '107.jpg', 'Berawal dari Program Nasional Pemberdayaan Masyarakat (PNPM) Mandiri Perdesaan sebagai salah satu program pemerintah yang berorientasi pada peningkatan kualitas hidup masyarakat perdesaan, dalam beberapa tahun terakhir ini telah mampu menjadi ikon dari pembangunan partisipatif yang mengakar di kalangan masyarakat. Hal itu terbentuk karena besarnya kontribusi riil dari program ini terhadap pemberdayaan, peningkatan kualitas hidup dan pemenuhan kebutuhan dasar masyarakat perdesaan. <br><br> Mutlaknya keterlibatan masyarakat langsung dalam seluruh proseskegiatan PNPM ini yang dimulai dari kegiatan sosialisasi, penggalian gagasan,penetapan, pelaksanaan, dan pelestarian kegiatan, mengharuskan pula adanyaketerlibatan banyak pelaku sebagai pelaksana program, baik pelaku di tingkatdesa maupun pelaku program di tingkat kecamatan. Dan salah satu pelakuprogram tingkat kecamatan yang memiliki tugas dan tanggung jawab dalampengelolaan keuangan dan seluruh rangkaian kegiatan PNPM Mandiriperdesaan adalah Unit Pengelola Kegiatan (UPK).', 'https://www.facebook.com/upkonline', '', '', 'www.google.co.id/maps/@-7.6029099,109.4424357,3a,60y,90t/data=!3m6!1e1!3m4!1sTEmSzP6GrC2EU1QyAalx6g!2e0!7i13312!8i6656', 1500107, 'Manajer UPK', 'Sekretaris UPK', 'Keuangan UPK', 'camat107', '12345', '', 'JKN', '1', '70', '2', '0', '0', '0', '0', '0', '', '', '', '0', '');
