INSERT INTO `kecamatan` VALUES (194, 18, 194, 'UPK', 'Unit Pengelola Kegiatan', 'BKAD', 'Badan Kerjasama Antar Desa', 'BP', 'Badan Pengawas', 'TV', 'Tim Verifikasi', 'Poncowarno', '', 'Jalan Raya Poncowarno Km1', '085292027169', 'upk_poncowarno@yahoo.com', '', 'poncowarno.siupkonline.com', 'undefined', '08:00', '15:00', '1.25', 12, ' 500', '2018-07-01', '2018-07-01', '01', '31', '0', '<li>Apabila Pihak Kedua dan para Pemberi kuasa membayar angsuran dalam  jumlah dan waktu yang tidak sesuai dengan yang tertera pada jadwal angsuran,  maka dikenakan denda sesuai dengan ketentuan di UPK.</li>', '', '', '', '', '', '2', '1', '1', '2', '2', '1', '', '1', '', '<p>Berawal dari Program Nasional Pemberdayaan Masyarakat (PNPM) Mandiri Perdesaan sebagai salah satu program pemerintah yang berorientasi pada peningkatan kualitas hidup masyarakat perdesaan, dalam beberapa tahun terakhir ini telah mampu menjadi ikon dari pembangunan partisipatif yang mengakar di kalangan masyarakat. Hal itu terbentuk karena besarnya kontribusi riil dari program ini terhadap pemberdayaan, peningkatan kualitas hidup dan pemenuhan kebutuhan dasar masyarakat perdesaan. <br /><br /> Mutlaknya keterlibatan masyarakat langsung dalam seluruh proseskegiatan PNPM ini yang dimulai dari kegiatan sosialisasi, penggalian gagasan,penetapan, pelaksanaan, dan pelestarian kegiatan, mengharuskan pula adanyaketerlibatan banyak pelaku sebagai pelaksana program, baik pelaku di tingkatdesa maupun pelaku program di tingkat kecamatan. Dan salah satu pelakuprogram tingkat kecamatan yang memiliki tugas dan tanggung jawab dalampengelolaan keuangan dan seluruh rangkaian kegiatan PNPM Mandiriperdesaan adalah Unit Pengelola Kegiatan (UPK).</p>', 'http://facebook.com/upkonline, http://twitter.com', '', '', 'https://goo.gl/maps/EUAbB6iCaiu', 1500194, 'Ketua', 'Sekretaris', 'Bendahara', 'camat194', '2018', '', '', '', '', '', '0', '0', '0', '0', '0', '', '', '', '0', '');
INSERT INTO `kecamatan` VALUES (195, 18, 195, 'UPK', 'Unit Pengelola Kegiatan', 'BKAD', 'Badan Kerjasama Antar Desa', 'BP', 'Badan Pengawas', 'TV', 'Tim Verifikasi', 'Buayan', '-', 'Jl Karangbolong Km 10 Buayan', '087732517888', 'upk_buayan@yahoo.com', 'buayan.dapmkebumen.com', 'buayan.siupkonline.com', '<p>Masyarkat Mandiri dan Sejahtera dengan Mengoptimalkan Potensi Lokal</p>', '08:00', '16:00', '1.25', 18, '-500', '2018-04-01', '2018-04-01', '01', '31', '0', '<li>Apabila Pihak Kedua dan para Pemberi kuasa membayar angsuran dalam  jumlah dan waktu yang tidak sesuai dengan yang tertera pada jadwal angsuran,  maka dikenakan denda sesuai dengan ketentuan di UPK.</li>', '', '', '', '', '', '2', '1', NULL, '3', '1', '4', '195.png', '2', '', '<p>Dengan berlakunya UU Nomer 6 Tahun 2016 dan Surat Edaran dari Menteri Desa Pembangunan Daerah Tertinggal dan Transmigrasi Nomer : 134/DPPMD/VII/2015 Tanggal 20 Oktober 2015 Tentang Pengakhiran Serta Penataan Dan Pengalihan Kepemilikan Aset Hasil Kegiatan Program Nasional Pemberdayaan Masyarakat Mandiri Perdesaan &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;( PNPM MPd). Berakhirnya PNPM Mandiri Perdesaan, Unit Pengelola Kegiatan sebagai pengelola dana bergulir.&nbsp;&nbsp; Unit Pengelola Kegiatan mempunyai tantangan tersendiri didalam mempertahankan eksistensinya (keberadaan) dana bergulir, untuk tetap eksis ditengah-tengah masyarakat yang selama ini menjadi pemanfaat dari dana bergulir.</p>\r\n<p>Unit Pengelola Kegiatan Dana Bergulir menawarkan solusi peningkatan ekonomi masyarakat dengan penguatan modal usaha kelompok masyarakat berdasarkan kearifan lokal yang tertuang dalam permakades yang ditetapkan pada Tanggal 20 Maret 2015. Berbekal dengan keyakinan inilah maka UPK Dana Bergulir hadir di tengah-tengah kita. Dengan motto &lsquo;Masyarakat Mandiri dan Sejahtera Dengan Mengotimalkan Potensi Lokal&rsquo; membekali masyarakat, tiga hal penting yaitu moralitas, ketrampilan dan pengembangan usaha.</p>\r\n<p>Unit Pengelola Kegiatan (UPK) lahir berawal atas adanya Program Pengembangan Kecamatan (PPK) di Kecamatan Buayan pada tanggal 27 November 2003.&nbsp; UPK Dan Berglir lahir sebagai pengelola dan penyalur seluruh dana bergulir di tingkat kecamatan.&nbsp; Dalam perkembangannya UPK Dana Bergulir terus berbenah diri dalam rangka kemandirian untuk pelayanan dan pembinaan masyarakat khususnya yang telah bergabung dalam kelompok pemanfaat dana bergulir, sekaligus akan membangun jaringan kerja sama dengan pihak lain.</p>\r\n<p>Kegiatan UPK dalam upaya menegakkan komitmennya, menitik beratkan pada :</p>\r\n<ol start=\"1\">\r\n<li>Pemberdayaan ekonomi masyarakat melalui simpan pinjam dana bergulir ( SPP dan UEP )</li>\r\n<li>Pembinaan usaha melalui model kelompok tanggung renteng untuk peningkatan dan pengembangan usaha sekala mikro yang dikembangkan masyarakat, agar memiliki kinerja yang semakin baik menuju usaha yang kokoh dan mantap.</li>\r\n<li>Pelatihan pengelola UPK untuk peningkatan kompetensi pengelola UPK.</li>\r\n</ol>\r\n<p>Kegiatan Sosial Kemasarakatan</p>\r\n<ol>\r\n<li>Bantuan alat usaha &nbsp;: Meningkatkan pemerataan dan kesempatan pengembangan usaha, Memberikan dorongan dan semangat untuk meningkatkan pendapatan.</li>\r\n</ol><ol start=\"2\">\r\n<li>Memberikan bantuan untuk korban bencana alam, sosial kemasyarakatan, sosial keagamaan, uang duka / musibah bagi kelompok dan kelembagaan BKAD.</li>\r\n<li>Bantuan sembako gratis : Bantuan sembako gratis diberikan kepada janda dan anak yatim piatu</li>\r\n</ol>', 'http://facebook.com/upkonline, http://twitter.com', '', '', '', 1500195, 'Manajer', 'Administrasi', 'Pembukuan', 'camat195', '2018', '', '', '', '', '', '0', '0', '0', '0', '0', '', '', '', '0', '');
INSERT INTO `kecamatan` VALUES (193, 18, 193, 'USPK', 'Unit Simpan Pinjam Kelompok', 'Bumdesma', 'BUMDESMA', 'DP', 'Dewan Pengawas', 'TV', 'Tim Verifikasi', 'Kuwarasan', '', 'Jl. Puring Km. 6,5 No. 8 Kuwarasan ', '085385331666', 'upk_kuwarasan@yahoo.com', 'kuwarasan.dapmkebumen.com', 'kuwarasan.siupkonline.com', 'Mitra Setia Perekonomian Masyarakat', '08:00', '16:00', '1.5', 12, '-500', '2018-04-01', '2018-04-01', '01', '31', '0', '<li>Apabila Pihak Kedua dan para Pemberi kuasa membayar angsuran dalam  jumlah dan waktu yang tidak sesuai dengan yang tertera pada jadwal angsuran,  maka dikenakan denda sesuai dengan ketentuan di UPK.</li><br>', '', '', '', '', '', '2', '2', '1', '2', '2', '2', '193.jpg', '7', '193.jpg', 'Berawal dari Program Nasional Pemberdayaan Masyarakat (PNPM) Mandiri Perdesaan sebagai salah satu program pemerintah yang berorientasi pada peningkatan kualitas hidup masyarakat perdesaan, dalam beberapa tahun terakhir ini telah mampu menjadi ikon dari pembangunan partisipatif yang mengakar di kalangan masyarakat. Hal itu terbentuk karena besarnya kontribusi riil dari program ini terhadap pemberdayaan, peningkatan kualitas hidup dan pemenuhan kebutuhan dasar masyarakat perdesaan. <br><br> Mutlaknya keterlibatan masyarakat langsung dalam seluruh proseskegiatan PNPM ini yang dimulai dari kegiatan sosialisasi, penggalian gagasan,penetapan, pelaksanaan, dan pelestarian kegiatan, mengharuskan pula adanyaketerlibatan banyak pelaku sebagai pelaksana program, baik pelaku di tingkatdesa maupun pelaku program di tingkat kecamatan. Dan salah satu pelakuprogram tingkat kecamatan yang memiliki tugas dan tanggung jawab dalampengelolaan keuangan dan seluruh rangkaian kegiatan PNPM Mandiriperdesaan adalah Unit Pengelola Kegiatan (UPK).', 'http://facebook.com/upkonline, http://twitter.com', '', '', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3954.1669584139113!2d109.50655211404764!3d-7.66519227798183!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x2e654a70869f8015%3A0x999a6468c8f0d58c!2sBKAD-UPK+KUWARASAN!5e0!3m2!1sid!2sid!4v1525397133095', 1500193, 'Ketua', 'Sekretaris', 'Bendahara', 'camat193', '2018', '', '', '', '', '', '0', '0', '0', '0', '0', '', '', '', '0', '');
INSERT INTO `kecamatan` VALUES (210, 18, 210, 'UPK', 'Unit Pengelola Kegiatan', 'BKAD', 'Badan Kerjasama Antar Desa', 'BP', 'Badan Pengawas', 'TV', 'Tim Verifikasi', 'Kutowinangun', '', 'Jl. Raya Barat No. 10B RT 01 RW 01 Desa Kaliputih', '087737821444', 'Pnpm_kutowinangun@yahoo.com', 'kutowinangun.dapmkebumen.com', 'kutowinangun.siupkonline.com', '', '08:00', '16:00', '1.4', 12, '500', '2018-08-01', '2018-07-01', '01', '31', '3', '<li> Apabila Pihak Kedua dan para pemberi kuasa membayar angsuran dalam jumlah dan waktu yang tidak sesuai dengan yang tertera pada jadwal angsuran Maksimal 3 hari setelah tanggal jatuh tempo, maka pembayaran akan diperhitungkan dengan urutan sebagai berikut : pembayaran kewajiban jasa, pembayaran tunggakan pokok dan baru kemudian kewajiban pembayaran pokok untuk bulan berjalan, denda 1.5% dari tunggakan pokok dan jasa. </li>\n<li>Apabila Pihak Kedua dan para pemberi kuasa membayar angsuran dalam jumlah dan waktu sesuai dengan yang tertera pada jadwal angsuran Maksimal 3 hari setelah tanggal jatuh tempo, maka kelompok akan mendapatkan Insentif Pengembalian Tepat Waktu (IPTW) pada akhir periode jangka waktu pinjaman dengan jumlah prosentase sebesar 8% dari jumlah jasa yang dibayarkan dikalikan dengan jangka waktu pinjaman.</li>', '', '', '', '', '', '2', '1', '1', '2', '6', '3', '', '3', '', 'Berawal dari Program Nasional Pemberdayaan Masyarakat (PNPM) Mandiri Perdesaan sebagai salah satu program pemerintah yang berorientasi pada peningkatan kualitas hidup masyarakat perdesaan, dalam beberapa tahun terakhir ini telah mampu menjadi ikon dari pembangunan partisipatif yang mengakar di kalangan masyarakat. Hal itu terbentuk karena besarnya kontribusi riil dari program ini terhadap pemberdayaan, peningkatan kualitas hidup dan pemenuhan kebutuhan dasar masyarakat perdesaan. <br><br> Mutlaknya keterlibatan masyarakat langsung dalam seluruh proseskegiatan PNPM ini yang dimulai dari kegiatan sosialisasi, penggalian gagasan,penetapan, pelaksanaan, dan pelestarian kegiatan, mengharuskan pula adanyaketerlibatan banyak pelaku sebagai pelaksana program, baik pelaku di tingkatdesa maupun pelaku program di tingkat kecamatan. Dan salah satu pelakuprogram tingkat kecamatan yang memiliki tugas dan tanggung jawab dalampengelolaan keuangan dan seluruh rangkaian kegiatan PNPM Mandiriperdesaan adalah Unit Pengelola Kegiatan (UPK).', '', '', '', '', 1500210, 'Ketua', 'Sekretaris', 'Bendahara', '18210', '2018', '', '', '', '', '', '0', '0', '0', '0', '0', '', '', '', '0', '');
INSERT INTO `kecamatan` VALUES (214, 18, 214, 'UPK', 'Unit Pengelola Kegiatan', 'BKAD', 'Badan Kerjasama Antar Desa', 'BP', 'Badan Pengawas', 'TV', 'Tim Verifikasi', 'Gombong', '', 'Jl. Kawedanan NO.6 Gombong', '08179546306', 'upk_gombong@yahoo.com', 'gombong.dapmkebumen.com', 'gombong.siupkonline.com', '', '08:00', '16:00', '1.5', 12, '-500', '2018-10-01', '2018-10-01', '01', '31', '0', '', '', '', '', '', '', '2', '1', '1', '2', '3', '4', '', '3', '', 'Berawal dari Program Nasional Pemberdayaan Masyarakat (PNPM) Mandiri Perdesaan sebagai salah satu program pemerintah yang berorientasi pada peningkatan kualitas hidup masyarakat perdesaan, dalam beberapa tahun terakhir ini telah mampu menjadi ikon dari pembangunan partisipatif yang mengakar di kalangan masyarakat. Hal itu terbentuk karena besarnya kontribusi riil dari program ini terhadap pemberdayaan, peningkatan kualitas hidup dan pemenuhan kebutuhan dasar masyarakat perdesaan. <br><br> Mutlaknya keterlibatan masyarakat langsung dalam seluruh proseskegiatan PNPM ini yang dimulai dari kegiatan sosialisasi, penggalian gagasan,penetapan, pelaksanaan, dan pelestarian kegiatan, mengharuskan pula adanyaketerlibatan banyak pelaku sebagai pelaksana program, baik pelaku di tingkatdesa maupun pelaku program di tingkat kecamatan. Dan salah satu pelakuprogram tingkat kecamatan yang memiliki tugas dan tanggung jawab dalampengelolaan keuangan dan seluruh rangkaian kegiatan PNPM Mandiriperdesaan adalah Unit Pengelola Kegiatan (UPK).', '', '', '', 'Kecamatan Gombong, Jalan Kawedanan, Gombong, Kabupaten Kebumen, Jawa Tengah', 1500214, 'Ketua', 'Sekretaris', 'Bendahara', '', '', '', '', '', '', '', '0', '0', '0', '0', '0', '', '', '', '0', '');
INSERT INTO `kecamatan` VALUES (215, 18, 215, 'UPK', 'Unit Pengelola Kegiatan', 'BKAD', 'Badan Kerjasama Antar Desa', 'BP', 'Badan Pengawas', 'TV', 'Tim Verifikasi', 'Ayah', '', 'Jl. Raya Demangsari km 2,7 Desa Candirenggo', '082 135 492929', 'UPK_ayah@yahoo.com', 'ayah.dapmkebumen.com', 'ayah.siupkonline.com', 'Tercapainya Kesejahteraan dan Kemandirian Masyarakat Miskin Pedesaan', '08:00', '16:00', '1.4', 12, ' 500', '2018-10-01', '2019-05-31', '01', '31', '3', '<div>Apabila pihak kedua menunggak maka akan dikenakan denda sebesar 2% x dari tunggakan angsuran dan jika tepat waktu sampai lunas maka Pihak Pertama akan memberikan IPTW (Insentif Pengembalian Tepat Waktu) sebesar 10 % dari total jasa yang dibayarkan.</div><br>', '', '', '', '', '', '2', '3', '2', '2', '1', '4', '', '5', '', 'Berawal dari Program Nasional Pemberdayaan Masyarakat (PNPM) Mandiri Perdesaan sebagai salah satu program pemerintah yang berorientasi pada peningkatan kualitas hidup masyarakat perdesaan, dalam beberapa tahun terakhir ini telah mampu menjadi ikon dari pembangunan partisipatif yang mengakar di kalangan masyarakat. Hal itu terbentuk karena besarnya kontribusi riil dari program ini terhadap pemberdayaan, peningkatan kualitas hidup dan pemenuhan kebutuhan dasar masyarakat perdesaan. <br><br> Mutlaknya keterlibatan masyarakat langsung dalam seluruh proseskegiatan PNPM ini yang dimulai dari kegiatan sosialisasi, penggalian gagasan,penetapan, pelaksanaan, dan pelestarian kegiatan, mengharuskan pula adanyaketerlibatan banyak pelaku sebagai pelaksana program, baik pelaku di tingkatdesa maupun pelaku program di tingkat kecamatan. Dan salah satu pelakuprogram tingkat kecamatan yang memiliki tugas dan tanggung jawab dalampengelolaan keuangan dan seluruh rangkaian kegiatan PNPM Mandiriperdesaan adalah Unit Pengelola Kegiatan (UPK).', '', '', '', '', 1500215, 'Ketua', 'Sekretaris', 'Bendahara', '', '', '', '', '', '', '', '0', '0', '0', '0', '0', '', '', '', '0', '');
