INSERT INTO `news` VALUES (1, '2015-10-30 07:24:10', 'Musyawarah Khusus Kepala Desa', 'Musyawarah Khusus Kepala Desa.jpg', 'Menyikapi tentang Pengakhiran, Penataan Aset&nbsp;Program PNPM-MPd dan Penyelerasana Kelembagaan BKAD, maka mengambil inisiatif untuk melaksanakan Musyawarah Khusu untuk membahas hal tersebut.<br>Hasil pertemuan tersebut adalah :<br>1. Semua Kepala Desa yang ada di Kec. Tompobulu sepakat untuk bekerjasama dalam bidang Pemberdayaan, Pembangunan partisifatif dan Ktertiban dan Keamanan.<br>2. Aset PNPM-MPd SPP Dana Bergulir sebagai aset abadi masyarakat Kec. Tompobulu akan dilestarikan secara bersama dalam bentuk Koperasi Kecamatan.', 2, 1, 'P');
INSERT INTO `news` VALUES (3, '2015-12-19 19:58:39', 'BIMTEK TUTUP BUKU UPK SE-KABUPATEN BANTAENG DAN SOSIALISASI APLIKASI SIUPKONLINE', 'BIMTEK TUTUP BUKU UPK SE-KABUPATEN BANTAENG DAN SOSIALISASI APLIKASI SIUPKONLINE.jpg', 'Pada tanggal, 16 - 17 Desember 2015 bertempat di Hotel Ahriani Bantaeng telah dilaksanakan Bimbingan Teknis Laporan Tutup Buku bagi pengurus Unit Pengelola Kegiatan UPK se-Kab. Bantaeng<br>Kegiatan Bimtek ini di laksanakan oleh Satker Kabupaten PMD Bidang Ekonomi Pembangunan yang dihadiri oleh seluruh pengurus UPK dari 7 Kecamatan.<br>Narasumber dari kegiatan tersebut ialah Tenaga Ahli Pendamping Desa yang dulunya disebut FasKeu, FasPPU dan FK pada saat PNPM-MPd belum berakhir. <br>Pada akhir kegiatan, dilakukan Sosialisasi Pengelolaan UPK Berbasis Online yang dibawakan oleh Ketua UPK Kec. Tompobulu saudara LUKMAN, yang mencoba mesimulasikan akun Demo yang dimiliki oleh UPK Kec. Tompobulu <a rel=\"nofollow\" target=\"_blank\" href=\"http://tompobulu.siupkonline.com\">http://tompobulu.siupkonline.com/</a> <br>', 2, 1, 'P');
INSERT INTO `news` VALUES (4, '2015-12-21 12:47:45', 'PROPIL UPK TOMPOBULU', 'PROPIL UPK TOMPOBULU.png', '<h3>\r\n<b>VISI MISI UPK KEC. TOMPOBULU KAB. BANTAENG</b>\r\n</h3><b>VISI\r\n&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\n</b>\r\n<div>\r\n<i>Terwujudnya Kelembagaan UPK Micro\r\nyang Mandiri dan Profesional Melalui peningkatan Pemberdayaan Masyarakat</i><span><br><br></span><b>MISI&nbsp;&nbsp; &nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; </b><br>- Meningkatkan Potensi\r\nkelompok melalui penguatan kelembagaan.</div>\r\n<div>- Meningkatkan usaha perekonomian masyarkat melalui pelayanan\r\nsimpan pinjam.</div>\r\n<div>- <span>Menjadi mitra usaha\r\nkelompok Perempuan dan kelompok usaha Ekonomi produktif.<br></span><span><br><b>Alamat&nbsp; Jl. Pendidikan No.&nbsp;&nbsp;&nbsp;&nbsp; Banyorang Kec.Tompobulu</b></span>\r\n</div><div>\r\n<b>Berdiri Pada Tahun 2003</b></div>\r\n<div>\r\n<br><b></b></div>Kecamatan\r\nTompobulu Kabupten Bantaeng, merupakan salah satu kecamatan yang ada di\r\nPropinsi Sulawesi Selatan yang terdiri dari 10 Desa/Kelurahan, dengan jumlah\r\npenduduk 25.264 jiwa, 5.731 KK. Sebanyak 1.870 KK dikategorikan keluarga\r\nmiskin. Mata pencaharian masyarakatnya mayoritas adalah petani, dan potensi\r\nsumber daya alam yang potensial adalah Pertanian dan perekebunan. Adapun produk\r\nunggulannya adalah kakao (coklat) dan Cengkeh.\r\n<div>\r\nKecamatan ini terletak diarah utara dari ibu kota\r\nkabupaten dan sebelah selatan dari arah ibu kota propinsi sulawesi selatan (Sub\r\nRegion Selatan-selatan) dapat dijangkau dengan jalan darat darat dari ibu kota\r\npropinsi selama kurang lebih 3 jam, Kecamatan ini&nbsp; telah berpartisipasi dalam PPK sejak tahun\r\n2003 dan sampai saat&nbsp; ini telah mendapat\r\nalokasi BLM PPK II (siklus 4/5/6) dan PPK III (siklus 9/10). Memasuki Tahun anggaran\r\n2008 kecamatan ini masih berpartisipasi pada PNPM PPK</div>\r\n<div>\r\nBahwa seiring dengan\r\nperjalanan waktu, dimana keberadaan PNPM di Kecamatan Tompobulu yang sebelumnya\r\nbernama PPK dan PPK-PNPM, merupakan salah satu program untuk mempercepat\r\npenanggulangan kemiskiminan dinilai telah membawa dampak positif dan manfaat bagi\r\nmasyarakat. Realitas ini tidak dapat dipungkiri karena PNPM Mandiri Perdesaan\r\ndan PNPM Agribisnis Perdesaan telah melakukan perubahan yang sangat strategis\r\nbaik dalam wujud peningkatan Kapasitas Masyarakat dan pemerataan pembangunan,\r\nmaupun upaya peningkatan ekonomi kerakyatan dalam bentuk bantuan kredit lunak\r\nkepada segenap kelompok usaha produktif bagi kaum perempuan berupa Simpan\r\nPinjam (SPP/UEP). Pada prinsipnya bahwa kaidah-kaidah yang terkandung\r\ndidalamnya&nbsp; telah memberikan harapan yang\r\ncukup besar kedepan bagi seluruh masyarakat, oleh karenanya kita semua tentu\r\nsepakat bahwa PNPM Mandiri Perdesaan ini masih sangat diharapkan\r\nkeberlajutannya. Kenyatan ini tidak dapat dipungkiri bahwa untuk mengawal\r\nkelestrian dan keberlanjutan program ini dimana Unit Pengelola Kegiatan (UPK)\r\nmempunyai posisi central yang cukup strategis sebagai lokomotif&nbsp; pelaksanaan kegiatan di tingkat kecamatan.</div>\r\n<div>\r\nPengurus Unit\r\nPengelola Kegiatan (UPK) Kec. Tompobulu dalam menjalankan tugas dan fungsinya\r\ndibentuk sejak adanya Program Pengembangan Kecamatan (PPK) dan sekarang menjadi\r\nProgram Nasional Pemberdayaan Masyarakat mandiri Perdesaan (PNPM-MP), yang\r\nterdiri dari beberapa ungsur yaitu BKAD, BP-UPK dan UPK itu sendiri, dan setiap\r\nperiode terkadang ada perubahan persenil pengurus disebabkan kesibukan dan\r\nkesanggupan masing-masing personil.</div>\r\n<div>\r\n<b>Pengurus MAD periode\r\n2003 s/d 2005</b></div>\r\n<div>\r\nKetua&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; :\r\nSirajuddin, S.Ag</div>\r\n<div>\r\nSekretaris&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : Abdul Mannan, S.Ag</div>\r\n<div>\r\n<br></div>\r\n<div>\r\n<b>Pengurus&nbsp;&nbsp; BKAD\r\nPeriode 2005 s/d 2007</b></div>\r\n<div>\r\nKetua&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; :\r\nAbdul Mannan, S.ag</div>\r\n<div>\r\nSekretaris&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : Jarifuddin, S.Pd.I</div>\r\n<div>\r\nBendahara&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : St. NiÃ¢â‚¬â„¢mah, S.Ag</div>\r\n<div>\r\n<br></div>\r\n<div>\r\n<b>Pengurus&nbsp;&nbsp; BKAD\r\nPeriode 2008 s/d 2009</b></div>\r\n<div>\r\nKetua&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; :\r\nAbdul Mannan, S.ag</div>\r\n<div>\r\nSekretaris&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : Muh. Asri</div>\r\n<div>\r\nBendahara&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : St. NiÃ¢â‚¬â„¢mah, S.Ag</div>\r\n<div>\r\n<br></div>\r\n<div>\r\n<b>Pengurus&nbsp;&nbsp; BKAD\r\nPeriode 2009 s/d 2010</b></div>\r\n<div>\r\nKetua&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; :\r\nAbdul Mannan, S.ag</div>\r\n<div>\r\nSekretaris&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : Haerul MaÃ¢â‚¬â„¢ruf</div>\r\n<div>\r\nBendahara&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : St. NiÃ¢â‚¬â„¢mah, S.Ag</div>\r\n<div>\r\n<b>Pengawas UPK Periode\r\n2007 s/d 2008</b></div>\r\n<div>\r\nKetua&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; :\r\nH. Abd. Hayyi Said BA</div>\r\n<div>\r\nAnggota&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : Marsus, S.Ag</div>\r\n<div>\r\nAnggota&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : Abdul Mannan, S.Ag</div>\r\n<div>\r\n<br></div>\r\n<div>\r\n<b>Pengawas UPK Periode\r\n2009 s/d 2010</b></div>\r\n<div>\r\nKetua&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; :\r\nDrs. Hilman Muchtar</div>\r\n<div>\r\nAnggota&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : Asrianto</div>\r\n<div>\r\nAnggota&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : M. Idris</div>\r\n<div>\r\n<br></div>\r\n<div>\r\n<b>Pengawas UPK Periode\r\n20</b><b>10</b><b> s/d 201</b><b>1</b></div>\r\n<div>\r\nKetua&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; :\r\nDrs. Hilman Muchtar</div>\r\n<div>\r\nAnggota&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : Asrianto</div>\r\n<div>\r\nAnggota&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : M. Idris</div>\r\n<div>\r\n<br></div>\r\n<div>\r\n<b>Pengurus UPK Periode\r\n2007 s/d 2009</b></div>\r\n<div>\r\nKetua&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; :\r\nMuhammad Zubair</div>\r\n<div>\r\nSekretaris&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : Lukman</div>\r\n<div>\r\nBendahara&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : Rahmawati, S.Ag</div>\r\n<div>\r\n<br></div>\r\n<div>\r\n<b>Pengurus UPK Periode\r\n20</b><b>09</b><b> s/d 201</b><b>1</b></div>\r\n<div>\r\nKetua&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; :\r\nMuhammad Zubair</div>\r\n<div>\r\nSekretaris&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : Lukman</div>\r\n<div>\r\nBendahara&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : Kasma Indah, S.Pd</div>\r\n<div>\r\n<br></div>\r\n<div>\r\n<b>Pengurus UPK Periode\r\n201</b><b>1</b><b> s/d 201</b><b>5</b></div>\r\n<div>\r\nKetua&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; :\r\nLukman&nbsp; HR</div>\r\n<div>\r\nSekretaris&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : Naswar, S.Pd</div>\r\n<div>\r\nBendahara&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; : Kasma Indah, S.Pd</div>\r\n<div>\r\n<br></div>\r\nSelama\r\nperiode 2003 s/d sekarang, Unit Pengelola Kegiatan (UPK) ini telah mengelola\r\ndana program yang diterima dalam bentuk Bantuan Langsung Masyarakat (BLM) dan\r\ndisalurkan langsung kepada masyarakat untuk kegiatan pembangunan prasarana\r\ndesa, kegiatan usaha ekonomi produktif (UEP) dan Simpan Pinjam Khusus Perempuan\r\n(SPP), kegiatan pendidikan dan kegiatan kesehatan<br>', 2, 2, 'P');
INSERT INTO `news` VALUES (5, '2016-01-20 22:22:20', 'Pentingnya SI UPK Onine', 'Pentingnya SI UPK Onine.jpg', 'Sebagaimana sambuatan PJOKab Kabupaten Magelang yang akarab dipanggil Bu Nia, menyampaiakan sudah saatnya para UPK berfikir dan mencari /menerapkan Sistem informasi dan Pelaporan sehingga memudahkan kerja administrasi dan pelaporan yang dikelola selama ini.<br>Menanggapi hal tersebut PT. Asta Brata Teknologi memberikan tawaran SI UPK Online yang menghasilkan out put berupa laporan pembukuan (bisa memilih) standar PTO maupun Double Entry sebagai solusi melakukan pencatatan cepat akurat dan modern.<br>', 1, 241, 'P');
INSERT INTO `news` VALUES (6, '2016-04-12 13:43:40', 'PNPM', 'PNPM.png', '<b>PNPM Mandiri Perdesaan</b> Ã¢â‚¬â€Program Nasional Pemberdayaan Masyarakat \r\nMandiri Perdesaan (PNPM Mandiri Perdesaan atau PNPM-Perdesaan atau Rural\r\n PNPM)Ã¢â‚¬â€ merupakan salah satu mekanisme program pemberdayaan masyarakat \r\nyang digunakan PNPM Mandiri dalam upaya mempercepat penanggulangan \r\nkemiskinan dan perluasan kesempatan kerja di wilayah perdesaan. PNPM \r\nMandiri Perdesaan mengadopsi sepenuhnya mekanisme dan prosedur Program \r\nPengembangan Kecamatan (PPK) yang telah dilaksanakan sejak 1998. PNPM \r\nMandiri sendiri dikukuhkan secara resmi oleh Presiden RI pada 30 April \r\n2007 di Kota Palu, Sulawesi Tengah.<br>', 56, 648, 'P');
INSERT INTO `news` VALUES (7, '2016-04-12 13:46:37', 'PNPM', 'PNPM.png', '<b>PNPM Mandiri Perdesaan</b> Ã¢â‚¬â€Program Nasional Pemberdayaan Masyarakat \r\nMandiri Perdesaan (PNPM Mandiri Perdesaan atau PNPM-Perdesaan atau Rural\r\n PNPM)Ã¢â‚¬â€ merupakan salah satu mekanisme program pemberdayaan masyarakat \r\nyang digunakan PNPM Mandiri dalam upaya mempercepat penanggulangan \r\nkemiskinan dan perluasan kesempatan kerja di wilayah perdesaan. PNPM \r\nMandiri Perdesaan mengadopsi sepenuhnya mekanisme dan prosedur Program \r\nPengembangan Kecamatan (PPK) yang telah dilaksanakan sejak 1998. PNPM \r\nMandiri sendiri dikukuhkan secara resmi oleh Presiden RI pada 30 April \r\n2007 di Kota Palu, Sulawesi Tengah.<br>', 56, 648, 'P');
INSERT INTO `news` VALUES (8, '2016-04-12 13:43:22', 'Uji Coba program', 'Uji Coba program.jpg', 'Acara BIMTEK UPK Kec. Kromengan yang dilaksanakan pada tanggal 12-13 April 2016 di Hotel DW Kepanjen.<br>', 65, 765, 'N');
INSERT INTO `news` VALUES (10, '2016-06-24 19:21:19', 'Pendampingan Kelompok SPP Desa Tamblang (UPK Kubutambahan)', 'Pendampingan Kelompok SPP Desa Tamblang (UPK Kubutambahan).jpg', 'Mengawali pengajuan proposal usulan kelompok SPP di Desa Tamblang (UPK.Kubutambahan), petugas pendampingan dari <b><i>UPK Kubutambahan</i></b> harus sabar dan teliti mendampingi kelompok pengusul,,,wala<br>upun mereka sudah berkali-kali sebagai kelompok binaan,,,maklum kalangan masyarakat menengah kebawah<i>,SDM terbatas</i>,,,<b></b><br>', 78, 948, 'P');
INSERT INTO `news` VALUES (11, '2016-06-26 08:55:06', 'Tim Verifikasi UPK Kubutatambahan', '', 'Tim Verifikasi UPK Kubutatambahan; amati (automatically means and trick indikator), cermati (care equality rational modul and trick indikator), selidiki (search lie data indikator kib)***<br>', 78, 950, 'P');
INSERT INTO `news` VALUES (12, '2016-07-04 00:00:20', 'SOP Selidiki Olah Pancing', '', '<h3><b>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; STANDARD\r\nOPERASIONAL DAN PROSEDUR</b><b>&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;  &nbsp; &nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; (SOP)</b></h3><h3>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; <b>TIM\r\nVERIFIKASI</b></h3><h3>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;  <b>UPK\r\nKubutambahan, Buleleng-Bali</b><br></h3><span>1.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\nTim verifikasi menyiapkan kunjungan lapangan sesuai\r\njadwal yang sudah ditentukan berupa; <br></span>&nbsp;&nbsp;\r\n\r\n<span>&nbsp; &nbsp; &nbsp; &nbsp; a. Proposal\r\nusulan kelompok yang sudah medapatkan pendampingan oleh UPK dan diberikan <b><i>disposisi\r\n</i></b>Ã¢â‚¬Å“layak diverifikasiÃ¢â‚¬Â.<br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp;</span> <span>b.Catatan UPK tentang jejak rekam\r\nkelompok, berupa;<br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; </span>i .Surat Pengukuhan Kepala Desa &nbsp;minimal berusia 1 (satu) tahun, bagi kelompok\r\nbaru.<br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ii.Riwayat pinjaman sebelumnya, bagi\r\nkelompok lama<br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; c. Daftar\r\nkesepakatan kunjungan dengan kelompok pengusul; (waktu dan tempat).\r\n\r\n<span><br>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;d.Surat pemberitahuan kepada\r\nPemdes setempat,tentang rencana kunjungan Tim Verifikasi pada kelompok pengusul\r\ndan atau setidak tidaknya melapor kepada Pemdes setempat dengan mengisi Buku\r\nTamu Kantor Desa pada saat kunjungan sebagai bukti. &nbsp;</span>&nbsp;\r\n\r\n<br>2.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\nTim Verifikasi melaksanakan kunjungan lapangan kepada\r\nkelompok pada hari dan jam kerja, kecuali&nbsp;\r\nberdasarkan kesepakatan dengan kelompok pengusul atas sepengetahuan dan\r\nijin aparat pemdes setempat.&nbsp;\r\n\r\n<br><span>3.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\nKunjungan lapangan oleh Tim Verifikasi\r\ndlaksanakan sejak proposal usulan kelompok sudah mendapat pendampingan dan\r\ndiberi <i>disposisi</i> layak diverifikasi\r\ns/d tanggal 15&nbsp; pada bulan bersangkutan.</span>\r\n\r\n&nbsp;\r\n\r\n<br>4.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\nKelompok yang di lakukan verifikasi lapangan /\r\nkunjungan lapangan berkumpul di rumah salah satu pengurus atau anggota\r\nkelompok, Balai Kelompok, Balai Dusun, &nbsp;Balai Desa atau tempat umum lain yang disepakati\r\ndan dihadiri oleh pengurus beserta anggota kelompoknya.\r\n\r\n&nbsp;\r\n\r\n<br>5.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\nTim verifikasi dapat melakukan wawancara jika\r\nseluruh pengurus beserta seluruh anggota pemanfaat dan atau sedikitnya 2/3 &nbsp;anggota kelompok hadir.\r\n\r\n&nbsp;\r\n\r\n<br>6.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\nIsi dari wawancara berupa pertanyaan mendasar sebagai\r\nberikut :\r\n\r\n<br>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;a. Nama\r\ndan kedudukan kelompok.\r\n\r\n<br>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;b. Kelengkapan administrasi\r\nkelompok (AD/ART dan buku administrasi kelompok).\r\n<br>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;c. Kelengkapan\r\npengurus kelompok (ketua, sekretaris dan bendahara)&nbsp;&nbsp;\r\n\r\n&nbsp;  <br>&nbsp; &nbsp; &nbsp;&nbsp; &nbsp;&nbsp; d. Rutinitas pertemuan dan\r\nkegiatan/usaha kelompok.\r\n<br>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;&nbsp; e. Akurasi dan identifikasi;<br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; i.&nbsp; Identitas masing- masing anggota pemanfaat.\r\n<br>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; ii.&nbsp; Realitas\r\nbesaran pinjaman masing- masing anggota pemanfaat.\r\n<br>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; iii. Kapabilitas usaha masing- masing anggota pemanfaat.<br>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; f.&nbsp; Rekam\r\njejak pinjaman kelompok sebelumnya, bagi kelompok lama.\r\n<br>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;g. Penyebab\r\nmasalah bagi kelompok yang sebelumnya mengalami pinjaman bermasalah.\r\n\r\n&nbsp;\r\n<br>\r\n7.&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;\r\nMelaksanakan Rapat akhir rekomendasi Tim\r\nVerifikasi, untuk menentukan;\r\n<br>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;a. Validasi\r\nkeabsahan dan rekam jejak kelompok.\r\n\r\n<br>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp;b.Validasi besar pinjaman dan\r\nkemampuan angsuran masing masing anggota pemanfaat\r\n<br>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp;  c. Validasi\r\ndan kelayakan besaran pinjaman kelompok\r\n\r\n&nbsp;\r\n\r\n&nbsp;\r\n<br>\r\n<br>Ditetapkan di&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; :\r\nKubutambahan\r\n\r\n<br>Padatanggal&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; :&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Mei 2016&nbsp;\r\n\r\n<br>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;  &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Ketua BKAD\r\n<br>\r\n&nbsp;\r\n<br>&nbsp;&nbsp;\r\n&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;  &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp;&nbsp; (I Made Sumebawa)\r\n\r\n<br>&nbsp;&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; Mengetahui\r\n:\r\n\r\n<br>&nbsp;&nbsp; &nbsp; &nbsp; Camat\r\nKubutambahan<br>&nbsp;<br>&nbsp;\r\n\r\n<b><u>Drs.&nbsp; Komang Sumertajaya</u></b>\r\n\r\n<br>&nbsp;&nbsp;  NiP.\r\n1940311\r\n198503 1017\r\n\r\n<br><br>', 78, 948, 'P');
INSERT INTO `news` VALUES (13, '2016-07-22 13:27:17', 'INFORMASI TERBARU', 'INFORMASI TERBARU.jpg', 'UNTUK INFORMASI TERBARU UPK ROWOKANGKUNG SILAHKAN BERKUNJUNG KE <a rel=\"\" target=\"\" href=\"http://upkrowokangkung.blogspot.com/\">http://upkrowokangkung.blogspot.com/</a><br><br>', 40, 494, 'P');
INSERT INTO `news` VALUES (14, '2016-09-26 13:45:22', 'DESAKU YANG PERMAI', 'DESAKU YANG PERMAI.jpg', 'Nun jauh dari suara bising mesin, diriku mengenal indahnya alam yang diciptakan sebagai deretan khatulistiwa yang terhampar di muka bumi ini. Dari sana pula diriku mengenal keunikan pancaran mentari pagi di ufuk dan cakrawala yang selalu nampak menguning di kala senja. Tak terlupakan pula riangnya berbagai burung kecil yang terbang kian kemari mencari sebutir padi yang mulai menguning di pagi dan siang hari.<br>Desaku.......<br>Suatu tempat yang indah permai tiada terlupakan sampai kapanpun karena keindahan dan kedamaian nurani. Tak pernah sedikit waktupun alpa mengingat-Mu pada ciptaan yang indah penuh makna yang Engkau anugerahkan......<br><br>&nbsp;<br>', 82, 990, 'P');
INSERT INTO `news` VALUES (15, '2016-10-12 01:04:46', 'Bimbingan Teknis Pemakaian Aplikasi Laporan Keuangan SI UPK Online', 'Bimbingan Teknis Pemakaian Aplikasi Laporan Keuangan SI UPK Online.jpg', 'Sebulan Aplikasi Laporan SI UPK Online di UPK Kawedanan Magetan telah diterapkan, karena telah diluncurkan dan dilaksanakan di Kawedanan per 1 September 2016. Langkah demi langkah dilalui dengan penuh keseriusan, dengan prinsip \"kesalahan adalah awal dari keberhasilan\". Demikian pula dengan Pengurus UPK Kawedanan tidak mengenal lelah memecahkan sebuah aplikasi yang sebelumnya tak pernah diketahui.<br>Dengan bantuan Whatsapp, Tim Teknis Astabrata, Magelang dengan setia menemani dan memberikan instruksi bagaimana seharusnya, hingga akhirnya tuntas dapat menjalankan sebuah Aplikasi Laporan Keuangan Dana Bergulir yang dikelola oleh UPK Kawedanan.<br>Namun dengan penuh semangat bersama dengan teman senasib seperjuangan, pada hari Selasa dan Rabu tertanggal 11 dan 12 Oktober 2016, mengikuti Bimbingan lansung dari Tim Astabrata di SMKN 1 Magetan. Semoga dapat bermanfaat bagi semuanya...... aamiin...!<br>', 82, 990, 'P');
INSERT INTO `news` VALUES (16, '2016-10-13 10:28:00', 'Tayang Perdana SI UPK online nguntoronadi.upkmagetan.com', '', 'Salam semangat pagi!!!!!<br><br>Alhamdulillah UPK Istiqomah Kecamatan Nguntoronadi telah online. Kemarin tanggal 11 s/d 12 Oktober 2016 telah dilaksanakan pelatihan SI UPK Online di SMKN 1 Magetan dengan narasumber dari Tim Asta Brata Teknologi Magelang.<br>Seluruh masyarakat sudah bisa mengakses UPK Istiqomah Nguntoronadi secara online di alamat nguntoronadi.upkmagetan.com.<br>Semoga layanan ini bisa menambah kualitas pelayanan kami kepada masyarakat.<br>Kami mengharap saran dan kritik yang membangun dari anda semua.<br>Terima Kasih<br>Salam Pemberdayaan', 84, 1016, 'P');
INSERT INTO `news` VALUES (17, '2016-10-18 11:56:12', 'Bintek penerapan aplikasi pelaporan keuangan dan pengelolaan pinjaman berbasis online', 'Bintek penerapan aplikasi pelaporan keuangan dan pengelolaan pinjaman berbasis online.jpg', 'Pada tanggal 14 - 15 Oktober 2016, BKAD Bina Sejahtera Kecamatan Kajoran telah melaksanakan Bintek penerapan aplikasi SIUPKONLINE sebagai tindak lanjut MOU yang telah ditandatangani pada Tanggal 15 September 2015 dengan PT Astra Brata Teknologi. Bintek ini diikuti oleh seluruh kelembagaan yang ada di Kecamatan kajoran dengan jumlah peserta 20 orang yang terdiri dari 3 orang PH-BKAD, 3 orang BP-UPK, 4 orang Tim Pendanaan, 3 orang Tim Verifikasi, 6 orang Pengurus UPK dan Kasi PMD Kecamatan Kajoran selaku Penanggungjawab operasional.<br>Bintek ini dibuka secara resmi oleh Camat Kajoran Bp Drs H Basirul Hakim. Beliau mengatakan bahwa dalam pengelolaan kegiatan simpan pinjam pasca PNPM-MPd berakhir, diperlukan kekompakan dan kebersamaan tim agar dana yang ada sampai dengan saat ini bisa tetap lestari. Dengan digunakannya sistim pelaporan dan pengelolaan pinjaman secara online ini, maka pengelolaan yang dilakukan oleh lembaga dapat lebih transparan sesuai dengan salah satu prinsip PNPM-MPd / PPK. <br>', 89, 1077, 'P');
INSERT INTO `news` VALUES (18, '2016-10-25 08:52:28', 'STUDI BANDING KELOMPOK SPP dan KELEMBAGAAN', 'STUDI BANDING KELOMPOK SPP dan KELEMBAGAAN.jpg', 'Selamat pagi.........<br>Salam pemberdayaan!!!<br>Hari Kamis 20 Oktober 2016 UPK Istiqomah Kecamatan Nguntoronadi mengadakan studi banding ke Jejamuran Volva Sleman Jogjakarta. Disana para peserta megetahui dan mempelajari macam-macam jamur,&nbsp;cara budidaya jamur, pemasaran jamur dan pengolahan jamur menjadi makanan.<br>Semoga bermanfaat!!!<img alt=\"\" src=\"http://\"><br><br>', 84, 1016, 'P');
INSERT INTO `news` VALUES (19, '2016-11-22 11:31:44', 'VERIFIKASI BANSOS UPK DESA WUKIRSARI', 'VERIFIKASI BANSOS UPK DESA WUKIRSARI.jpg', 'Pada hari Selasa, 22 Nopember 2016 Verifikasi Bansos UPK memanfaatkan Surplus UPk tahun 2015 telah dilaksanakan dengan penerima manfaat sebanyak 18 KK tersebar di 18 pedukuhan.<br>mayoritas usulan berupa MCK <br>', 92, 1130, 'P');
INSERT INTO `news` VALUES (20, '2016-11-22 10:47:56', 'Pameran Produk Binanan Eks-PNPM dalam rangka Bulan Bakti Gotong Royong Magetan 2016', 'Pameran Produk Binanan Eks-PNPM dalam rangka Bulan Bakti Gotong Royong Magetan 2016.jpg', 'Pada tanggal 22 Nopember 2016 Bapermas dan Pemdes Magetan mengadakan kegiatan Bulan Bakti Gotong Royong Magetan dengan menampilkan berbagai acara antara lain lomba melukis anak-anak, hiburan dongkrek dari anak berkebutuhan khusus, stand pameran per kecamatan dengan tema teknologi tepat guna.<br>Asosiasi UPK Magetan menampilkan stand pameran produk hasil binaan UPK. Pagi hari acara pembukaan dan beberapa kegiatan dihadiri oleh Bupati Magetan. Untuk lembaga dan ke UPK-an ada penyerahan penghargaan dari hasil Monev tanggal 1-20 Nopember 2016. <br>UPK Nguntoronadi mendapat penghargaan Kelembagaan terbaik se-Kabupaten Magetan.<br>Pameran ditutup dengan pentas Wayang Kulit dengan dalan Kepala Basarnas.<br>', 84, 1016, 'P');
INSERT INTO `news` VALUES (21, '2016-12-06 21:18:33', 'VERIFIKASI UPK KUBUTAMBAHAN ', 'VERIFIKASI UPK KUBUTAMBAHAN .jpg', 'Kegiatan verifikasi TV UPK Kubutambahan,Buleleng-Bali di penghujung Tahun 2016,dilaksanakan bersamaan dengan kegiatan Pendampingan kelompok pada minggu pertama.<br>Berdasarkan proposal pengajuan pinjaman kelompok yang masuk ke UPK Kubutambahan berjumlah 5&nbsp; buah Proposal usulan kelompok di 4 desa dari total 13 desa yang ada di wilayah Kecamatan Kubutambahan, Kabupaten Buleleng - Bali. <br>Total jumlah pinjaman sebesar Rp. 419.000.000,-(empat ratus sembilan belas juta rupiah)<br>', 78, 948, 'P');
