INSERT INTO `update_fitur` VALUES (1, '2016-08-16 07:57:17', 'Perubahan dasar target angsuran', 'Terdapat perubahan fitur pada target angsuran, semula target angsuran berdasarkan pergantian bulan berubah menjadi berdasarkan tanggal cair, kecuali pada Jurnal Angsuran. ', '', 4, 'R');
INSERT INTO `update_fitur` VALUES (2, '2016-08-16 08:09:07', 'Penambahan fitur Jenis skema Jasa', 'Terdapat penambahan fitur Jenis skema Jasa yaitu Flat (Bunga Tetap), Efektif (Bunga Menurun, Pokok Tetap), dan Anuitas (Bunga Menurun, Pokok Berubah) ', '2.png', 2, 'R');
INSERT INTO `update_fitur` VALUES (3, '2016-09-20 20:46:38', 'Legalisasi Dokumen', ' Terdapat perubahan fitur Tanda Tangan Laporan dan Penandatangan SPK, untuk mengaturnya silahkan klik Pengaturan/Personalisasi SOP/Legalisasi Dokumen.', '3.png', 3, 'R');
INSERT INTO `update_fitur` VALUES (4, '2016-09-20 20:46:38', 'Penomoran SPK', ' Terdapat perubahan fitur Penomoran SPK. Pada saat waiting list, anda harus memasukkan nomor SPK untuk membuat dokumen pencairan.', '4.png', 1, 'R');
INSERT INTO `update_fitur` VALUES (5, '2016-11-16 20:55:20', 'Penambahan Form Nama Lembaga', 'Sehubungan terdapat beberapa UPK pengguna SI UPK Online yang telah mendapatkan payung hukum dan telah berubah nama lembaganya, kami tambahkan fitur pada personalisasi SOP untuk mengatur nama lembaga sesuai dengan payung hukumnya, seperti UPK-DAPM, Perkumpulan DAPM, Bumdes Bersama, Koperasi, PT, dll.', '', 5, 'R');
INSERT INTO `update_fitur` VALUES (6, '2016-11-17 16:53:27', 'Cetak Rekening Koran', 'Terdapat penambahan fitur cetak rekening koran riwayat transaksi angsuran kelomppok. <br>\r\nDapat melalui Menu jurnal angsuran, pilih kelompok, klik tombol cetak rekening koran pada buku transaksi kelompok.<br>\r\nAtau dapat melalui menu pinjaman aktif, pilih kelompok, klik riwayat transaksi, klik tombol cetak rekening koran pada buku transaksi kelompok.', '', 3, 'R');
INSERT INTO `update_fitur` VALUES (7, '2016-11-18 22:22:34', 'Quick Access Groups Statistic', 'Penambahan fitur tombol quick access untuk mencetak beberapa data statistik kelompok seperti Data kelompok aktif, proposal, verified, waiting list, tagihan hari ini, tunggakan, dan agenda pencairan.', '7.png', 2, 'R');
INSERT INTO `update_fitur` VALUES (8, '2016-12-05 08:30:36', 'SPK Anggota', 'Terdapat Penambahan fitur cetak SPK by Anggota Pemanfaat melalui Waiting List/Pinjaman Aktif, klik Kelompok, klik tab Daftar Pemanfaat.<br>\nBagi UPK yang belum menerapkan SPK by Name mohon diabaikan.<br>\nTerimakasih.', '8.png', 3, 'R');
