INSERT INTO `web_request` VALUES (1, '2016-02-03 14:17:00', 'Gunawan Yedi', 'gunawanyedi@gmail.com', '0', 1, '0', '1. maaf admin, saya mau tanya kalau si upk online ini sudah sesuai dengan keadaan yang sekarang tidak?sebab BLM kan dahtidak ada, lgsg ke desa.<br>\n2. kira\" kalau kami berminat, maharnya berapa untuk aplikasi ini?\nterima kasih', 'Sudah dilakukan konfirmasi dengan tanggapan 11 Maret 2016 (08.29) ;\n\"oh ya pa...rencana bulan ini kami mau bahas RAPB UPK nya, sudah kami anggarkan, selesai insyaAlloh lgsg sya hubungi\"\n\nPenjelasan ttg fasilitas dan harga online offline ;\nSetup, 12,5 jt dengan biaya perawatan tahunan (sistem remot setiap kali dibutuhkan penanganan dan update oleh kami) sebesar 1,5 jt per tahun. atau kami layani dengan paket jual lepas garansi 3 bulan dengan harga 17,5 jt (akan dikenakan biaya adcost apabila terjadi error sistem/data akibat kerusakan komputer, virus maupun kesalahan input data)\n												\n												');
INSERT INTO `web_request` VALUES (2, '2016-02-04 10:10:00', 'Asep Suhaya', 'a.suhana@yahoo.co.id', '0', 1, 'Darmaraja Sumedang', 'Yth. pengelola SIUPKONLINE.COM<br>\r\nKami adalah pengurus BKAD Kecamatan darmaraja Kabupaten Sumedang<br>\r\nDalam hal in mau menanyakan harga dan keunngulan aplikasi siupk online, untuk merubah pembukuan laporan keuangan upk dari yang single entry ke doble entry, serta laporan lain dalam rangka pengembangan dan plestarian dana bergulir yang di kelola UPK.....<br>\r\ndemikian terima kasih.', 'coba ini di follow up...');
