INSERT INTO `web_request` VALUES (14, '2016-02-23 14:31:00', 'Ade warnedi', 'upkpagadensubang@gmail.com', '081321411032', 1, 'Kecamatan Pagaden Kabupaten Subang Provinsi Jawabarat', 'harga net berapa', 'Presentasi sudah dilakukan oleh Tim Marketing P. Rasidin dari Purwakarta dihadapan 12 UPK, sehingga komunikasi diserahkan/ditekel \n\noleh ybs.\nHarga kita buat net sebagaimana Penawaran OL dengan fee marketing plus sebesar 15%.\n\nP Rasidin sedang burgaining dengan Ketua Asosiasi UPK\n												');
INSERT INTO `web_request` VALUES (15, '2016-03-11 09:02:58', 'Santoso', '0', '085292226282', 19, 'Kabupaten Magelang Jawa Tengah', 'Fasilitas apa saja yang memudahkan Tim Kabupaten menjalin komunikasi dan melakukan monitoring perkembangan tingkat kabupaten dan kecamatan dalam pengelolaan asset ekonomi dan non ekonomi?', 'Konfirmasi yang kesekian kalinya di tgl 10/3/2016 ;\nSugeng siang Pak ..., mhn info barangkali sudah ada progres diluar surat? karena ternyata surat di sebagian UPK belum menjadi pembahasan bersama (Tim UPK dengan kelembagaannya serta apa RKTLnya)\n\nOh iya dengan SI UPK Online kami, nanti kabupaten bisa langsung control updatenya  per transaksi perkecamatan kecamatan tdk harus menunggu UPK berkirim laporan atau email setiap bulan atau setiap diperlukan\n\nMhn maaf pak barangkali saya bisa dapat kiriman scan suratnya biar saya coba jadikan bahan komunikasi gerilya\n\nHasil Konfirmasi ;\nBentar mas..ni mmg perlu proses.. Brngkali surat jg msh di Camat bkum disposidi...n mmg perlu advokasi minggu k depan scra bertahap akn..ada plthan bumdes kpd semua kasie..nti sy sisipkn tentng hak n peran desa dlm transparansi..serta sy minta bpermas rakor camat untk sy pertegas...nti juga sy gerilya respon upk n bkad..\n												\n												');
INSERT INTO `web_request` VALUES (16, '2016-03-11 09:56:44', 'Rifai Lobok', 'pnpmmpd.mtgading@yahoo.com', '085292226282', 4, 'Matagading Kab. Bima', 'Contak lebih lancar pakai FB', 'Konfirmasi yang kesekian kalinya di tgl 11/3/2016 ;\n\nSelamat Pagi Pak Rifai Lombok, salam sukses dan semoga sehat selalu. Mohon perkenan untuk dapat berbagi informasi tentang tanggapan dan persiapan Rekan-rekan UPK dalam menuju implementasi SI UPK Online sebagaimana penawaran yang kami ajukan, apabila menghendaki versi Offline kami juga telah menyediakan menu downloadnya di www.siupkonline.com , terimakasih\n\nJawaban ;\nUntuk sementara teman2 masih menggunakan aplikasi yg ada... Demo belum di coba\n\nKonfirm lanjutan;\nOk, barangkali sebagai bahan pertimbangan kami persilahkan dilakukan uji coba sehingga bisa menemukan sisi kelemahan aplikasi kami dan kemudahan serta kecepatan melakukan verifikasi data serta transaksi hingga menjadi sebuah dokumen proposal/dokumen pencairan/bukti transaksi maupun pelaporan keuangan yang diperlukan,\n\nNjempo\n												');
