  `id` int NOT NULL AUTO_INCREMENT,
  `unit` varchar(1) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL DEFAULT '1' COMMENT 'Dana Bergulir (1), Sektor Riil (2), Penjaminan (3), UPK-Pay (4), Minimarket (5), Apotek (6)',
  `posisi` varchar(1) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL COMMENT 'Aktiva (1), Hutang(2), Modal (3), Pendapatan (4), Biaya (5)',
  `kd_jr` varchar(2) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `kd_jb` varchar(25) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `ins` varchar(3) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `nama_jb` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `icon` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `ap` int NOT NULL DEFAULT 0 COMMENT 'Apakah termasuk Aset Produktif (Kas, Bank, Produk). Ya(1), Tidak (0)',
  `file` varchar(50) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `lokasi` varchar(210) CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `kd_kab` int NOT NULL DEFAULT 0,
  `kecuali` text CHARACTER SET latin1 COLLATE latin1_swedish_ci NOT NULL,
  `akun` varchar(60) CHARACTER SET latin1 COLLATE latin1_swedish_ci NULL DEFAULT NULL,
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `unit`(`unit`, `posisi`, `kd_jr`, `kd_jb`, `ins`) USING BTREE,
  INDEX `kd_kab`(`kd_kab`) USING BTREE,
  INDEX `lokasi`(`lokasi`) USING BTREE,
  INDEX `nama_jb`(`nama_jb`) USING BTREE,
  FULLTEXT INDEX `kecuali`(`kecuali`)
) ENGINE = MyISAM AUTO_INCREMENT = 272 CHARACTER SET = latin1 COLLATE = latin1_swedish_ci ROW_FORMAT = Dynamic;

